{"command":"cd /workspace; mkdir -p src/lua; cat > .gitignore <<'EOF'
/target
/executable
*.o
EOF
cat > src/lua/lexer.rs <<'EOF'
//! Lua 5.4 compatible lexer.

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Name(String),
    Str(Vec<u8>),
    Int(i64),
    Flt(f64),
    // keywords
    And, Break, Do, Else, Elseif, End, False, For, Function, Goto, If, In, Local, Nil, Not, Or,
    Repeat, Return, Then, True, Until, While,
    // symbols
    Plus, Minus, Star, Slash, DSlash, Percent, Caret, Hash, Amp, Tilde, Pipe, Shl, Shr,
    Eq, Ne, Le, Ge, Lt, Gt, Assign, LParen, RParen, LBrace, RBrace, LBracket, RBracket,
    DColon, Semi, Colon, Comma, Dot, Concat, Dots,
    Eof,
}

#[derive(Clone, Debug)]
pub struct Token {
    pub tok: Tok,
    pub line: u32,
    /// raw text of the token as it appeared in the source (for error messages)
    pub raw: Vec<u8>,
}

pub struct LexError {
    pub msg: String,
    pub line: u32,
    /// text to show after "near" (already quoted when needed); None means no "near" part
    pub near: Option<String>,
}

pub fn token_desc(tok: &Tok, raw: &[u8]) -> String {
    match tok {
        Tok::Name(_) | Tok::Str(_) | Tok::Int(_) | Tok::Flt(_) => {
            format!("'{}'", String::from_utf8_lossy(raw))
        }
        Tok::Eof => "<eof>".to_string(),
        _ => format!("'{}'", tok_text(tok)),
    }
}

pub fn tok_text(tok: &Tok) -> &'static str {
    match tok {
        Tok::And => "and", Tok::Break => "break", Tok::Do => "do", Tok::Else => "else",
        Tok::Elseif => "elseif", Tok::End => "end", Tok::False => "false", Tok::For => "for",
        Tok::Function => "function", Tok::Goto => "goto", Tok::If => "if", Tok::In => "in",
        Tok::Local => "local", Tok::Nil => "nil", Tok::Not => "not", Tok::Or => "or",
        Tok::Repeat => "repeat", Tok::Return => "return", Tok::Then => "then", Tok::True => "true",
        Tok::Until => "until", Tok::While => "while",
        Tok::Plus => "+", Tok::Minus => "-", Tok::Star => "*", Tok::Slash => "/", Tok::DSlash => "//",
        Tok::Percent => "%", Tok::Caret => "^", Tok::Hash => "#", Tok::Amp => "&", Tok::Tilde => "~",
        Tok::Pipe => "|", Tok::Shl => "<<", Tok::Shr => ">>", Tok::Eq => "==", Tok::Ne => "~=",
        Tok::Le => "<=", Tok::Ge => ">=", Tok::Lt => "<", Tok::Gt => ">", Tok::Assign => "=",
        Tok::LParen => "(", Tok::RParen => ")", Tok::LBrace => "{", Tok::RBrace => "}",
        Tok::LBracket => "[", Tok::RBracket => "]", Tok::DColon => "::", Tok::Semi => ";",
        Tok::Colon => ":", Tok::Comma => ",", Tok::Dot => ".", Tok::Concat => "..", Tok::Dots => "...",
        Tok::Eof => "<eof>",
        Tok::Name(_) => "<name>", Tok::Str(_) => "<string>", Tok::Int(_) => "<integer>", Tok::Flt(_) => "<number>",
    }
}

fn keyword(s: &str) -> Option<Tok> {
    Some(match s {
        "and" => Tok::And, "break" => Tok::Break, "do" => Tok::Do, "else" => Tok::Else,
        "elseif" => Tok::Elseif, "end" => Tok::End, "false" => Tok::False, "for" => Tok::For,
        "function" => Tok::Function, "goto" => Tok::Goto, "if" => Tok::If, "in" => Tok::In,
        "local" => Tok::Local, "nil" => Tok::Nil, "not" => Tok::Not, "or" => Tok::Or,
        "repeat" => Tok::Repeat, "return" => Tok::Return, "then" => Tok::Then, "true" => Tok::True,
        "until" => Tok::Until, "while" => Tok::While,
        _ => return None,
    })
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    line: u32,
}

fn is_name_start(c: u8) -> bool { c.is_ascii_alphabetic() || c == b'_' }
fn is_name_char(c: u8) -> bool { c.is_ascii_alphanumeric() || c == b'_' }

/// Format a raw buffer for a "near" clause like Lua does for buffered tokens.
fn quote_raw(raw: &[u8]) -> String {
    format!("'{}'", String::from_utf8_lossy(raw))
}

/// Lua's luaX_token2str for a single character.
pub fn char_desc(c: u8) -> String {
    if c.is_ascii_graphic() || c == b' ' {
        format!("'{}'", c as char)
    } else {
        format!("'<\\{}>'", c)
    }
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        let mut l = Lexer { src, pos: 0, line: 1 };
        // skip shebang line
        if src.starts_with(b"#") {
            while l.pos < src.len() && src[l.pos] != b'\n' { l.pos += 1; }
        }
        l
    }

    fn peek(&self) -> Option<u8> { self.src.get(self.pos).copied() }
    fn peek2(&self) -> Option<u8> { self.src.get(self.pos + 1).copied() }

    fn err(&self, msg: &str, near: Option<String>) -> LexError {
        LexError { msg: msg.to_string(), line: self.line, near }
    }

    fn inc_line(&mut self) {
        // handles \n, \r, \r\n, \n\r
        let c = self.src[self.pos];
        self.pos += 1;
        if let Some(n) = self.peek() {
            if (n == b'\n' || n == b'\r') && n != c { self.pos += 1; }
        }
        self.line += 1;
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, LexError> {
        let mut out = Vec::new();
        loop {
            let t = self.next_token()?;
            let eof = t.tok == Tok::Eof;
            out.push(t);
            if eof { break; }
        }
        Ok(out)
    }

    fn skip_long_bracket_level(&mut self) -> Option<usize> {
        // at '[', returns level if a valid long bracket opener, consuming it
        let start = self.pos;
        debug_assert!(self.src[self.pos] == b'[');
        let mut p = self.pos + 1;
        let mut level = 0;
        while p < self.src.len() && self.src[p] == b'=' { level += 1; p += 1; }
        if p < self.src.len() && self.src[p] == b'[' {
            self.pos = p + 1;
            Some(level)
        } else {
            self.pos = start;
            None
        }
    }

    fn read_long_string(&mut self, level: usize, is_comment: bool, start_line: u32) -> Result<Vec<u8>, LexError> {
        // we are just after the opening bracket
        // skip first newline
        if let Some(c) = self.peek() {
            if c == b'\n' || c == b'\r' { self.inc_line(); }
        }
        let mut buf = Vec::new();
        loop {
            match self.peek() {
                None => {
                    let what = if is_comment { "comment" } else { "string" };
                    return Err(self.err(&format!("unfinished long {} (starting at line {})", what, start_line), Some("<eof>".into())));
                }
                Some(b']') => {
                    // check closing
                    let mut p = self.pos + 1;
                    let mut l = 0;
                    while p < self.src.len() && self.src[p] == b'=' { l += 1; p += 1; }
                    if l == level && p < self.src.len() && self.src[p] == b']' {
                        self.pos = p + 1;
                        return Ok(buf);
                    }
                    buf.push(b']');
                    self.pos += 1;
                }
                Some(c) if c == b'\n' || c == b'\r' => {
                    buf.push(b'\n');
                    self.inc_line();
                }
                Some(c) => { buf.push(c); self.pos += 1; }
            }
        }
    }

    fn read_string(&mut self, delim: u8) -> Result<Vec<u8>, LexError> {
        // at the opening delimiter
        let start = self.pos;
        self.pos += 1;
        let mut buf = Vec::new();
        loop {
            let c = match self.peek() {
                None => return Err(self.err("unfinished string", Some("<eof>".into()))),
                Some(c) => c,
            };
            if c == delim { self.pos += 1; break; }
            match c {
                b'\n' | b'\r' => {
                    let raw = &self.src[start..self.pos];
                    return Err(self.err("unfinished string", Some(quote_raw(raw))));
                }
                b'\\' => {
                    self.pos += 1;
                    let e = match self.peek() {
                        None => return Err(self.err("unfinished string", Some("<eof>".into()))),
                        Some(e) => e,
                    };
                    match e {
                        b'a' => { buf.push(7); self.pos += 1; }
                        b'b' => { buf.push(8); self.pos += 1; }
                        b'f' => { buf.push(12); self.pos += 1; }
                        b'n' => { buf.push(b'\n'); self.pos += 1; }
                        b'r' => { buf.push(b'\r'); self.pos += 1; }
                        b't' => { buf.push(b'\t'); self.pos += 1; }
                        b'v' => { buf.push(11); self.pos += 1; }
                        b'x' => {
                            self.pos += 1;
                            let mut v: u32 = 0;
                            for _ in 0..2 {
                                match self.peek() {
                                    Some(h) if h.is_ascii_hexdigit() => {
                                        v = v * 16 + (h as char).to_digit(16).unwrap();
                                        self.pos += 1;
                                    }
                                    Some(_) => { self.pos += 1; return Err(self.err("hexadecimal digit expected", Some(quote_raw(&self.src[start..self.pos])))); }
                                    None => return Err(self.err("hexadecimal digit expected", Some("<eof>".into()))),
                                }
                            }
                            buf.push(v as u8);
                        }
                        b'u' => {
                            self.pos += 1;
                            if self.peek() != Some(b'{') {
                                if self.peek().is_none() { return Err(self.err("missing '{'", Some("<eof>".into()))); }
                                self.pos += 1;
                                return Err(self.err("missing '{'", Some(quote_raw(&self.src[start..self.pos]))));
                            }
                            self.pos += 1;
                            let mut v: u64 = 0;
                            let mut n = 0;
                            loop {
                                match self.peek() {
                                    Some(h) if h.is_ascii_hexdigit() => {
                                        v = v * 16 + (h as char).to_digit(16).unwrap() as u64;
                                        n += 1;
                                        self.pos += 1;
                                        if v > 0x7FFF_FFFF {
                                            return Err(self.err("UTF-8 value too large", Some(quote_raw(&self.src[start..self.pos]))));
                                        }
                                    }
                                    Some(b'}') if n > 0 => { self.pos += 1; break; }
                                    Some(_) => {
                                        self.pos += 1;
                                        let m = if n == 0 { "hexadecimal digit expected" } else { "missing '}'" };
                                        return Err(self.err(m, Some(quote_raw(&self.src[start..self.pos]))));
                                    }
                                    None => {
                                        let m = if n == 0 { "hexadecimal digit expected" } else { "missing '}'" };
                                        return Err(self.err(m, Some("<eof>".into())));
                                    }
                                }
                            }
                            utf8_encode(v as u32, &mut buf);
                        }
                        b'\n' | b'\r' => { buf.push(b'\n'); self.inc_line(); }
                        b'\\' | b'"' | b'\'' => { buf.push(e); self.pos += 1; }
                        b'z' => {
                            self.pos += 1;
                            while let Some(w) = self.peek() {
                                if w == b'\n' || w == b'\r' { self.inc_line(); }
                                else if w.is_ascii_whitespace() { self.pos += 1; }
                                else { break; }
                            }
                        }
                        d if d.is_ascii_digit() => {
                            let mut v: u32 = 0;
                            let mut i = 0;
                            while i < 3 {
                                match self.peek() {
                                    Some(d) if d.is_ascii_digit() => { v = v * 10 + (d - b'0') as u32; self.pos += 1; i += 1; }
                                    _ => break,
                                }
                            }
                            if v > 255 {
                                return Err(self.err("decimal escape too large", Some(quote_raw(&self.src[start..self.pos]))));
                            }
                            buf.push(v as u8);
                        }
                        _ => {
                            self.pos += 1;
                            return Err(self.err("invalid escape sequence", Some(quote_raw(&self.src[start..self.pos]))));
                        }
                    }
                }
                _ => { buf.push(c); self.pos += 1; }
            }
        }
        Ok(buf)
    }

    fn read_number(&mut self) -> Result<Tok, LexError> {
        let start = self.pos;
        let mut expo: &[u8] = b"Ee";
        if self.peek() == Some(b'0') && matches!(self.peek2(), Some(b'x') | Some(b'X')) {
            expo = b"Pp";
            self.pos += 2;
        }
        loop {
            match self.peek() {
                Some(c) if expo.contains(&c) => {
                    self.pos += 1;
                    if matches!(self.peek(), Some(b'+') | Some(b'-')) { self.pos += 1; }
                }
                Some(c) if c.is_ascii_hexdigit() || c == b'.' => { self.pos += 1; }
                _ => break,
            }
        }
        // Lua reads any trailing alnum chars into the buffer too (lislalnum) for the error msg
        while let Some(c) = self.peek() {
            if is_name_char(c) || c == b'.' { self.pos += 1; } else { break; }
        }
        let raw = &self.src[start..self.pos];
        match str_to_number(raw) {
            Some(Number::Int(i)) => Ok(Tok::Int(i)),
            Some(Number::Flt(f)) => Ok(Tok::Flt(f)),
            None => Err(self.err("malformed number", Some(quote_raw(raw)))),
        }
    }

    fn next_token(&mut self) -> Result<Token, LexError> {
        loop {
            let c = match self.peek() {
                None => return Ok(Token { tok: Tok::Eof, line: self.line, raw: vec![] }),
                Some(c) => c,
            };
            match c {
                b'\n' | b'\r' => { self.inc_line(); continue; }
                b' ' | b'\t' | 0x0b | 0x0c => { self.pos += 1; continue; }
                b'-' => {
                    if self.peek2() == Some(b'-') {
                        self.pos += 2;
                        // comment
                        if self.peek() == Some(b'[') {
                            let line = self.line;
                            if let Some(level) = self.skip_long_bracket_level() {
                                self.read_long_string(level, true, line)?;
                                continue;
                            }
                        }
                        while let Some(c) = self.peek() {
                            if c == b'\n' || c == b'\r' { break; }
                            self.pos += 1;
                        }
                        continue;
                    }
                    return Ok(self.simple(Tok::Minus, 1));
                }
                _ => {}
            }
            let start = self.pos;
            let line = self.line;
            let tok = match c {
                b'[' => {
                    if let Some(level) = self.skip_long_bracket_level() {
                        let s = self.read_long_string(level, false, line)?;
                        Tok::Str(s)
                    } else if self.peek2() == Some(b'=') {
                        // invalid delimiter like [=x
                        let mut p = self.pos + 1;
                        while p < self.src.len() && self.src[p] == b'=' { p += 1; }
                        self.pos = p;
                        return Err(self.err("invalid long string delimiter", Some(quote_raw(&self.src[start..self.pos]))));
                    } else {
                        self.pos += 1;
                        Tok::LBracket
                    }
                }
                b'=' => if self.peek2() == Some(b'=') { self.pos += 2; Tok::Eq } else { self.pos += 1; Tok::Assign },
                b'<' => match self.peek2() {
                    Some(b'=') => { self.pos += 2; Tok::Le }
                    Some(b'<') => { self.pos += 2; Tok::Shl }
                    _ => { self.pos += 1; Tok::Lt }
                },
                b'>' => match self.peek2() {
                    Some(b'=') => { self.pos += 2; Tok::Ge }
                    Some(b'>') => { self.pos += 2; Tok::Shr }
                    _ => { self.pos += 1; Tok::Gt }
                },
                b'/' => if self.peek2() == Some(b'/') { self.pos += 2; Tok::DSlash } else { self.pos += 1; Tok::Slash },
                b'~' => if self.peek2() == Some(b'=') { self.pos += 2; Tok::Ne } else { self.pos += 1; Tok::Tilde },
                b':' => if self.peek2() == Some(b':') { self.pos += 2; Tok::DColon } else { self.pos += 1; Tok::Colon },
                b'"' | b'\'' => {
                    let s = self.read_string(c)?;
                    Tok::Str(s)
                }
                b'.' => {
                    if self.peek2() == Some(b'.') {
                        if self.src.get(self.pos + 2) == Some(&b'.') { self.pos += 3; Tok::Dots }
                        else { self.pos += 2; Tok::Concat }
                    } else if self.peek2().map_or(false, |d| d.is_ascii_digit()) {
                        self.read_number()?
                    } else { self.pos += 1; Tok::Dot }
                }
                b'0'..=b'9' => self.read_number()?,
                b'+' => { self.pos += 1; Tok::Plus }
                b'*' => { self.pos += 1; Tok::Star }
                b'%' => { self.pos += 1; Tok::Percent }
                b'^' => { self.pos += 1; Tok::Caret }
                b'#' => { self.pos += 1; Tok::Hash }
                b'&' => { self.pos += 1; Tok::Amp }
                b'|' => { self.pos += 1; Tok::Pipe }
                b'(' => { self.pos += 1; Tok::LParen }
                b')' => { self.pos += 1; Tok::RParen }
                b'{' => { self.pos += 1; Tok::LBrace }
                b'}' => { self.pos += 1; Tok::RBrace }
                b']' => { self.pos += 1; Tok::RBracket }
                b';' => { self.pos += 1; Tok::Semi }
                b',' => { self.pos += 1; Tok::Comma }
                _ => {
                    if is_name_start(c) {
                        while let Some(c) = self.peek() {
                            if is_name_char(c) { self.pos += 1; } else { break; }
                        }
                        let s = String::from_utf8_lossy(&self.src[start..self.pos]).into_owned();
                        match keyword(&s) { Some(k) => k, None => Tok::Name(s) }
                    } else {
                        // single-char token: Lua returns the char itself; the parser will
                        // report "unexpected symbol near '<c>'"
                        self.pos += 1;
                        return Err(LexError { msg: "unexpected symbol".into(), line, near: Some(char_desc(c)) });
                    }
                }
            };
            let raw = self.src[start..self.pos].to_vec();
            return Ok(Token { tok, line, raw });
        }
    }

    fn simple(&mut self, tok: Tok, len: usize) -> Token {
        let start = self.pos;
        self.pos += len;
        Token { tok, line: self.line, raw: self.src[start..self.pos].to_vec() }
    }
}

pub fn utf8_encode(mut x: u32, buf: &mut Vec<u8>) {
    // Lua's luaO_utf8esc: supports up to 0x7FFFFFFF (6 byte sequences)
    if x < 0x80 { buf.push(x as u8); return; }
    let mut tmp = Vec::new();
    let mut mfb: u32 = 0x3f;
    loop {
        tmp.push((0x80 | (x & 0x3f)) as u8);
        x >>= 6;
        mfb >>= 1;
        if x <= mfb { break; }
    }
    tmp.push(((!mfb << 1) | x) as u8);
    tmp.reverse();
    buf.extend(tmp);
}

pub enum Number { Int(i64), Flt(f64) }

/// Convert a string to a number following Lua's rules (lua_stringtonumber).
/// Accepts leading/trailing whitespace, hex ints/floats, decimal ints/floats.
pub fn str_to_number(s: &[u8]) -> Option<Number> {
    let t = trim_ascii(s);
    if t.is_empty() { return None; }
    if let Some(i) = str_to_int(t) { return Some(Number::Int(i)); }
    str_to_float(t).map(Number::Flt)
}

fn trim_ascii(s: &[u8]) -> &[u8] {
    let mut a = 0;
    let mut b = s.len();
    while a < b && is_lua_space(s[a]) { a += 1; }
    while b > a && is_lua_space(s[b - 1]) { b -= 1; }
    &s[a..b]
}

fn is_lua_space(c: u8) -> bool { matches!(c, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) }

fn str_to_int(s: &[u8]) -> Option<i64> {
    let (neg, body) = match s.first() {
        Some(b'-') => (true, &s[1..]),
        Some(b'+') => (false, &s[1..]),
        _ => (false, s),
    };
    if body.is_empty() { return None; }
    let mut a: u64 = 0;
    if body.len() > 2 && body[0] == b'0' && (body[1] == b'x' || body[1] == b'X') {
        for &c in &body[2..] {
            let d = (c as char).to_digit(16)? as u64;
            a = a.wrapping_mul(16).wrapping_add(d);
        }
    } else {
        let mut empty = true;
        for &c in body {
            if !c.is_ascii_digit() { return None; }
            let d = (c - b'0') as u64;
            // overflow check like Lua: if a >= maxby10 && (a > maxby10 || d > maxlastd + neg) -> not an integer
            let maxby10 = (i64::MAX as u64) / 10;
            let maxlastd = (i64::MAX as u64) % 10;
            if a >= maxby10 && (a > maxby10 || d > maxlastd + neg as u64) { return None; }
            a = a * 10 + d;
            empty = false;
        }
        if empty { return None; }
    }
    Some(if neg { (a as i64).wrapping_neg() } else { a as i64 })
}

fn str_to_float(s: &[u8]) -> Option<f64> {
    let st = std::str::from_utf8(s).ok()?;
    let lower = st.to_ascii_lowercase();
    if lower.contains("inf") || lower.contains("nan") { return None; }
    let (neg, body) = match st.as_bytes().first() {
        Some(b'-') => (true, &st[1..]),
        Some(b'+') => (false, &st[1..]),
        _ => (false, st),
    };
    let v = if body.len() > 2 && (body.starts_with("0x") || body.starts_with("0X")) {
        parse_hex_float(&body[2..])?
    } else {
        // validate decimal float syntax: digits [. digits] [e [+-] digits]
        if !valid_dec_float(body.as_bytes()) { return None; }
        body.parse::<f64>().ok()?
    };
    Some(if neg { -v } else { v })
}

fn valid_dec_float(s: &[u8]) -> bool {
    let mut i = 0;
    let mut digits = 0;
    while i < s.len() && s[i].is_ascii_digit() { i += 1; digits += 1; }
    if i < s.len() && s[i] == b'.' {
        i += 1;
        while i < s.len() && s[i].is_ascii_digit() { i += 1; digits += 1; }
    }
    if digits == 0 { return false; }
    if i < s.len() && (s[i] == b'e' || s[i] == b'E') {
        i += 1;
        if i < s.len() && (s[i] == b'+' || s[i] == b'-') { i += 1; }
        let mut ed = 0;
        while i < s.len() && s[i].is_ascii_digit() { i += 1; ed += 1; }
        if ed == 0 { return false; }
    }
    i == s.len()
}

fn parse_hex_float(s: &str) -> Option<f64> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut mant: f64 = 0.0;
    let mut exp: i64 = 0;
    let mut any = false;
    while i < b.len() && b[i].is_ascii_hexdigit() {
        mant = mant * 16.0 + (b[i] as char).to_digit(16).unwrap() as f64;
        i += 1; any = true;
    }
    if i < b.len() && b[i] == b'.' {
        i += 1;
        while i < b.len() && b[i].is_ascii_hexdigit() {
            mant = mant * 16.0 + (b[i] as char).to_digit(16).unwrap() as f64;
            exp -= 4;
            i += 1; any = true;
        }
    }
    if !any { return None; }
    if i < b.len() && (b[i] == b'p' || b[i] == b'P') {
        i += 1;
        let mut neg = false;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') { neg = b[i] == b'-'; i += 1; }
        let mut e: i64 = 0;
        let mut ed = 0;
        while i < b.len() && b[i].is_ascii_digit() { e = e.saturating_mul(10).saturating_add((b[i] - b'0') as i64); i += 1; ed += 1; }
        if ed == 0 { return None; }
        exp += if neg { -e } else { e };
    }
    if i != b.len() { return None; }
    Some(mant * (2.0f64).powi(exp as i32))
}
