use std::rc::Rc;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum BinOp {
    Add, Sub, Mul, Div, IDiv, Mod, Pow, Concat,
    Eq, Ne, Lt, Le, Gt, Ge,
    BAnd, BOr, BXor, Shl, Shr,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum UnOp { Neg, Not, Len, BNot }

#[derive(Debug)]
pub struct Expr {
    pub kind: ExprKind,
    pub line: u32,
}

#[derive(Debug)]
pub enum ExprKind {
    Nil,
    True,
    False,
    Int(i64),
    Flt(f64),
    Str(Rc<Vec<u8>>),
    Vararg,
    Name(String),
    Index(Box<Expr>, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>),
    Method(Box<Expr>, String, Vec<Expr>),
    Function(Rc<FuncDef>),
    Bin(BinOp, Box<Expr>, Box<Expr>),
    Un(UnOp, Box<Expr>),
    And(Box<Expr>, Box<Expr>),
    Or(Box<Expr>, Box<Expr>),
    Table(Vec<TableField>),
    Paren(Box<Expr>),
}

#[derive(Debug)]
pub enum TableField {
    Pos(Expr),
    Named(Rc<Vec<u8>>, Expr),
    Keyed(Expr, Expr),
}

#[derive(Debug)]
pub struct FuncDef {
    pub params: Vec<String>,
    pub is_vararg: bool,
    pub body: Block,
    pub line: u32,
    pub end_line: u32,
}

#[derive(Debug, Default)]
pub struct Block {
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Attrib { None, Const, Close }

#[derive(Debug)]
pub enum Stmt {
    Local { names: Vec<(String, Attrib)>, exprs: Vec<Expr>, line: u32 },
    Assign { targets: Vec<Expr>, exprs: Vec<Expr>, line: u32 },
    Call(Expr),
    Do(Block),
    While { cond: Expr, body: Block },
    Repeat { body: Block, cond: Expr },
    If { conds: Vec<(Expr, Block)>, else_block: Option<Block> },
    NumFor { var: String, start: Expr, limit: Expr, step: Option<Expr>, body: Block, line: u32 },
    GenFor { names: Vec<String>, exprs: Vec<Expr>, body: Block, line: u32 },
    Function { target: Expr, func: Rc<FuncDef>, line: u32 },
    LocalFunction { name: String, func: Rc<FuncDef>, line: u32 },
    Return { exprs: Vec<Expr>, line: u32 },
    Break { line: u32 },
    Goto { label: String, line: u32 },
    Label(String),
}
