cat > src/lua/parser.rs <<'EOF'
use super::ast::*;
use super::lexer::{token_desc, Lexer, LexError, Tok, Token};
use std::rc::Rc;

pub struct SyntaxError {
    pub msg: String,
    pub line: u32,
    pub near: Option<String>,
}

impl SyntaxError {
    pub fn format(&self, chunk: &str) -> String {
        match &self.near {
            Some(n) => format!("{}:{}: {} near {}", chunk, self.line, self.msg, n),
            None => format!("{}:{}: {}", chunk, self.line, self.msg),
        }
    }
}

impl From<LexError> for SyntaxError {
    fn from(e: LexError) -> Self {
        SyntaxError { msg: e.msg, line: e.line, near: e.near }
    }
}

struct FuncState {
    is_vararg: bool,
    /// stack of block scopes, each with local names (for const checking / detection)
    blocks: Vec<Vec<(String, Attrib)>>,
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    funcs: Vec<FuncState>,
}

const MAX_LEVELS: usize = 200;

type PResult<T> = Result<T, SyntaxError>;

pub fn parse(src: &[u8]) -> PResult<Rc<FuncDef>> {
    let toks = Lexer::new(src).tokenize()?;
    let mut p = Parser { toks, pos: 0, funcs: vec![FuncState { is_vararg: true, blocks: vec![vec![]] }] };
    let body = p.block()?;
    p.check(&Tok::Eof)?;
    let end_line = p.cur().line;
    Ok(Rc::new(FuncDef { params: vec![], is_vararg: true, body, line: 0, end_line }))
}

impl Parser {
    fn cur(&self) -> &Token { &self.toks[self.pos] }
    fn cur_tok(&self) -> &Tok { &self.toks[self.pos].tok }
    fn line(&self) -> u32 { self.toks[self.pos].line }
    fn peek_tok(&self) -> &Tok {
        if self.pos + 1 < self.toks.len() { &self.toks[self.pos + 1].tok } else { &Tok::Eof }
    }
    fn advance(&mut self) -> Token {
        let t = self.toks[self.pos].clone();
        if self.pos + 1 < self.toks.len() { self.pos += 1; }
        t
    }

    fn near_cur(&self) -> String {
        let t = self.cur();
        token_desc(&t.tok, &t.raw)
    }

    fn error(&self, msg: &str) -> SyntaxError {
        SyntaxError { msg: msg.to_string(), line: self.line(), near: Some(self.near_cur()) }
    }

    fn error_expected(&self, tok: &Tok) -> SyntaxError {
        let s = super::lexer::tok_text(tok);
        let what = if matches!(tok, Tok::Eof | Tok::Name(_) | Tok::Str(_) | Tok::Int(_) | Tok::Flt(_)) {
            s.to_string()
        } else {
            format!("'{}'", s)
        };
        self.error(&format!("{} expected", what))
    }

    fn check(&self, tok: &Tok) -> PResult<()> {
        if std::mem::discriminant(self.cur_tok()) == std::mem::discriminant(tok) { Ok(()) } else { Err(self.error_expected(tok)) }
    }

    fn checknext(&mut self, tok: &Tok) -> PResult<()> {
        self.check(tok)?;
        self.advance();
        Ok(())
    }

    fn testnext(&mut self, tok: &Tok) -> bool {
        if std::mem::discriminant(self.cur_tok()) == std::mem::discriminant(tok) { self.advance(); true } else { false }
    }

    fn check_match(&mut self, what: &Tok, who: &Tok, where_line: u32) -> PResult<()> {
        if !self.testnext(what) {
            if where_line == self.line() {
                return Err(self.error_expected(what));
            } else {
                let msg = format!("'{}' expected (to close '{}' at line {})", super::lexer::tok_text(what), super::lexer::tok_text(who), where_line);
                return Err(self.error(&msg));
            }
        }
        Ok(())
    }

    fn check_name(&mut self) -> PResult<String> {
        match self.cur_tok().clone() {
            Tok::Name(n) => { self.advance(); Ok(n) }
            _ => Err(self.error_expected(&Tok::Name(String::new()))),
        }
    }

    fn block_follow(&self, with_until: bool) -> bool {
        match self.cur_tok() {
            Tok::Else | Tok::Elseif | Tok::End | Tok::Eof => true,
            Tok::Until => with_until,
            _ => false,
        }
    }

    fn enter_level(&self) -> PResult<()> {
        // simplistic: count recursion via funcs/blocks depth isn't accurate; rely on Rust stack
        Ok(())
    }

    fn fs(&mut self) -> &mut FuncState { self.funcs.last_mut().unwrap() }

    fn declare_local(&mut self, name: String, attrib: Attrib) {
        self.fs().blocks.last_mut().unwrap().push((name, attrib));
    }

    fn find_local_attrib(&self, name: &str) -> Option<Attrib> {
        for fs in self.funcs.iter().rev() {
            for b in fs.blocks.iter().rev() {
                for (n, a) in b.iter().rev() {
                    if n == name { return Some(*a); }
                }
            }
        }
        None
    }

    // block ::= statlist
    fn block(&mut self) -> PResult<Block> {
        self.fs().blocks.push(vec![]);
        let mut stmts = Vec::new();
        loop {
            if self.block_follow(true) { break; }
            if *self.cur_tok() == Tok::Return {
                stmts.push(self.retstat()?);
                break;
            }
            if let Some(s) = self.statement()? { stmts.push(s); }
        }
        self.fs().blocks.pop();
        Ok(Block { stmts })
    }

    fn retstat(&mut self) -> PResult<Stmt> {
        let line = self.line();
        self.advance(); // 'return'
        let mut exprs = Vec::new();
        if !(self.block_follow(true) || *self.cur_tok() == Tok::Semi) {
            exprs = self.exprlist()?;
        }
        self.testnext(&Tok::Semi);
        Ok(Stmt::Return { exprs, line })
    }

    fn statement(&mut self) -> PResult<Option<Stmt>> {
        self.enter_level()?;
        let line = self.line();
        let st = match self.cur_tok().clone() {
            Tok::Semi => { self.advance(); return Ok(None); }
            Tok::If => self.ifstat(line)?,
            Tok::While => {
                self.advance();
                let cond = self.expr()?;
                self.checknext(&Tok::Do)?;
                let body = self.block()?;
                self.check_match(&Tok::End, &Tok::While, line)?;
                Stmt::While { cond, body }
            }
            Tok::Do => {
                self.advance();
                let body = self.block()?;
                self.check_match(&Tok::End, &Tok::Do, line)?;
                Stmt::Do(body)
            }
            Tok::For => self.forstat(line)?,
            Tok::Repeat => {
                self.advance();
                // repeat's scope includes the condition
                self.fs().blocks.push(vec![]);
                let mut stmts = Vec::new();
                loop {
                    if self.block_follow(true) { break; }
                    if *self.cur_tok() == Tok::Return { stmts.push(self.retstat()?); break; }
                    if let Some(s) = self.statement()? { stmts.push(s); }
                }
                self.check_match(&Tok::Until, &Tok::Repeat, line)?;
                let cond = self.expr()?;
                self.fs().blocks.pop();
                Stmt::Repeat { body: Block { stmts }, cond }
            }
            Tok::Function => self.funcstat(line)?,
            Tok::Local => {
                self.advance();
                if self.testnext(&Tok::Function) {
                    let name = self.check_name()?;
                    self.declare_local(name.clone(), Attrib::None);
                    let func = self.body(false, line)?;
                    Stmt::LocalFunction { name, func, line }
                } else {
                    self.localstat(line)?
                }
            }
            Tok::DColon => {
                self.advance();
                let name = self.check_name()?;
                self.checknext(&Tok::DColon)?;
                Stmt::Label(name)
            }
            Tok::Return => unreachable!(),
            Tok::Break => { self.advance(); Stmt::Break { line } }
            Tok::Goto => {
                self.advance();
                let label = self.check_name()?;
                Stmt::Goto { label, line }
            }
            _ => self.exprstat(line)?,
        };
        Ok(Some(st))
    }

    fn ifstat(&mut self, line: u32) -> PResult<Stmt> {
        let mut conds = Vec::new();
        // 'if' or 'elseif'
        self.advance();
        let cond = self.expr()?;
        self.checknext(&Tok::Then)?;
        let blk = self.block()?;
        conds.push((cond, blk));
        let mut else_block = None;
        loop {
            match self.cur_tok() {
                Tok::Elseif => {
                    self.advance();
                    let cond = self.expr()?;
                    self.checknext(&Tok::Then)?;
                    let blk = self.block()?;
                    conds.push((cond, blk));
                }
                Tok::Else => {
                    self.advance();
                    else_block = Some(self.block()?);
                    self.check_match(&Tok::End, &Tok::If, line)?;
                    break;
                }
                _ => {
                    self.check_match(&Tok::End, &Tok::If, line)?;
                    break;
                }
            }
        }
        Ok(Stmt::If { conds, else_block })
    }

    fn forstat(&mut self, line: u32) -> PResult<Stmt> {
        self.advance(); // 'for'
        let n1 = self.check_name()?;
        let st = match self.cur_tok() {
            Tok::Assign => {
                self.advance();
                let start = self.expr()?;
                self.checknext(&Tok::Comma)?;
                let limit = self.expr()?;
                let step = if self.testnext(&Tok::Comma) { Some(self.expr()?) } else { None };
                self.checknext(&Tok::Do)?;
                self.fs().blocks.push(vec![(n1.clone(), Attrib::None)]);
                let body = self.block()?;
                self.fs().blocks.pop();
                Stmt::NumFor { var: n1, start, limit, step, body, line }
            }
            Tok::Comma | Tok::In => {
                let mut names = vec![n1];
                while self.testnext(&Tok::Comma) {
                    names.push(self.check_name()?);
                }
                self.checknext(&Tok::In)?;
                let exprs = self.exprlist()?;
                self.checknext(&Tok::Do)?;
                self.fs().blocks.push(names.iter().map(|n| (n.clone(), Attrib::None)).collect());
                let body = self.block()?;
                self.fs().blocks.pop();
                Stmt::GenFor { names, exprs, body, line }
            }
            _ => return Err(self.error("'=' or 'in' expected")),
        };
        self.check_match(&Tok::End, &Tok::For, line)?;
        Ok(st)
    }

    fn funcstat(&mut self, line: u32) -> PResult<Stmt> {
        self.advance(); // 'function'
        // funcname: NAME {'.' NAME} [':' NAME]
        let nline = self.line();
        let n = self.check_name()?;
        let mut target = Expr { kind: ExprKind::Name(n), line: nline };
        let mut is_method = false;
        loop {
            match self.cur_tok() {
                Tok::Dot => {
                    self.advance();
                    let l = self.line();
                    let k = self.check_name()?;
                    target = Expr { kind: ExprKind::Index(Box::new(target), Box::new(Expr { kind: ExprKind::Str(Rc::new(k.into_bytes())), line: l })), line: l };
                }
                Tok::Colon => {
                    self.advance();
                    let l = self.line();
                    let k = self.check_name()?;
                    target = Expr { kind: ExprKind::Index(Box::new(target), Box::new(Expr { kind: ExprKind::Str(Rc::new(k.into_bytes())), line: l })), line: l };
                    is_method = true;
                    break;
                }
                _ => break,
            }
        }
        let func = self.body(is_method, line)?;
        Ok(Stmt::Function { target, func, line })
    }

    fn localstat(&mut self, line: u32) -> PResult<Stmt> {
        let mut names = Vec::new();
        loop {
            let name = self.check_name()?;
            let attrib = if self.testnext(&Tok::Lt) {
                let a = self.check_name()?;
                let at = match a.as_str() {
                    "const" => Attrib::Const,
                    "close" => Attrib::Close,
                    _ => return Err(self.error(&format!("unknown attribute '{}'", a))),
                };
                self.checknext(&Tok::Gt)?;
                at
            } else { Attrib::None };
            names.push((name, attrib));
            if !self.testnext(&Tok::Comma) { break; }
        }
        let exprs = if self.testnext(&Tok::Assign) { self.exprlist()? } else { Vec::new() };
        for (n, a) in &names { self.declare_local(n.clone(), *a); }
        Ok(Stmt::Local { names, exprs, line })
    }

    fn exprstat(&mut self, line: u32) -> PResult<Stmt> {
        let e = self.suffixedexp()?;
        if matches!(self.cur_tok(), Tok::Assign | Tok::Comma) {
            let mut targets = vec![e];
            while self.testnext(&Tok::Comma) {
                targets.push(self.suffixedexp()?);
            }
            for t in &targets {
                match &t.kind {
                    ExprKind::Name(n) => {
                        if let Some(a) = self.find_local_attrib(n) {
                            if a != Attrib::None {
                                return Err(self.error(&format!("attempt to assign to const variable '{}'", n)));
                            }
                        }
                    }
                    ExprKind::Index(..) => {}
                    _ => return Err(self.error("syntax error")),
                }
            }
            self.checknext(&Tok::Assign)?;
            let exprs = self.exprlist()?;
            Ok(Stmt::Assign { targets, exprs, line })
        } else {
            match e.kind {
                ExprKind::Call(..) | ExprKind::Method(..) => Ok(Stmt::Call(e)),
                _ => Err(self.error("syntax error")),
            }
        }
    }

    fn exprlist(&mut self) -> PResult<Vec<Expr>> {
        let mut v = vec![self.expr()?];
        while self.testnext(&Tok::Comma) {
            v.push(self.expr()?);
        }
        Ok(v)
    }

    fn body(&mut self, is_method: bool, line: u32) -> PResult<Rc<FuncDef>> {
        let mut params = Vec::new();
        if is_method { params.push("self".to_string()); }
        self.funcs.push(FuncState { is_vararg: false, blocks: vec![vec![]] });
        self.checknext(&Tok::LParen)?;
        if *self.cur_tok() != Tok::RParen {
            loop {
                match self.cur_tok().clone() {
                    Tok::Name(n) => { self.advance(); params.push(n); }
                    Tok::Dots => { self.advance(); self.fs().is_vararg = true; break; }
                    _ => return Err(self.error("<name> expected")),
                }
                if !self.testnext(&Tok::Comma) { break; }
            }
        }
        for p in &params { self.declare_local(p.clone(), Attrib::None); }
        self.checknext(&Tok::RParen)?;
        let body = self.block()?;
        let end_line = self.line();
        self.check_match(&Tok::End, &Tok::Function, line)?;
        let fs = self.funcs.pop().unwrap();
        Ok(Rc::new(FuncDef { params, is_vararg: fs.is_vararg, body, line, end_line }))
    }

    fn primaryexp(&mut self) -> PResult<Expr> {
        let line = self.line();
        match self.cur_tok().clone() {
            Tok::Name(n) => { self.advance(); Ok(Expr { kind: ExprKind::Name(n), line }) }
            Tok::LParen => {
                self.advance();
                let e = self.expr()?;
                self.check_match(&Tok::RParen, &Tok::LParen, line)?;
                Ok(Expr { kind: ExprKind::Paren(Box::new(e)), line })
            }
            _ => Err(self.error("unexpected symbol")),
        }
    }

    fn suffixedexp(&mut self) -> PResult<Expr> {
        let mut e = self.primaryexp()?;
        loop {
            let line = self.line();
            match self.cur_tok().clone() {
                Tok::Dot => {
                    self.advance();
                    let k = self.check_name()?;
                    e = Expr { kind: ExprKind::Index(Box::new(e), Box::new(Expr { kind: ExprKind::Str(Rc::new(k.into_bytes())), line })), line };
                }
                Tok::LBracket => {
                    self.advance();
                    let k = self.expr()?;
                    self.checknext(&Tok::RBracket)?;
                    e = Expr { kind: ExprKind::Index(Box::new(e), Box::new(k)), line };
                }
                Tok::Colon => {
                    self.advance();
                    let name = self.check_name()?;
                    let args = self.funcargs(line)?;
                    e = Expr { kind: ExprKind::Method(Box::new(e), name, args), line };
                }
                Tok::LParen | Tok::Str(_) | Tok::LBrace => {
                    let args = self.funcargs(line)?;
                    e = Expr { kind: ExprKind::Call(Box::new(e), args), line };
                }
                _ => return Ok(e),
            }
        }
    }

    fn funcargs(&mut self, line: u32) -> PResult<Vec<Expr>> {
        match self.cur_tok().clone() {
            Tok::LParen => {
                self.advance();
                let args = if *self.cur_tok() == Tok::RParen { Vec::new() } else { self.exprlist()? };
                self.check_match(&Tok::RParen, &Tok::LParen, line)?;
                Ok(args)
            }
            Tok::LBrace => {
                let t = self.table_constructor()?;
                Ok(vec![t])
            }
            Tok::Str(s) => {
                let l = self.line();
                self.advance();
                Ok(vec![Expr { kind: ExprKind::Str(Rc::new(s)), line: l }])
            }
            _ => Err(self.error("function arguments expected")),
        }
    }

    fn table_constructor(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.checknext(&Tok::LBrace)?;
        let mut fields = Vec::new();
        loop {
            if *self.cur_tok() == Tok::RBrace { break; }
            match self.cur_tok().clone() {
                Tok::Name(n) if *self.peek_tok() == Tok::Assign => {
                    self.advance();
                    self.advance();
                    let v = self.expr()?;
                    fields.push(TableField::Named(Rc::new(n.into_bytes()), v));
                }
                Tok::LBracket => {
                    self.advance();
                    let k = self.expr()?;
                    self.checknext(&Tok::RBracket)?;
                    self.checknext(&Tok::Assign)?;
                    let v = self.expr()?;
                    fields.push(TableField::Keyed(k, v));
                }
                _ => {
                    let v = self.expr()?;
                    fields.push(TableField::Pos(v));
                }
            }
            if !(self.testnext(&Tok::Comma) || self.testnext(&Tok::Semi)) { break; }
        }
        self.check_match(&Tok::RBrace, &Tok::LBrace, line)?;
        Ok(Expr { kind: ExprKind::Table(fields), line })
    }

    fn simpleexp(&mut self) -> PResult<Expr> {
        let line = self.line();
        let kind = match self.cur_tok().clone() {
            Tok::Flt(f) => { self.advance(); ExprKind::Flt(f) }
            Tok::Int(i) => { self.advance(); ExprKind::Int(i) }
            Tok::Str(s) => { self.advance(); ExprKind::Str(Rc::new(s)) }
            Tok::Nil => { self.advance(); ExprKind::Nil }
            Tok::True => { self.advance(); ExprKind::True }
            Tok::False => { self.advance(); ExprKind::False }
            Tok::Dots => {
                if !self.fs().is_vararg {
                    return Err(self.error("cannot use '...' outside a vararg function"));
                }
                self.advance();
                ExprKind::Vararg
            }
            Tok::LBrace => return self.table_constructor(),
            Tok::Function => {
                self.advance();
                let f = self.body(false, line)?;
                ExprKind::Function(f)
            }
            _ => return self.suffixedexp(),
        };
        Ok(Expr { kind, line })
    }

    fn unop(&self) -> Option<UnOp> {
        match self.cur_tok() {
            Tok::Not => Some(UnOp::Not),
            Tok::Minus => Some(UnOp::Neg),
            Tok::Tilde => Some(UnOp::BNot),
            Tok::Hash => Some(UnOp::Len),
            _ => None,
        }
    }

    fn binop(&self) -> Option<(BinOpKind, u8, u8)> {
        use BinOpKind::*;
        Some(match self.cur_tok() {
            Tok::Plus => (B(BinOp::Add), 10, 10),
            Tok::Minus => (B(BinOp::Sub), 10, 10),
            Tok::Star => (B(BinOp::Mul), 11, 11),
            Tok::Percent => (B(BinOp::Mod), 11, 11),
            Tok::Caret => (B(BinOp::Pow), 14, 13),
            Tok::Slash => (B(BinOp::Div), 11, 11),
            Tok::DSlash => (B(BinOp::IDiv), 11, 11),
            Tok::Amp => (B(BinOp::BAnd), 6, 6),
            Tok::Pipe => (B(BinOp::BOr), 4, 4),
            Tok::Tilde => (B(BinOp::BXor), 5, 5),
            Tok::Shl => (B(BinOp::Shl), 7, 7),
            Tok::Shr => (B(BinOp::Shr), 7, 7),
            Tok::Concat => (B(BinOp::Concat), 9, 8),
            Tok::Ne => (B(BinOp::Ne), 3, 3),
            Tok::Eq => (B(BinOp::Eq), 3, 3),
            Tok::Lt => (B(BinOp::Lt), 3, 3),
            Tok::Le => (B(BinOp::Le), 3, 3),
            Tok::Gt => (B(BinOp::Gt), 3, 3),
            Tok::Ge => (B(BinOp::Ge), 3, 3),
            Tok::And => (And, 2, 2),
            Tok::Or => (Or, 1, 1),
            _ => return None,
        })
    }

    pub fn expr(&mut self) -> PResult<Expr> {
        self.subexpr(0, 0)
    }

    fn subexpr(&mut self, limit: u8, depth: usize) -> PResult<Expr> {
        if depth > MAX_LEVELS {
            return Err(self.error("chunk has too many syntax levels"));
        }
        let line = self.line();
        let mut e = if let Some(op) = self.unop() {
            self.advance();
            let operand = self.subexpr(12, depth + 1)?;
            fold_unop(op, operand, line)
        } else {
            self.simpleexp()?
        };
        while let Some((op, left, right)) = self.binop() {
            if left <= limit { break; }
            let opline = self.line();
            self.advance();
            let rhs = self.subexpr(right, depth + 1)?;
            e = match op {
                BinOpKind::B(b) => Expr { kind: ExprKind::Bin(b, Box::new(e), Box::new(rhs)), line: opline },
                BinOpKind::And => Expr { kind: ExprKind::And(Box::new(e), Box::new(rhs)), line: opline },
                BinOpKind::Or => Expr { kind: ExprKind::Or(Box::new(e), Box::new(rhs)), line: opline },
            };
        }
        Ok(e)
    }
}

enum BinOpKind { B(BinOp), And, Or }

fn fold_unop(op: UnOp, operand: Expr, line: u32) -> Expr {
    // constant-fold numeric negation so that "-1" is a constant (matters little, but keeps
    // integer literals like math.mininteger-style negative numbers behaving)
    match (op, &operand.kind) {
        (UnOp::Neg, ExprKind::Int(i)) => Expr { kind: ExprKind::Int(i.wrapping_neg()), line },
        (UnOp::Neg, ExprKind::Flt(f)) => Expr { kind: ExprKind::Flt(-f), line },
        _ => Expr { kind: ExprKind::Un(op, Box::new(operand)), line },
    }
}
