use super::ast::FuncDef;
use super::interp::{Interp, LuaError};
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

pub type LuaStr = Rc<Vec<u8>>;
pub type TableRef = Rc<RefCell<Table>>;

pub type NativeFn = fn(&mut Interp, Vec<Value>) -> Result<Vec<Value>, LuaError>;

pub struct NativeFunction {
    /// qualified name as found through package.loaded (e.g. "string.find", "print")
    pub name: &'static str,
    pub f: NativeFn,
}

pub struct LuaClosure {
    pub def: Rc<FuncDef>,
    pub env: Rc<Scope>,
}

pub enum Function {
    Lua(LuaClosure),
    Native(NativeFunction),
}

pub type FuncRef = Rc<Function>;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Flt(f64),
    Str(LuaStr),
    Table(TableRef),
    Func(FuncRef),
}

impl Value {
    pub fn str(s: &str) -> Value { Value::Str(Rc::new(s.as_bytes().to_vec())) }
    pub fn bytes(b: Vec<u8>) -> Value { Value::Str(Rc::new(b)) }
    pub fn is_nil(&self) -> bool { matches!(self, Value::Nil) }
    pub fn truthy(&self) -> bool { !matches!(self, Value::Nil | Value::Bool(false)) }
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) | Value::Flt(_) => "number",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Func(_) => "function",
        }
    }
    pub fn new_table() -> Value { Value::Table(Rc::new(RefCell::new(Table::new()))) }

    /// raw equality (no metamethods)
    pub fn raw_eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Flt(a), Value::Flt(b)) => a == b,
            (Value::Int(a), Value::Flt(b)) | (Value::Flt(b), Value::Int(a)) => int_flt_eq(*a, *b),
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Func(a), Value::Func(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

pub fn int_flt_eq(i: i64, f: f64) -> bool {
    // exact comparison like Lua: convert float to int if it has an exact representation
    if f.fract() != 0.0 || !f.is_finite() { return false; }
    if f >= -9223372036854775808.0 && f < 9223372036854775808.0 {
        (f as i64) == i
    } else { false }
}

/// Table key (normalized: floats with integer values become Int)
#[derive(Clone)]
pub enum Key {
    Bool(bool),
    Int(i64),
    Flt(u64), // bit pattern of a non-integral float
    Str(LuaStr),
    Table(TableRef),
    Func(FuncRef),
}

impl PartialEq for Key {
    fn eq(&self, other: &Key) -> bool {
        match (self, other) {
            (Key::Bool(a), Key::Bool(b)) => a == b,
            (Key::Int(a), Key::Int(b)) => a == b,
            (Key::Flt(a), Key::Flt(b)) => a == b,
            (Key::Str(a), Key::Str(b)) => a == b,
            (Key::Table(a), Key::Table(b)) => Rc::ptr_eq(a, b),
            (Key::Func(a), Key::Func(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}
impl Eq for Key {}
impl std::hash::Hash for Key {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        match self {
            Key::Bool(b) => { 0u8.hash(state); b.hash(state); }
            Key::Int(i) => { 1u8.hash(state); i.hash(state); }
            Key::Flt(f) => { 2u8.hash(state); f.hash(state); }
            Key::Str(s) => { 3u8.hash(state); s.hash(state); }
            Key::Table(t) => { 4u8.hash(state); (Rc::as_ptr(t) as usize).hash(state); }
            Key::Func(f) => { 5u8.hash(state); (Rc::as_ptr(f) as *const u8 as usize).hash(state); }
        }
    }
}

impl Key {
    pub fn from_value(v: &Value) -> Option<Key> {
        match v {
            Value::Nil => None,
            Value::Bool(b) => Some(Key::Bool(*b)),
            Value::Int(i) => Some(Key::Int(*i)),
            Value::Flt(f) => {
                if f.is_nan() { return None; }
                if let Some(i) = flt_to_int_exact(*f) { Some(Key::Int(i)) } else { Some(Key::Flt(f.to_bits())) }
            }
            Value::Str(s) => Some(Key::Str(s.clone())),
            Value::Table(t) => Some(Key::Table(t.clone())),
            Value::Func(f) => Some(Key::Func(f.clone())),
        }
    }
    pub fn to_value(&self) -> Value {
        match self {
            Key::Bool(b) => Value::Bool(*b),
            Key::Int(i) => Value::Int(*i),
            Key::Flt(f) => Value::Flt(f64::from_bits(*f)),
            Key::Str(s) => Value::Str(s.clone()),
            Key::Table(t) => Value::Table(t.clone()),
            Key::Func(f) => Value::Func(f.clone()),
        }
    }
}

pub fn flt_to_int_exact(f: f64) -> Option<i64> {
    if f.fract() != 0.0 || !f.is_finite() { return None; }
    if f >= -9223372036854775808.0 && f < 9223372036854775808.0 { Some(f as i64) } else { None }
}

#[derive(Default)]
pub struct Table {
    pub arr: Vec<Value>,
    index: HashMap<Key, usize>,
    pub entries: Vec<(Key, Value)>,
    pub meta: Option<TableRef>,
}

impl Table {
    pub fn new() -> Table { Table::default() }

    pub fn get(&self, key: &Value) -> Value {
        match key {
            Value::Int(i) => self.get_int(*i),
            Value::Flt(f) => {
                if let Some(i) = flt_to_int_exact(*f) { self.get_int(i) } else {
                    match Key::from_value(key) { Some(k) => self.get_key(&k), None => Value::Nil }
                }
            }
            Value::Nil => Value::Nil,
            _ => match Key::from_value(key) { Some(k) => self.get_key(&k), None => Value::Nil },
        }
    }

    pub fn get_str(&self, s: &str) -> Value {
        self.get_key(&Key::Str(Rc::new(s.as_bytes().to_vec())))
    }

    pub fn get_int(&self, i: i64) -> Value {
        if i >= 1 && (i as usize) <= self.arr.len() {
            return self.arr[(i - 1) as usize].clone();
        }
        self.get_key(&Key::Int(i))
    }

    fn get_key(&self, k: &Key) -> Value {
        match self.index.get(k) {
            Some(&i) => self.entries[i].1.clone(),
            None => Value::Nil,
        }
    }

    /// Set; returns Err(msg) for invalid keys
    pub fn set(&mut self, key: Value, val: Value) -> Result<(), &'static str> {
        let k = match &key {
            Value::Nil => return Err("table index is nil"),
            Value::Flt(f) if f.is_nan() => return Err("table index is NaN"),
            _ => Key::from_value(&key).unwrap(),
        };
        self.set_key(k, val);
        Ok(())
    }

    pub fn set_str(&mut self, s: &str, val: Value) {
        self.set_key(Key::Str(Rc::new(s.as_bytes().to_vec())), val);
    }

    pub fn set_int(&mut self, i: i64, val: Value) {
        self.set_key(Key::Int(i), val);
    }

    pub fn set_key(&mut self, k: Key, val: Value) {
        if let Key::Int(i) = k {
            let n = self.arr.len();
            if i >= 1 && (i as usize) <= n {
                self.arr[(i - 1) as usize] = val;
                if (i as usize) == n {
                    while matches!(self.arr.last(), Some(Value::Nil)) { self.arr.pop(); }
                }
                return;
            }
            if (i as usize) == n + 1 && i >= 1 {
                if val.is_nil() {
                    // removing a non-existent entry; but there might be one in hash
                    if let Some(&idx) = self.index.get(&k) { self.entries[idx].1 = Value::Nil; }
                    return;
                }
                // if present in hash, remove it from there
                if let Some(&idx) = self.index.get(&k) { self.entries[idx].1 = Value::Nil; self.index.remove(&k); }
                self.arr.push(val);
                // migrate following keys
                loop {
                    let next = Key::Int(self.arr.len() as i64 + 1);
                    match self.index.get(&next) {
                        Some(&idx) => {
                            let v = std::mem::replace(&mut self.entries[idx].1, Value::Nil);
                            self.index.remove(&next);
                            if v.is_nil() { break; }
                            self.arr.push(v);
                        }
                        None => break,
                    }
                }
                return;
            }
        }
        match self.index.get(&k) {
            Some(&idx) => { self.entries[idx].1 = val; }
            None => {
                if val.is_nil() { return; }
                self.index.insert(k.clone(), self.entries.len());
                self.entries.push((k, val));
            }
        }
    }

    pub fn len(&self) -> i64 {
        let n = self.arr.len() as i64;
        if n > 0 { return n; }
        // check hash part for a border starting at 1
        let mut j: i64 = 0;
        loop {
            if self.get_key(&Key::Int(j + 1)).is_nil() { return j; }
            j += 1;
            if j > 1 << 20 { return j; }
        }
    }

    /// next: returns the entry after `key` (None key = first). Err if key not found.
    pub fn next(&self, key: &Value) -> Result<Option<(Value, Value)>, ()> {
        let mut start_entry: usize = 0;
        match key {
            Value::Nil => {
                for (i, v) in self.arr.iter().enumerate() {
                    if !v.is_nil() { return Ok(Some((Value::Int(i as i64 + 1), v.clone()))); }
                }
            }
            _ => {
                let mut in_arr = false;
                if let Value::Int(i) = key {
                    if *i >= 1 && (*i as usize) <= self.arr.len() {
                        in_arr = true;
                        for j in (*i as usize)..self.arr.len() {
                            if !self.arr[j].is_nil() { return Ok(Some((Value::Int(j as i64 + 1), self.arr[j].clone()))); }
                        }
                    }
                }
                if let Value::Flt(f) = key {
                    if let Some(i) = flt_to_int_exact(*f) {
                        if i >= 1 && (i as usize) <= self.arr.len() {
                            in_arr = true;
                            for j in (i as usize)..self.arr.len() {
                                if !self.arr[j].is_nil() { return Ok(Some((Value::Int(j as i64 + 1), self.arr[j].clone()))); }
                            }
                        }
                    }
                }
                if !in_arr {
                    let k = Key::from_value(key).ok_or(())?;
                    match self.index.get(&k) {
                        Some(&idx) => start_entry = idx + 1,
                        None => return Err(()),
                    }
                }
            }
        }
        for (k, v) in self.entries[start_entry..].iter() {
            if !v.is_nil() { return Ok(Some((k.to_value(), v.clone()))); }
        }
        Ok(None)
    }
}

/// Lexical scope for locals
pub struct Scope {
    pub vars: RefCell<Vec<(Rc<str>, Rc<RefCell<Value>>)>>,
    pub parent: Option<Rc<Scope>>,
    pub func_id: usize,
}

impl Scope {
    pub fn new(parent: Option<Rc<Scope>>, func_id: usize) -> Rc<Scope> {
        Rc::new(Scope { vars: RefCell::new(Vec::new()), parent, func_id })
    }
    pub fn declare(&self, name: &str, v: Value) {
        self.vars.borrow_mut().push((Rc::from(name), Rc::new(RefCell::new(v))));
    }
    /// find a variable: returns cell and whether it is in the same function (local) or outer (upvalue)
    pub fn lookup(self: &Rc<Scope>, name: &str) -> Option<(Rc<RefCell<Value>>, bool)> {
        let func_id = self.func_id;
        let mut cur: Option<&Rc<Scope>> = Some(self);
        while let Some(s) = cur {
            {
                let vars = s.vars.borrow();
                for (n, cell) in vars.iter().rev() {
                    if &**n == name { return Some((cell.clone(), s.func_id == func_id)); }
                }
            }
            cur = s.parent.as_ref();
        }
        None
    }
}
