//! C-style number formatting helpers (%g, %e, %f, %a) used by Lua.

/// Format like C's printf("%.<prec>e")
pub fn fmt_e(v: f64, prec: usize, upper: bool) -> String {
    if !v.is_finite() { return fmt_nonfinite(v, upper); }
    let s = format!("{:.*e}", prec, v);
    // Rust: "1.5e3" / "1.5e-3"; C: "1.5e+03"
    let (mant, exp) = s.split_once('e').unwrap();
    let exp_i: i32 = exp.parse().unwrap();
    let e = if upper { 'E' } else { 'e' };
    let sign = if exp_i < 0 { '-' } else { '+' };
    format!("{}{}{}{:02}", mant, e, sign, exp_i.abs())
}

/// Format like C's printf("%.<prec>f")
pub fn fmt_f(v: f64, prec: usize, upper: bool) -> String {
    if !v.is_finite() { return fmt_nonfinite(v, upper); }
    format!("{:.*}", prec, v)
}

fn fmt_nonfinite(v: f64, upper: bool) -> String {
    let s = if v.is_nan() {
        if v.is_sign_negative() { "-nan" } else { "nan" }
    } else if v > 0.0 { "inf" } else { "-inf" };
    if upper { s.to_uppercase() } else { s.to_string() }
}

/// Format like C's printf("%.<prec>g") (alt = '#' flag keeps trailing zeros)
pub fn fmt_g(v: f64, prec: usize, upper: bool, alt: bool) -> String {
    if !v.is_finite() { return fmt_nonfinite(v, upper); }
    let p = if prec == 0 { 1 } else { prec };
    if v == 0.0 {
        let mut s = if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
        if alt { s.push('.'); for _ in 0..p.saturating_sub(1) { s.push('0'); } }
        return s;
    }
    // determine exponent after rounding to p significant digits
    let es = format!("{:.*e}", p - 1, v);
    let (_, exp) = es.split_once('e').unwrap();
    let x: i32 = exp.parse().unwrap();
    let mut s = if (p as i32) > x && x >= -4 {
        format!("{:.*}", (p as i32 - 1 - x) as usize, v)
    } else {
        fmt_e(v, p - 1, upper)
    };
    if !alt {
        s = strip_trailing_zeros(&s);
    }
    s
}

fn strip_trailing_zeros(s: &str) -> String {
    // strip zeros in the fractional part (before any exponent)
    let (mant, exp) = match s.find(|c| c == 'e' || c == 'E') {
        Some(i) => (&s[..i], &s[i..]),
        None => (s, ""),
    };
    let mant = if mant.contains('.') {
        let t = mant.trim_end_matches('0');
        t.trim_end_matches('.')
    } else { mant };
    format!("{}{}", mant, exp)
}

/// Lua's tostring for floats: "%.14g", adding ".0" when it looks like an integer
pub fn lua_float_to_string(f: f64) -> String {
    let mut s = fmt_g(f, 14, false, false);
    if s.bytes().all(|c| c == b'-' || c.is_ascii_digit()) {
        s.push_str(".0");
    }
    s
}

/// C's "%a" hex float formatting
pub fn fmt_a(v: f64, prec: Option<usize>, upper: bool) -> String {
    if !v.is_finite() { return fmt_nonfinite(v, upper); }
    let bits = v.to_bits();
    let sign = if bits >> 63 != 0 { "-" } else { "" };
    let exp_bits = ((bits >> 52) & 0x7ff) as i64;
    let mut mant = bits & ((1u64 << 52) - 1);
    let (lead, exp) = if exp_bits == 0 {
        if mant == 0 { (0u64, 0i64) } else { (0u64, -1022i64) }
    } else { (1u64, exp_bits - 1023) };
    // mantissa as 13 hex digits
    let mut hex = format!("{:013x}", mant);
    let mut lead = lead;
    match prec {
        None => {
            let t = hex.trim_end_matches('0').to_string();
            hex = t;
        }
        Some(p) => {
            if p < 13 {
                // round to p hex digits
                let shift = (13 - p) * 4;
                let full = (lead << 52) | mant;
                let half = 1u64 << (shift - 1);
                let mut r = full >> shift;
                let rem = full & ((1u64 << shift) - 1);
                if rem > half || (rem == half && (r & 1) == 1) { r += 1; }
                lead = r >> (p * 4);
                mant = r & ((1u64 << (p * 4)) - 1);
                hex = if p > 0 { format!("{:0width$x}", mant, width = p) } else { String::new() };
            } else {
                for _ in 13..p { hex.push('0'); }
            }
        }
    }
    let mut s = format!("{}0x{}", sign, lead);
    if !hex.is_empty() { s.push('.'); s.push_str(&hex); }
    s.push_str(&format!("p{}{}", if exp < 0 { "-" } else { "+" }, exp.abs()));
    if upper { s = s.to_uppercase().replace("0X", "0X"); }
    s
}
