//! Lua 5.4 pattern matching (port of lstrlib.c matching engine).

pub const MAXCAPTURES: usize = 32;
const CAP_UNFINISHED: isize = -1;
pub const CAP_POSITION: isize = -2;
const MAXCCALLS: usize = 200;
const L_ESC: u8 = b'%';

pub struct MatchState<'a> {
    pub src: &'a [u8],
    pub pat: &'a [u8],
    pub level: usize,
    pub capture: Vec<(usize, isize)>, // (init index, len or special)
    matchdepth: usize,
}

pub type PResult<T> = Result<T, String>;

impl<'a> MatchState<'a> {
    pub fn new(src: &'a [u8], pat: &'a [u8]) -> Self {
        MatchState { src, pat, level: 0, capture: vec![(0, 0); MAXCAPTURES], matchdepth: MAXCCALLS }
    }

    pub fn reprep(&mut self) {
        self.level = 0;
        self.matchdepth = MAXCCALLS;
    }

    fn check_capture(&self, l: u8) -> PResult<usize> {
        let l = l as isize - b'1' as isize;
        if l < 0 || l as usize >= self.level || self.capture[l as usize].1 == CAP_UNFINISHED {
            return Err(format!("invalid capture index %{} in pattern", l + 1));
        }
        Ok(l as usize)
    }

    fn capture_to_close(&self) -> PResult<usize> {
        let mut level = self.level as isize - 1;
        while level >= 0 {
            if self.capture[level as usize].1 == CAP_UNFINISHED { return Ok(level as usize); }
            level -= 1;
        }
        Err("invalid pattern capture".to_string())
    }

    fn class_end(&self, mut p: usize) -> PResult<usize> {
        let c = self.pat[p];
        p += 1;
        if c == L_ESC {
            if p >= self.pat.len() { return Err("malformed pattern (ends with '%')".to_string()); }
            return Ok(p + 1);
        }
        if c == b'[' {
            if p < self.pat.len() && self.pat[p] == b'^' { p += 1; }
            loop {
                // look for a ']'
                if p >= self.pat.len() { return Err("malformed pattern (missing ']')".to_string()); }
                let cc = self.pat[p];
                p += 1;
                if cc == L_ESC {
                    if p >= self.pat.len() { return Err("malformed pattern (missing ']')".to_string()); }
                    p += 1; // skip escapes (e.g. '%]')
                }
                if p < self.pat.len() && self.pat[p] == b']' { break; }
                if p >= self.pat.len() { return Err("malformed pattern (missing ']')".to_string()); }
            }
            return Ok(p + 1);
        }
        Ok(p)
    }

    fn single_match(&self, s: usize, p: usize, ep: usize) -> bool {
        if s >= self.src.len() { return false; }
        let c = self.src[s];
        match self.pat[p] {
            b'.' => true,
            L_ESC => match_class(c, self.pat[p + 1]),
            b'[' => match_bracket_class(c, self.pat, p, ep - 1),
            pc => pc == c,
        }
    }

    fn match_balance(&self, s: usize, p: usize) -> PResult<Option<usize>> {
        if p + 1 >= self.pat.len() {
            return Err("malformed pattern (missing arguments to '%b')".to_string());
        }
        if s >= self.src.len() || self.src[s] != self.pat[p] { return Ok(None); }
        let b = self.pat[p];
        let e = self.pat[p + 1];
        let mut cont = 1;
        let mut s = s + 1;
        while s < self.src.len() {
            let c = self.src[s];
            if c == e {
                cont -= 1;
                if cont == 0 { return Ok(Some(s + 1)); }
            } else if c == b { cont += 1; }
            s += 1;
        }
        Ok(None)
    }

    fn max_expand(&mut self, s: usize, p: usize, ep: usize) -> PResult<Option<usize>> {
        let mut i = 0usize;
        while self.single_match(s + i, p, ep) { i += 1; }
        // keeps trying to match with the maximum repetitions
        loop {
            if let Some(res) = self.do_match(s + i, ep + 1)? { return Ok(Some(res)); }
            if i == 0 { return Ok(None); }
            i -= 1;
        }
    }

    fn min_expand(&mut self, mut s: usize, p: usize, ep: usize) -> PResult<Option<usize>> {
        loop {
            if let Some(res) = self.do_match(s, ep + 1)? { return Ok(Some(res)); }
            if self.single_match(s, p, ep) { s += 1; } else { return Ok(None); }
        }
    }

    fn start_capture(&mut self, s: usize, p: usize, what: isize) -> PResult<Option<usize>> {
        if self.level >= MAXCAPTURES { return Err("too many captures".to_string()); }
        self.capture[self.level] = (s, what);
        self.level += 1;
        let res = self.do_match(s, p)?;
        if res.is_none() { self.level -= 1; }
        Ok(res)
    }

    fn end_capture(&mut self, s: usize, p: usize) -> PResult<Option<usize>> {
        let l = self.capture_to_close()?;
        self.capture[l].1 = (s - self.capture[l].0) as isize;
        let res = self.do_match(s, p)?;
        if res.is_none() { self.capture[l].1 = CAP_UNFINISHED; }
        Ok(res)
    }

    fn match_capture(&self, s: usize, l: u8) -> PResult<Option<usize>> {
        let l = self.check_capture(l)?;
        let (init, len) = self.capture[l];
        let len = len as usize;
        if self.src.len() - s >= len && self.src[init..init + len] == self.src[s..s + len] {
            Ok(Some(s + len))
        } else { Ok(None) }
    }

    pub fn do_match(&mut self, mut s: usize, mut p: usize) -> PResult<Option<usize>> {
        if self.matchdepth == 0 { return Err("pattern too complex".to_string()); }
        self.matchdepth -= 1;
        let result = loop {
            if p >= self.pat.len() { break Some(s); }
            match self.pat[p] {
                b'(' => {
                    break if p + 1 < self.pat.len() && self.pat[p + 1] == b')' {
                        self.start_capture(s, p + 2, CAP_POSITION)?
                    } else {
                        self.start_capture(s, p + 1, CAP_UNFINISHED)?
                    };
                }
                b')' => break self.end_capture(s, p + 1)?,
                b'$' if p + 1 == self.pat.len() => {
                    break if s == self.src.len() { Some(s) } else { None };
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1] == b'b' => {
                    match self.match_balance(s, p + 2)? {
                        Some(ns) => { s = ns; p += 4; continue; }
                        None => break None,
                    }
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1] == b'f' => {
                    p += 2;
                    if p >= self.pat.len() || self.pat[p] != b'[' {
                        return Err("missing '[' after '%f' in pattern".to_string());
                    }
                    let ep = self.class_end(p)?;
                    let previous = if s == 0 { 0u8 } else { self.src[s - 1] };
                    let cur = if s < self.src.len() { self.src[s] } else { 0u8 };
                    if !match_bracket_class(previous, self.pat, p, ep - 1) && match_bracket_class(cur, self.pat, p, ep - 1) {
                        p = ep; continue;
                    }
                    break None;
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1].is_ascii_digit() => {
                    match self.match_capture(s, self.pat[p + 1])? {
                        Some(ns) => { s = ns; p += 2; continue; }
                        None => break None,
                    }
                }
                _ => {
                    let ep = self.class_end(p)?;
                    let epc = if ep < self.pat.len() { self.pat[ep] } else { 0 };
                    if !self.single_match(s, p, ep) {
                        if epc == b'*' || epc == b'?' || epc == b'-' {
                            p = ep + 1; continue;
                        }
                        break None;
                    } else {
                        match epc {
                            b'?' => {
                                if let Some(res) = self.do_match(s + 1, ep + 1)? { break Some(res); }
                                p = ep + 1; continue;
                            }
                            b'+' => break self.max_expand(s + 1, p, ep)?,
                            b'*' => break self.max_expand(s, p, ep)?,
                            b'-' => break self.min_expand(s, p, ep)?,
                            _ => { s += 1; p = ep; continue; }
                        }
                    }
                }
            }
        };
        self.matchdepth += 1;
        Ok(result)
    }

    /// Get capture i as (start, len) or position; whole match if no captures and i == 0
    pub fn get_capture(&self, i: usize, s: usize, e: usize) -> PResult<Capture> {
        if i >= self.level {
            if i == 0 { return Ok(Capture::Str(s, e - s)); }
            return Err(format!("invalid capture index %{}", i + 1));
        }
        let (init, l) = self.capture[i];
        if l == CAP_UNFINISHED { return Err("unfinished capture".to_string()); }
        if l == CAP_POSITION { return Ok(Capture::Pos(init + 1)); }
        Ok(Capture::Str(init, l as usize))
    }

    pub fn num_captures(&self, s: usize, e: usize) -> usize {
        let _ = (s, e);
        if self.level == 0 { 1 } else { self.level }
    }
}

pub enum Capture { Str(usize, usize), Pos(usize) }

fn match_class(c: u8, cl: u8) -> bool {
    let res = match cl.to_ascii_lowercase() {
        b'a' => c.is_ascii_alphabetic(),
        b'c' => c.is_ascii_control(),
        b'd' => c.is_ascii_digit(),
        b'g' => c.is_ascii_graphic(),
        b'l' => c.is_ascii_lowercase(),
        b'p' => c.is_ascii_punctuation(),
        b's' => c == b' ' || (9..=13).contains(&c),
        b'u' => c.is_ascii_uppercase(),
        b'w' => c.is_ascii_alphanumeric(),
        b'x' => c.is_ascii_hexdigit(),
        _ => return cl == c,
    };
    if cl.is_ascii_uppercase() { !res } else { res }
}

fn match_bracket_class(c: u8, pat: &[u8], p: usize, ec: usize) -> bool {
    // pat[p] == '[', pat[ec] == ']'
    let mut p = p + 1;
    let mut sig = true;
    if pat[p] == b'^' { sig = false; p += 1; }
    while p < ec {
        if pat[p] == L_ESC {
            p += 1;
            if match_class(c, pat[p]) { return sig; }
            p += 1;
        } else if p + 2 < ec && pat[p + 1] == b'-' {
            if pat[p] <= c && c <= pat[p + 2] { return sig; }
            p += 3;
        } else {
            if pat[p] == c { return sig; }
            p += 1;
        }
    }
    !sig
}

/// true if the pattern has no special characters
pub fn no_specials(pat: &[u8]) -> bool {
    !pat.iter().any(|c| b"^$*+?.([%-".contains(c))
}

/// plain substring find
pub fn lmemfind(s: &[u8], pat: &[u8]) -> Option<usize> {
    if pat.is_empty() { return Some(0); }
    if pat.len() > s.len() { return None; }
    (0..=s.len() - pat.len()).find(|&i| &s[i..i + pat.len()] == pat)
}
