cd /workspace; cat > src/lua/interp.rs <<'EOF'
//! Tree-walking Lua interpreter.

use super::ast::*;
use super::lexer::{str_to_number, Number};
use super::numfmt::lua_float_to_string;
use super::value::*;
use std::cell::RefCell;
use std::rc::Rc;

pub struct LuaError {
    pub value: Value,
    pub traceback: Option<String>,
}

impl LuaError {
    pub fn new_plain(v: Value) -> LuaError { LuaError { value: v, traceback: None } }
}

pub type LResult<T> = Result<T, LuaError>;

pub enum Flow {
    Normal,
    Break,
    Return(Vec<Value>),
    Goto(String),
}

/// Describes how a function was named at its call site (for tracebacks and arg errors).
#[derive(Clone)]
pub enum CallName {
    Global(String),
    Local(String),
    Upvalue(String),
    Field(String),
    Method(String),
    Constant(String),
    ForIterator,
    Unknown,
}

impl CallName {
    pub fn plain_name(&self) -> Option<&str> {
        match self {
            CallName::Global(n) | CallName::Local(n) | CallName::Upvalue(n) | CallName::Field(n) | CallName::Method(n) | CallName::Constant(n) => Some(n),
            CallName::ForIterator => Some("for iterator"),
            CallName::Unknown => None,
        }
    }
    /// " kind 'name'" form used in tracebacks
    pub fn traceback_desc(&self) -> Option<String> {
        Some(match self {
            CallName::Global(n) => format!("global '{}'", n),
            CallName::Local(n) => format!("local '{}'", n),
            CallName::Upvalue(n) => format!("upvalue '{}'", n),
            CallName::Field(n) => format!("field '{}'", n),
            CallName::Method(n) => format!("method '{}'", n),
            CallName::Constant(n) => format!("constant '{}'", n),
            CallName::ForIterator => "for iterator 'for iterator'".to_string(),
            CallName::Unknown => return None,
        })
    }
    pub fn is_method(&self) -> bool { matches!(self, CallName::Method(_)) }
}

pub enum FrameKind {
    Main,
    Lua { def: Rc<FuncDef>, func: FuncRef },
    Native { name: &'static str },
}

pub struct Frame {
    pub kind: FrameKind,
    pub line: u32,
    pub call_name: CallName,
}

pub struct Interp {
    pub globals: TableRef,
    pub string_meta: TableRef,
    pub string_lib: TableRef,
    pub chunk_name: String,
    pub frames: Vec<Frame>,
    pub next_func_id: usize,
    pub out: Vec<u8>,
    pub depth: usize,
}

const MAX_DEPTH: usize = 190;

fn with_traceback(mut e: LuaError, tb: String) -> LuaError {
    if e.traceback.is_none() { e.traceback = Some(tb); }
    e
}

impl Interp {
    pub fn new(chunk_name: &str) -> Interp {
        let globals = Rc::new(RefCell::new(Table::new()));
        let string_meta = Rc::new(RefCell::new(Table::new()));
        let string_lib = Rc::new(RefCell::new(Table::new()));
        let mut it = Interp {
            globals,
            string_meta,
            string_lib,
            chunk_name: chunk_name.to_string(),
            frames: Vec::new(),
            next_func_id: 1,
            out: Vec::new(),
            depth: 0,
        };
        super::stdlib::install(&mut it);
        it
    }

    pub fn set_chunk_name(&mut self, name: &str) { self.chunk_name = name.to_string(); }

    // ------------------------------------------------------------------
    // error helpers

    pub fn current_line(&self) -> Option<u32> {
        // the innermost Lua frame's line, if the innermost frame is Lua
        match self.frames.last() {
            Some(f) => match f.kind {
                FrameKind::Native { .. } => None,
                _ => Some(f.line),
            },
            None => None,
        }
    }

    /// position prefix "chunk:line: " of the frame at `level` (0 = innermost)
    pub fn where_(&self, level: usize) -> String {
        if level >= self.frames.len() { return String::new(); }
        let f = &self.frames[self.frames.len() - 1 - level];
        match f.kind {
            FrameKind::Native { .. } => String::new(),
            _ => format!("{}:{}: ", self.chunk_name, f.line),
        }
    }

    fn frame_desc(&self, f: &Frame) -> String {
        match &f.kind {
            FrameKind::Main => format!("{}:{}: in main chunk", self.chunk_name, f.line),
            FrameKind::Native { name } => format!("[C]: in function '{}'", name),
            FrameKind::Lua { def, func } => {
                // global function?
                if let Some(gname) = self.find_global_function(func) {
                    return format!("{}:{}: in function '{}'", self.chunk_name, f.line, gname);
                }
                match f.call_name.traceback_desc() {
                    Some(d) => format!("{}:{}: in {}", self.chunk_name, f.line, d),
                    None => format!("{}:{}: in function <{}:{}>", self.chunk_name, f.line, self.chunk_name, def.line),
                }
            }
        }
    }

    fn find_global_function(&self, func: &FuncRef) -> Option<String> {
        let g = self.globals.borrow();
        for (k, v) in g.entries.iter() {
            if let (Key::Str(name), Value::Func(f)) = (k, v) {
                if Rc::ptr_eq(f, func) { return Some(String::from_utf8_lossy(name).into_owned()); }
            }
        }
        None
    }

    /// Build a traceback. `handler_ctx` is what the message handler frame is reported as.
    pub fn traceback(&self, handler_ctx: &str) -> String {
        let mut s = String::from("stack traceback:");
        s.push_str(&format!("\n\t[C]: in {}", handler_ctx));
        for f in self.frames.iter().rev() {
            s.push('\n');
            s.push('\t');
            s.push_str(&self.frame_desc(f));
        }
        s
    }

    /// Runtime error raised by the VM at the current Lua frame.
    pub fn rt_error(&self, msg: &str, ctx: &str) -> LuaError {
        let full = format!("{}{}", self.where_(0), msg);
        LuaError { value: Value::str(&full), traceback: Some(self.traceback(ctx)) }
    }

    /// Error raised from within a native function (luaL_error semantics: position of level 1)
    pub fn lib_error(&self, msg: &str) -> LuaError {
        let full = format!("{}{}", self.where_(1), msg);
        LuaError { value: Value::str(&full), traceback: Some(self.traceback("?")) }
    }

    /// error without position
    pub fn lib_error_nopos(&self, v: Value) -> LuaError {
        LuaError { value: v, traceback: Some(self.traceback("?")) }
    }

    fn native_call_name(&self) -> Option<String> {
        // the name of the currently running native function at its call site
        match self.frames.last() {
            Some(f) => f.call_name.plain_name().map(|s| s.to_string()),
            None => None,
        }
    }

    pub fn arg_error(&self, mut arg: usize, extramsg: &str) -> LuaError {
        let f = self.frames.last();
        let (name, is_method) = match f {
            Some(fr) => (fr.call_name.plain_name().map(|s| s.to_string()), fr.call_name.is_method()),
            None => (None, false),
        };
        if is_method {
            if arg == 1 {
                return self.lib_error(&format!("calling '{}' on bad self ({})", name.unwrap_or("?".into()), extramsg));
            }
            arg -= 1;
        }
        let name = match name {
            Some(n) => n,
            None => match f { Some(Frame { kind: FrameKind::Native { name }, .. }) => name.to_string(), _ => "?".to_string() },
        };
        let _ = self.native_call_name();
        self.lib_error(&format!("bad argument #{} to '{}' ({})", arg, name, extramsg))
    }

    pub fn type_error(&self, arg: usize, expected: &str, got: Option<&Value>) -> LuaError {
        let tname = match got {
            None => "no value".to_string(),
            Some(v) => self.obj_type_name(v),
        };
        self.arg_error(arg, &format!("{} expected, got {}", expected, tname))
    }

    /// luaT_objtypename: uses __name metafield if present
    pub fn obj_type_name(&self, v: &Value) -> String {
        if let Value::Table(t) = v {
            if let Some(mt) = &t.borrow().meta {
                if let Value::Str(s) = mt.borrow().get_str("__name") {
                    return String::from_utf8_lossy(&s).into_owned();
                }
            }
        }
        v.type_name().to_string()
    }

    // ------------------------------------------------------------------
    // metatables

    pub fn get_metatable(&self, v: &Value) -> Option<TableRef> {
        match v {
            Value::Table(t) => t.borrow().meta.clone(),
            Value::Str(_) => Some(self.string_meta.clone()),
            _ => None,
        }
    }

    pub fn get_metamethod(&self, v: &Value, name: &str) -> Value {
        match self.get_metatable(v) {
            Some(mt) => mt.borrow().get_str(name),
            None => Value::Nil,
        }
    }

    // ------------------------------------------------------------------
    // variable description for error messages (ldebug varinfo)

    fn varinfo(&self, e: &Expr, scope: &Rc<Scope>) -> String {
        match &e.kind {
            ExprKind::Name(n) => match scope.lookup(n) {
                Some((_, true)) => format!(" (local '{}')", n),
                Some((_, false)) => format!(" (upvalue '{}')", n),
                None => format!(" (global '{}')", n),
            },
            ExprKind::Index(_, k) => match &k.kind {
                ExprKind::Str(s) => format!(" (field '{}')", String::from_utf8_lossy(s)),
                ExprKind::Int(i) if (0..=255).contains(i) => " (field 'integer index')".to_string(),
                _ => " (field '?')".to_string(),
            },
            ExprKind::Str(s) => format!(" (constant '{}')", String::from_utf8_lossy(s)),
            ExprKind::Method(_, n, _) => format!(" (method '{}')", n),
            ExprKind::Paren(inner) => self.varinfo(inner, scope),
            _ => String::new(),
        }
    }

    fn call_name_of(&self, e: &Expr, scope: &Rc<Scope>) -> CallName {
        match &e.kind {
            ExprKind::Name(n) => match scope.lookup(n) {
                Some((_, true)) => CallName::Local(n.clone()),
                Some((_, false)) => CallName::Upvalue(n.clone()),
                None => CallName::Global(n.clone()),
            },
            ExprKind::Index(_, k) => match &k.kind {
                ExprKind::Str(s) => CallName::Field(String::from_utf8_lossy(s).into_owned()),
                ExprKind::Int(i) if (0..=255).contains(i) => CallName::Field("integer index".into()),
                _ => CallName::Field("?".into()),
            },
            ExprKind::Method(_, n, _) => CallName::Method(n.clone()),
            ExprKind::Paren(inner) => self.call_name_of(inner, scope),
            _ => CallName::Unknown,
        }
    }

    fn set_line(&mut self, line: u32) {
        if let Some(f) = self.frames.last_mut() {
            if !matches!(f.kind, FrameKind::Native { .. }) { f.line = line; }
        }
    }

    // ------------------------------------------------------------------
    // running chunks

    pub fn run_main(&mut self, def: Rc<FuncDef>) -> LResult<Vec<Value>> {
        let scope = Scope::new(None, 0);
        self.frames.push(Frame { kind: FrameKind::Main, line: 1, call_name: CallName::Unknown });
        let r = self.exec_block(&def.body, &scope, &[]);
        self.frames.pop();
        match r? {
            Flow::Return(v) => Ok(v),
            _ => Ok(vec![]),
        }
    }

    pub fn exec_block(&mut self, b: &Block, parent: &Rc<Scope>, _varargs: &[Value]) -> LResult<Flow> {
        let scope = Scope::new(Some(parent.clone()), parent.func_id);
        self.exec_stmts(&b.stmts, &scope)
    }

    fn exec_stmts(&mut self, stmts: &[Stmt], scope: &Rc<Scope>) -> LResult<Flow> {
        let mut i = 0;
        while i < stmts.len() {
            let flow = self.exec_stmt(&stmts[i], scope)?;
            match flow {
                Flow::Normal => { i += 1; }
                Flow::Goto(label) => {
                    // look for label in this block
                    let pos = stmts.iter().position(|s| matches!(s, Stmt::Label(l) if *l == label));
                    match pos {
                        Some(p) => { i = p + 1; }
                        None => return Ok(Flow::Goto(label)),
                    }
                }
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_stmt(&mut self, s: &Stmt, scope: &Rc<Scope>) -> LResult<Flow> {
        match s {
            Stmt::Local { names, exprs, line } => {
                self.set_line(*line);
                let vals = self.eval_exprlist(exprs, scope)?;
                for (i, (n, _)) in names.iter().enumerate() {
                    let v = vals.get(i).cloned().unwrap_or(Value::Nil);
                    scope.declare(n, v);
                }
                Ok(Flow::Normal)
            }
            Stmt::Assign { targets, exprs, line } => {
                self.set_line(*line);
                // evaluate table/key of targets first? Lua evaluates all expressions before assigning.
                let mut prepared = Vec::with_capacity(targets.len());
                for t in targets {
                    match &t.kind {
                        ExprKind::Name(_) => prepared.push(None),
                        ExprKind::Index(obj, key) => {
                            let o = self.eval(obj, scope)?;
                            let k = self.eval(key, scope)?;
                            prepared.push(Some((o, k)));
                        }
                        _ => unreachable!(),
                    }
                }
                let vals = self.eval_exprlist(exprs, scope)?;
                self.set_line(*line);
                // Lua assigns right to left; order of errors rarely matters
                for (i, t) in targets.iter().enumerate().rev() {
                    let v = vals.get(i).cloned().unwrap_or(Value::Nil);
                    match &t.kind {
                        ExprKind::Name(n) => self.assign_name(n, v, scope)?,
                        ExprKind::Index(obj, _) => {
                            let (o, k) = prepared[i].take().unwrap();
                            self.set_index(o, k, v, obj, scope)?;
                        }
                        _ => unreachable!(),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Call(e) => {
                self.set_line(e.line);
                self.eval_multi(e, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::Do(b) => self.exec_block(b, scope, &[]),
            Stmt::While { cond, body } => {
                loop {
                    self.set_line(cond.line);
                    let c = self.eval(cond, scope)?;
                    if !c.truthy() { break; }
                    match self.exec_block(body, scope, &[])? {
                        Flow::Break => break,
                        Flow::Normal => {}
                        other => return Ok(other),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Repeat { body, cond } => {
                loop {
                    let inner = Scope::new(Some(scope.clone()), scope.func_id);
                    match self.exec_stmts(&body.stmts, &inner)? {
                        Flow::Break => break,
                        Flow::Normal => {}
                        other => return Ok(other),
                    }
                    self.set_line(cond.line);
                    let c = self.eval(cond, &inner)?;
                    if c.truthy() { break; }
                }
                Ok(Flow::Normal)
            }
            Stmt::If { conds, else_block } => {
                for (cond, blk) in conds {
                    self.set_line(cond.line);
                    let c = self.eval(cond, scope)?;
                    if c.truthy() {
                        return self.exec_block(blk, scope, &[]);
                    }
                }
                if let Some(b) = else_block {
                    return self.exec_block(b, scope, &[]);
                }
                Ok(Flow::Normal)
            }
            Stmt::NumFor { var, start, limit, step, body, line } => {
                self.set_line(*line);
                let init = self.eval(start, scope)?;
                let lim = self.eval(limit, scope)?;
                let stp = match step { Some(s) => self.eval(s, scope)?, None => Value::Int(1) };
                self.set_line(*line);
                let init = self.for_num(init, "initial")?;
                let lim = self.for_num(lim, "limit")?;
                let stp = self.for_num(stp, "step")?;
                match (init, stp) {
                    (Value::Int(i0), Value::Int(st)) => {
                        if st == 0 { return Err(self.rt_error("'for' step is zero", "?")); }
                        // compute integer limit
                        let lim_i: Option<i64> = match lim {
                            Value::Int(l) => Some(l),
                            Value::Flt(f) => {
                                if f.is_nan() { None }
                                else if st > 0 { let fl = f.floor(); if fl >= 9223372036854775808.0 { Some(i64::MAX) } else if fl < -9223372036854775808.0 { None } else { Some(fl as i64) } }
                                else { let cl = f.ceil(); if cl < -9223372036854775808.0 { Some(i64::MIN) } else if cl >= 9223372036854775808.0 { None } else { Some(cl as i64) } }
                            }
                            _ => unreachable!(),
                        };
                        let lim_i = match lim_i { Some(l) => l, None => return Ok(Flow::Normal) };
                        if (st > 0 && i0 > lim_i) || (st < 0 && i0 < lim_i) { return Ok(Flow::Normal); }
                        // iteration count
                        let count: u64 = if st > 0 { ((lim_i as i128 - i0 as i128) / st as i128) as u64 } else { ((i0 as i128 - lim_i as i128) / (-(st as i128))) as u64 };
                        let mut v = i0;
                        let mut remaining = count;
                        loop {
                            let inner = Scope::new(Some(scope.clone()), scope.func_id);
                            inner.declare(var, Value::Int(v));
                            match self.exec_stmts(&body.stmts, &inner)? {
                                Flow::Break => break,
                                Flow::Normal => {}
                                other => return Ok(other),
                            }
                            if remaining == 0 { break; }
                            remaining -= 1;
                            v = v.wrapping_add(st);
                        }
                    }
                    (init, stp) => {
                        let i0 = to_f(&init);
                        let st = to_f(&stp);
                        let l = to_f(&lim);
                        if st == 0.0 { return Err(self.rt_error("'for' step is zero", "?")); }
                        let mut v = i0;
                        loop {
                            if (st > 0.0 && v > l) || (st < 0.0 && v < l) { break; }
                            let inner = Scope::new(Some(scope.clone()), scope.func_id);
                            inner.declare(var, Value::Flt(v));
                            match self.exec_stmts(&body.stmts, &inner)? {
                                Flow::Break => break,
                                Flow::Normal => {}
                                other => return Ok(other),
                            }
                            v += st;
                        }
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::GenFor { names, exprs, body, line } => {
                self.set_line(*line);
                let vals = self.eval_exprlist(exprs, scope)?;
                let f = vals.get(0).cloned().unwrap_or(Value::Nil);
                let s = vals.get(1).cloned().unwrap_or(Value::Nil);
                let mut ctrl = vals.get(2).cloned().unwrap_or(Value::Nil);
                loop {
                    self.set_line(*line);
                    let rs = self.call_value(f.clone(), vec![s.clone(), ctrl.clone()], CallName::ForIterator, None)?;
                    let first = rs.get(0).cloned().unwrap_or(Value::Nil);
                    if first.is_nil() { break; }
                    ctrl = first;
                    let inner = Scope::new(Some(scope.clone()), scope.func_id);
                    for (i, n) in names.iter().enumerate() {
                        inner.declare(n, rs.get(i).cloned().unwrap_or(Value::Nil));
                    }
                    match self.exec_stmts(&body.stmts, &inner)? {
                        Flow::Break => break,
                        Flow::Normal => {}
                        other => return Ok(other),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Function { target, func, line } => {
                self.set_line(*line);
                let closure = self.make_closure(func, scope);
                match &target.kind {
                    ExprKind::Name(n) => self.assign_name(n, closure, scope)?,
                    ExprKind::Index(obj, key) => {
                        let o = self.eval(obj, scope)?;
                        let k = self.eval(key, scope)?;
                        self.set_index(o, k, closure, obj, scope)?;
                    }
                    _ => unreachable!(),
                }
                Ok(Flow::Normal)
            }
            Stmt::LocalFunction { name, func, line } => {
                self.set_line(*line);
                scope.declare(name, Value::Nil);
                let closure = self.make_closure(func, scope);
                let (cell, _) = scope.lookup(name).unwrap();
                *cell.borrow_mut() = closure;
                Ok(Flow::Normal)
            }
            Stmt::Return { exprs, line } => {
                self.set_line(*line);
                // tail call naming isn't modelled
                let vals = self.eval_exprlist(exprs, scope)?;
                Ok(Flow::Return(vals))
            }
            Stmt::Break { .. } => Ok(Flow::Break),
            Stmt::Goto { label, .. } => Ok(Flow::Goto(label.clone())),
            Stmt::Label(_) => Ok(Flow::Normal),
        }
    }

    fn for_num(&self, v: Value, what: &str) -> LResult<Value> {
        match &v {
            Value::Int(_) | Value::Flt(_) => Ok(v),
            Value::Str(s) => match str_to_number(s) {
                Some(Number::Int(i)) => Ok(Value::Int(i)),
                Some(Number::Flt(f)) => Ok(Value::Flt(f)),
                None => Err(self.rt_error(&format!("'for' {} value must be a number", what), "?")),
            },
            _ => Err(self.rt_error(&format!("'for' {} value must be a number", what), "?")),
        }
    }

    fn make_closure(&mut self, def: &Rc<FuncDef>, scope: &Rc<Scope>) -> Value {
        Value::Func(Rc::new(Function::Lua(LuaClosure { def: def.clone(), env: scope.clone() })))
    }

    fn assign_name(&mut self, n: &str, v: Value, scope: &Rc<Scope>) -> LResult<()> {
        match scope.lookup(n) {
            Some((cell, _)) => { *cell.borrow_mut() = v; Ok(()) }
            None => {
                let g = self.globals.clone();
                let key = Value::str(n);
                self.set_table(Value::Table(g), key, v, None)
            }
        }
    }

    pub fn eval_exprlist(&mut self, exprs: &[Expr], scope: &Rc<Scope>) -> LResult<Vec<Value>> {
        let mut out = Vec::with_capacity(exprs.len());
        for (i, e) in exprs.iter().enumerate() {
            if i + 1 == exprs.len() {
                let mut vs = self.eval_multi(e, scope)?;
                out.append(&mut vs);
            } else {
                out.push(self.eval(e, scope)?);
            }
        }
        Ok(out)
    }

    /// Evaluate to possibly multiple values (calls and varargs).
    pub fn eval_multi(&mut self, e: &Expr, scope: &Rc<Scope>) -> LResult<Vec<Value>> {
        match &e.kind {
            ExprKind::Call(fexpr, args) => {
                self.set_line(e.line);
                let f = self.eval(fexpr, scope)?;
                let argv = self.eval_exprlist(args, scope)?;
                self.set_line(e.line);
                let name = self.call_name_of(fexpr, scope);
                let info = self.varinfo(fexpr, scope);
                self.call_value(f, argv, name, Some(info))
            }
            ExprKind::Method(obj, name, args) => {
                self.set_line(e.line);
                let o = self.eval(obj, scope)?;
                let key = Value::str(name);
                let f = self.index_value(o.clone(), key, obj, scope)?;
                let mut argv = vec![o];
                let mut rest = self.eval_exprlist(args, scope)?;
                argv.append(&mut rest);
                self.set_line(e.line);
                self.call_value(f, argv, CallName::Method(name.clone()), Some(format!(" (method '{}')", name)))
            }
            ExprKind::Vararg => {
                match scope.lookup("...") {
                    Some((cell, _)) => {
                        let v = cell.borrow();
                        if let Value::Table(t) = &*v {
                            return Ok(t.borrow().arr.clone());
                        }
                        Ok(vec![])
                    }
                    None => Ok(vec![]),
                }
            }
            _ => Ok(vec![self.eval(e, scope)?]),
        }
    }

    pub fn eval(&mut self, e: &Expr, scope: &Rc<Scope>) -> LResult<Value> {
        match &e.kind {
            ExprKind::Nil => Ok(Value::Nil),
            ExprKind::True => Ok(Value::Bool(true)),
            ExprKind::False => Ok(Value::Bool(false)),
            ExprKind::Int(i) => Ok(Value::Int(*i)),
            ExprKind::Flt(f) => Ok(Value::Flt(*f)),
            ExprKind::Str(s) => Ok(Value::Str(s.clone())),
            ExprKind::Vararg => Ok(self.eval_multi(e, scope)?.into_iter().next().unwrap_or(Value::Nil)),
            ExprKind::Name(n) => {
                match scope.lookup(n) {
                    Some((cell, _)) => Ok(cell.borrow().clone()),
                    None => {
                        let v = self.globals.borrow().get_str(n);
                        if v.is_nil() {
                            // honour __index on globals
                            let g = Value::Table(self.globals.clone());
                            if !self.get_metamethod(&g, "__index").is_nil() {
                                return self.index_value(g, Value::str(n), e, scope);
                            }
                        }
                        Ok(v)
                    }
                }
            }
            ExprKind::Index(obj, key) => {
                let o = self.eval(obj, scope)?;
                let k = self.eval(key, scope)?;
                self.set_line(e.line);
                self.index_value(o, k, obj, scope)
            }
            ExprKind::Call(..) | ExprKind::Method(..) => {
                Ok(self.eval_multi(e, scope)?.into_iter().next().unwrap_or(Value::Nil))
            }
            ExprKind::Function(def) => Ok(self.make_closure(def, scope)),
            ExprKind::Paren(inner) => self.eval(inner, scope),
            ExprKind::And(a, b) => {
                let va = self.eval(a, scope)?;
                if !va.truthy() { Ok(va) } else { self.eval(b, scope) }
            }
            ExprKind::Or(a, b) => {
                let va = self.eval(a, scope)?;
                if va.truthy() { Ok(va) } else { self.eval(b, scope) }
            }
            ExprKind::Un(op, operand) => {
                let v = self.eval(operand, scope)?;
                self.set_line(e.line);
                match op {
                    UnOp::Not => Ok(Value::Bool(!v.truthy())),
                    UnOp::Neg => self.arith(BinOp::Sub, v.clone(), v, Some((operand, operand)), scope, true),
                    UnOp::Len => self.length(v, operand, scope),
                    UnOp::BNot => self.bitwise(BinOp::BXor, v.clone(), v, Some((operand, operand)), scope, true),
                }
            }
            ExprKind::Bin(op, a, b) => {
                let va = self.eval(a, scope)?;
                let vb = self.eval(b, scope)?;
                self.set_line(e.line);
                self.binop(*op, va, vb, Some((a, b)), scope)
            }
            ExprKind::Table(fields) => {
                let t = Rc::new(RefCell::new(Table::new()));
                let mut pos: i64 = 1;
                for (i, f) in fields.iter().enumerate() {
                    match f {
                        TableField::Pos(ex) => {
                            if i + 1 == fields.len() {
                                let vs = self.eval_multi(ex, scope)?;
                                for v in vs { t.borrow_mut().set_int(pos, v); pos += 1; }
                            } else {
                                let v = self.eval(ex, scope)?;
                                t.borrow_mut().set_int(pos, v);
                                pos += 1;
                            }
                        }
                        TableField::Named(k, ex) => {
                            let v = self.eval(ex, scope)?;
                            t.borrow_mut().set_key(Key::Str(k.clone()), v);
                        }
                        TableField::Keyed(kx, ex) => {
                            let k = self.eval(kx, scope)?;
                            let v = self.eval(ex, scope)?;
                            self.set_line(e.line);
                            if let Err(m) = t.borrow_mut().set(k, v) {
                                return Err(self.rt_error(m, "?"));
                            }
                        }
                    }
                }
                Ok(Value::Table(t))
            }
        }
    }

    // ------------------------------------------------------------------
    // indexing

    /// index with error context expression `obj_expr` (for messages)
    pub fn index_value(&mut self, obj: Value, key: Value, obj_expr: &Expr, scope: &Rc<Scope>) -> LResult<Value> {
        let info = self.varinfo(obj_expr, scope);
        self.index_with_info(obj, key, &info)
    }

    pub fn index_with_info(&mut self, obj: Value, key: Value, info: &str) -> LResult<Value> {
        let mut cur = obj;
        let mut first = true;
        for _ in 0..100 {
            match &cur {
                Value::Table(t) => {
                    let v = t.borrow().get(&key);
                    if !v.is_nil() { return Ok(v); }
                    let h = self.get_metamethod(&cur, "__index");
                    match h {
                        Value::Nil => return Ok(Value::Nil),
                        Value::Func(_) => {
                            let r = self.call_value(h, vec![cur.clone(), key], CallName::Unknown, None)?;
                            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                        }
                        other => { cur = other; first = false; continue; }
                    }
                }
                Value::Str(_) => {
                    let h = self.string_meta.borrow().get_str("__index");
                    match h {
                        Value::Nil => {
                            let msg = format!("attempt to index a string value{}", if first { info } else { "" });
                            return Err(self.rt_error(&msg, "metamethod 'index'"));
                        }
                        Value::Func(_) => {
                            let r = self.call_value(h, vec![cur.clone(), key], CallName::Unknown, None)?;
                            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                        }
                        other => { cur = other; first = false; continue; }
                    }
                }
                _ => {
                    let msg = format!("attempt to index a {} value{}", self.obj_type_name(&cur), if first { info } else { "" });
                    return Err(self.rt_error(&msg, "metamethod 'index'"));
                }
            }
        }
        Err(self.rt_error("'__index' chain too long; possible loop", "metamethod 'index'"))
    }

    fn set_index(&mut self, obj: Value, key: Value, val: Value, obj_expr: &Expr, scope: &Rc<Scope>) -> LResult<()> {
        let info = self.varinfo(obj_expr, scope);
        self.set_table(obj, key, val, Some(&info))
    }

    pub fn set_table(&mut self, obj: Value, key: Value, val: Value, info: Option<&str>) -> LResult<()> {
        let mut cur = obj;
        let mut first = true;
        for _ in 0..100 {
            match &cur {
                Value::Table(t) => {
                    let existing = t.borrow().get(&key);
                    if existing.is_nil() {
                        let h = self.get_metamethod(&cur, "__newindex");
                        match h {
                            Value::Nil => {}
                            Value::Func(_) => {
                                self.call_value(h, vec![cur.clone(), key, val], CallName::Unknown, None)?;
                                return Ok(());
                            }
                            other => { cur = other; first = false; continue; }
                        }
                    }
                    let r = t.borrow_mut().set(key, val);
                    if let Err(m) = r {
                        return Err(self.rt_error(m, "metamethod 'newindex'"));
                    }
                    return Ok(());
                }
                _ => {
                    let msg = format!("attempt to index a {} value{}", self.obj_type_name(&cur), if first { info.unwrap_or("") } else { "" });
                    return Err(self.rt_error(&msg, "metamethod 'newindex'"));
                }
            }
        }
        Err(self.rt_error("'__newindex' chain too long; possible loop", "metamethod 'newindex'"))
    }

    // ------------------------------------------------------------------
    // calls

    pub fn call_value(&mut self, f: Value, args: Vec<Value>, name: CallName, info: Option<String>) -> LResult<Vec<Value>> {
        match f {
            Value::Func(func) => self.call_function(func, args, name),
            other => {
                let h = self.get_metamethod(&other, "__call");
                if let Value::Func(hf) = h {
                    let mut a = vec![other];
                    a.extend(args);
                    return self.call_function(hf, a, name);
                }
                let info = info.unwrap_or_default();
                let msg = format!("attempt to call a {} value{}", self.obj_type_name(&other), info);
                let ctx = name.traceback_desc().unwrap_or_else(|| "?".to_string());
                Err(self.rt_error(&msg, &ctx))
            }
        }
    }

    pub fn call_function(&mut self, func: FuncRef, args: Vec<Value>, name: CallName) -> LResult<Vec<Value>> {
        if self.depth >= MAX_DEPTH {
            return Err(self.rt_error("stack overflow", "?"));
        }
        self.depth += 1;
        let r = match &*func {
            Function::Native(nf) => {
                self.frames.push(Frame { kind: FrameKind::Native { name: nf.name }, line: 0, call_name: name });
                let r = (nf.f)(self, args);
                self.frames.pop();
                r
            }
            Function::Lua(cl) => {
                let def = cl.def.clone();
                let func_id = self.next_func_id;
                self.next_func_id += 1;
                let scope = Scope::new(Some(cl.env.clone()), func_id);
                let nparams = def.params.len();
                for (i, p) in def.params.iter().enumerate() {
                    scope.declare(p, args.get(i).cloned().unwrap_or(Value::Nil));
                }
                if def.is_vararg {
                    let extra: Vec<Value> = if args.len() > nparams { args[nparams..].to_vec() } else { vec![] };
                    let t = Rc::new(RefCell::new(Table::new()));
                    t.borrow_mut().arr = extra;
                    scope.declare("...", Value::Table(t));
                }
                self.frames.push(Frame { kind: FrameKind::Lua { def: def.clone(), func: func.clone() }, line: def.line, call_name: name });
                let r = self.exec_stmts(&def.body.stmts, &scope);
                self.frames.pop();
                match r {
                    Ok(Flow::Return(v)) => Ok(v),
                    Ok(_) => Ok(vec![]),
                    Err(e) => Err(e),
                }
            }
        };
        self.depth -= 1;
        r
    }

    // ------------------------------------------------------------------
    // operators

    fn binop(&mut self, op: BinOp, a: Value, b: Value, exprs: Option<(&Expr, &Expr)>, scope: &Rc<Scope>) -> LResult<Value> {
        match op {
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod | BinOp::Pow | BinOp::IDiv => {
                self.arith(op, a, b, exprs, scope, false)
            }
            BinOp::BAnd | BinOp::BOr | BinOp::BXor | BinOp::Shl | BinOp::Shr => {
                self.bitwise(op, a, b, exprs, scope, false)
            }
            BinOp::Concat => self.concat(a, b, exprs, scope),
            BinOp::Eq => Ok(Value::Bool(self.equals(&a, &b)?)),
            BinOp::Ne => Ok(Value::Bool(!self.equals(&a, &b)?)),
            BinOp::Lt => Ok(Value::Bool(self.less_than(&a, &b)?)),
            BinOp::Le => Ok(Value::Bool(self.less_equal(&a, &b)?)),
            BinOp::Gt => Ok(Value::Bool(self.less_than(&b, &a)?)),
            BinOp::Ge => Ok(Value::Bool(self.less_equal(&b, &a)?)),
        }
    }

    pub fn equals(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        if a.raw_eq(b) { return Ok(true); }
        if let (Value::Table(ta), Value::Table(tb)) = (a, b) {
            let _ = (ta, tb);
            let mut h = self.get_metamethod(a, "__eq");
            if h.is_nil() { h = self.get_metamethod(b, "__eq"); }
            if !h.is_nil() {
                let r = self.call_value(h, vec![a.clone(), b.clone()], CallName::Unknown, None)?;
                return Ok(r.get(0).map_or(false, |v| v.truthy()));
            }
        }
        Ok(false)
    }

    fn order_error(&self, a: &Value, b: &Value, mm: &str) -> LuaError {
        let t1 = self.obj_type_name(a);
        let t2 = self.obj_type_name(b);
        let msg = if t1 == t2 {
            format!("attempt to compare two {} values", t1)
        } else {
            format!("attempt to compare {} with {}", t1, t2)
        };
        self.rt_error(&msg, &format!("metamethod '{}'", mm))
    }

    pub fn less_than(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        match (a, b) {
            (Value::Int(x), Value::Int(y)) => Ok(x < y),
            (Value::Flt(x), Value::Flt(y)) => Ok(x < y),
            (Value::Int(x), Value::Flt(y)) => Ok(int_lt_flt(*x, *y)),
            (Value::Flt(x), Value::Int(y)) => Ok(flt_lt_int(*x, *y)),
            (Value::Str(x), Value::Str(y)) => Ok(x.as_slice() < y.as_slice()),
            _ => {
                let mut h = self.get_metamethod(a, "__lt");
                if h.is_nil() { h = self.get_metamethod(b, "__lt"); }
                if !h.is_nil() {
                    let r = self.call_value(h, vec![a.clone(), b.clone()], CallName::Unknown, None)?;
                    return Ok(r.get(0).map_or(false, |v| v.truthy()));
                }
                Err(self.order_error(a, b, "lt"))
            }
        }
    }

    pub fn less_equal(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        match (a, b) {
            (Value::Int(x), Value::Int(y)) => Ok(x <= y),
            (Value::Flt(x), Value::Flt(y)) => Ok(x <= y),
            (Value::Int(x), Value::Flt(y)) => Ok(int_le_flt(*x, *y)),
            (Value::Flt(x), Value::Int(y)) => Ok(flt_le_int(*x, *y)),
            (Value::Str(x), Value::Str(y)) => Ok(x.as_slice() <= y.as_slice()),
            _ => {
                let mut h = self.get_metamethod(a, "__le");
                if h.is_nil() { h = self.get_metamethod(b, "__le"); }
                if !h.is_nil() {
                    let r = self.call_value(h, vec![a.clone(), b.clone()], CallName::Unknown, None)?;
                    return Ok(r.get(0).map_or(false, |v| v.truthy()));
                }
                Err(self.order_error(a, b, "le"))
            }
        }
    }

    fn length(&mut self, v: Value, operand: &Expr, scope: &Rc<Scope>) -> LResult<Value> {
        match &v {
            Value::Str(s) => Ok(Value::Int(s.len() as i64)),
            Value::Table(t) => {
                let h = self.get_metamethod(&v, "__len");
                if !h.is_nil() {
                    let r = self.call_value(h, vec![v.clone()], CallName::Unknown, None)?;
                    return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                }
                Ok(Value::Int(t.borrow().len()))
            }
            _ => {
                let h = self.get_metamethod(&v, "__len");
                if !h.is_nil() {
                    let r = self.call_value(h, vec![v.clone()], CallName::Unknown, None)?;
                    return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                }
                let info = self.varinfo(operand, scope);
                let msg = format!("attempt to get length of a {} value{}", self.obj_type_name(&v), info);
                Err(self.rt_error(&msg, "metamethod 'len'"))
            }
        }
    }

    fn concat(&mut self, a: Value, b: Value, exprs: Option<(&Expr, &Expr)>, scope: &Rc<Scope>) -> LResult<Value> {
        let sa = to_str_coerce(&a);
        let sb = to_str_coerce(&b);
        if let (Some(x), Some(y)) = (&sa, &sb) {
            let mut v = Vec::with_capacity(x.len() + y.len());
            v.extend_from_slice(x);
            v.extend_from_slice(y);
            return Ok(Value::bytes(v));
        }
        let mut h = self.get_metamethod(&a, "__concat");
        if h.is_nil() { h = self.get_metamethod(&b, "__concat"); }
        if !h.is_nil() {
            let r = self.call_value(h, vec![a, b], CallName::Unknown, None)?;
            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
        }
        // error: describe the non-string operand
        let (bad, bad_expr) = if sa.is_some() { (&b, exprs.map(|e| e.1)) } else { (&a, exprs.map(|e| e.0)) };
        let info = bad_expr.map(|e| self.varinfo(e, scope)).unwrap_or_default();
        let msg = format!("attempt to concatenate a {} value{}", self.obj_type_name(bad), info);
        Err(self.rt_error(&msg, "metamethod 'concat'"))
    }

    pub fn arith(&mut self, op: BinOp, a: Value, b: Value, exprs: Option<(&Expr, &Expr)>, scope: &Rc<Scope>, unary: bool) -> LResult<Value> {
        // fast path: numbers
        if let (Some(x), Some(y)) = (as_number(&a), as_number(&b)) {
            return self.arith_num(op, x, y, unary);
        }
        // metamethods
        let mm = arith_mm_name(op, unary);
        let mut h = self.get_metamethod(&a, mm);
        if h.is_nil() { h = self.get_metamethod(&b, mm); }
        if !h.is_nil() {
            // string metamethod emulation
            if a.is_string_like() || b.is_string_like() {
                if let Value::Func(_) = &h {
                    // if the metamethod is the string library's builtin arith we handle it here
                }
            }
            if self.is_string_arith_mm(&h) {
                let ca = coerce_to_number(&a);
                let cb = coerce_to_number(&b);
                if let (Some(x), Some(y)) = (ca, cb) {
                    return self.arith_num(op, x, y, unary);
                }
                // trymt: error
                let name = &mm[2..];
                let msg = format!("attempt to {} a '{}' with a '{}'", name, self.obj_type_name(&a), self.obj_type_name(&b));
                // raised inside the string metamethod (a C function)
                let full = format!("{}{}", self.where_(0), msg);
                let mut tb = String::from("stack traceback:\n\t[C]: in ?");
                tb.push_str(&format!("\n\t[C]: in metamethod '{}'", name));
                for f in self.frames.iter().rev() {
                    tb.push('\n'); tb.push('\t'); tb.push_str(&self.frame_desc(f));
                }
                return Err(LuaError { value: Value::str(&full), traceback: Some(tb) });
            }
            let r = self.call_value(h, vec![a, b], CallName::Unknown, None)?;
            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
        }
        // error
        let (bad, bad_expr) = if as_number(&a).is_some() { (&b, exprs.map(|e| e.1)) } else { (&a, exprs.map(|e| e.0)) };
        let info = bad_expr.map(|e| self.varinfo(e, scope)).unwrap_or_default();
        let msg = format!("attempt to perform arithmetic on a {} value{}", self.obj_type_name(bad), info);
        Err(self.rt_error(&msg, &format!("metamethod '{}'", &mm[2..])))
    }

    fn is_string_arith_mm(&self, h: &Value) -> bool {
        if let Value::Func(f) = h {
            if let Function::Native(nf) = &**f {
                return nf.name.starts_with("string.__");
            }
        }
        false
    }

    pub fn arith_num(&mut self, op: BinOp, x: Num, y: Num, unary: bool) -> LResult<Value> {
        if unary {
            // negation
            return Ok(match x { Num::I(i) => Value::Int(i.wrapping_neg()), Num::F(f) => Value::Flt(-f) });
        }
        Ok(match op {
            BinOp::Add => match (x, y) { (Num::I(a), Num::I(b)) => Value::Int(a.wrapping_add(b)), _ => Value::Flt(x.f() + y.f()) },
            BinOp::Sub => match (x, y) { (Num::I(a), Num::I(b)) => Value::Int(a.wrapping_sub(b)), _ => Value::Flt(x.f() - y.f()) },
            BinOp::Mul => match (x, y) { (Num::I(a), Num::I(b)) => Value::Int(a.wrapping_mul(b)), _ => Value::Flt(x.f() * y.f()) },
            BinOp::Div => Value::Flt(x.f() / y.f()),
            BinOp::Pow => Value::Flt(pow(x.f(), y.f())),
            BinOp::IDiv => match (x, y) {
                (Num::I(a), Num::I(b)) => {
                    if b == 0 { return Err(self.rt_error("attempt to perform 'n//0'", "?")); }
                    Value::Int(int_floor_div(a, b))
                }
                _ => Value::Flt((x.f() / y.f()).floor()),
            },
            BinOp::Mod => match (x, y) {
                (Num::I(a), Num::I(b)) => {
                    if b == 0 { return Err(self.rt_error("attempt to perform 'n%%0'", "?")); }
                    Value::Int(int_mod(a, b))
                }
                _ => Value::Flt(flt_mod(x.f(), y.f())),
            },
            _ => unreachable!(),
        })
    }

    fn bitwise(&mut self, op: BinOp, a: Value, b: Value, exprs: Option<(&Expr, &Expr)>, scope: &Rc<Scope>, unary: bool) -> LResult<Value> {
        let ia = to_int_strict(&a);
        let ib = to_int_strict(&b);
        if let (Some(x), Some(y)) = (ia, ib) {
            let r = match op {
                BinOp::BAnd => x & y,
                BinOp::BOr => x | y,
                BinOp::BXor => if unary { !x } else { x ^ y },
                BinOp::Shl => shift_left(x, y),
                BinOp::Shr => shift_left(x, y.wrapping_neg()),
                _ => unreachable!(),
            };
            return Ok(Value::Int(r));
        }
        let mm = match op {
            BinOp::BAnd => "__band", BinOp::BOr => "__bor",
            BinOp::BXor => if unary { "__bnot" } else { "__bxor" },
            BinOp::Shl => "__shl", BinOp::Shr => "__shr", _ => unreachable!(),
        };
        let mut h = self.get_metamethod(&a, mm);
        if h.is_nil() { h = self.get_metamethod(&b, mm); }
        if !h.is_nil() {
            let r = self.call_value(h, vec![a, b], CallName::Unknown, None)?;
            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
        }
        let ctx = format!("metamethod '{}'", &mm[2..]);
        if as_number(&a).is_some() && as_number(&b).is_some() {
            return Err(self.rt_error("number has no integer representation", &ctx));
        }
        let (bad, bad_expr) = if as_number(&a).is_some() { (&b, exprs.map(|e| e.1)) } else { (&a, exprs.map(|e| e.0)) };
        let info = bad_expr.map(|e| self.varinfo(e, scope)).unwrap_or_default();
        let msg = format!("attempt to perform bitwise operation on a {} value{}", self.obj_type_name(bad), info);
        Err(self.rt_error(&msg, &ctx))
    }

    // ------------------------------------------------------------------
    // tostring

    pub fn tostring(&mut self, v: &Value) -> LResult<Vec<u8>> {
        let h = self.get_metamethod(v, "__tostring");
        if !h.is_nil() {
            let r = self.call_value(h, vec![v.clone()], CallName::Unknown, None)?;
            match r.into_iter().next() {
                Some(Value::Str(s)) => return Ok((*s).clone()),
                Some(Value::Int(i)) => return Ok(i.to_string().into_bytes()),
                Some(Value::Flt(f)) => return Ok(lua_float_to_string(f).into_bytes()),
                _ => return Err(self.lib_error("'__tostring' must return a string")),
            }
        }
        if let Value::Table(t) = v {
            if let Some(mt) = &t.borrow().meta {
                if let Value::Str(name) = mt.borrow().get_str("__name") {
                    return Ok(format!("{}: {:p}", String::from_utf8_lossy(&name), Rc::as_ptr(t)).into_bytes());
                }
            }
        }
        Ok(tostring_basic(v))
    }
}

pub fn tostring_basic(v: &Value) -> Vec<u8> {
    match v {
        Value::Nil => b"nil".to_vec(),
        Value::Bool(b) => if *b { b"true".to_vec() } else { b"false".to_vec() },
        Value::Int(i) => i.to_string().into_bytes(),
        Value::Flt(f) => lua_float_to_string(*f).into_bytes(),
        Value::Str(s) => (**s).clone(),
        Value::Table(t) => format!("table: {:p}", Rc::as_ptr(t)).into_bytes(),
        Value::Func(f) => {
            match &**f {
                Function::Native(_) => format!("builtin: {:p}", Rc::as_ptr(f)).into_bytes(),
                _ => format!("function: {:p}", Rc::as_ptr(f)).into_bytes(),
            }
        }
    }
}

impl Value {
    fn is_string_like(&self) -> bool { matches!(self, Value::Str(_)) }
}

#[derive(Clone, Copy)]
pub enum Num { I(i64), F(f64) }
impl Num {
    pub fn f(self) -> f64 { match self { Num::I(i) => i as f64, Num::F(f) => f } }
}

pub fn as_number(v: &Value) -> Option<Num> {
    match v {
        Value::Int(i) => Some(Num::I(*i)),
        Value::Flt(f) => Some(Num::F(*f)),
        _ => None,
    }
}

/// number or numeric string
pub fn coerce_to_number(v: &Value) -> Option<Num> {
    match v {
        Value::Int(i) => Some(Num::I(*i)),
        Value::Flt(f) => Some(Num::F(*f)),
        Value::Str(s) => match str_to_number(s) {
            Some(Number::Int(i)) => Some(Num::I(i)),
            Some(Number::Flt(f)) => Some(Num::F(f)),
            None => None,
        },
        _ => None,
    }
}

fn to_f(v: &Value) -> f64 {
    match v { Value::Int(i) => *i as f64, Value::Flt(f) => *f, _ => 0.0 }
}

/// integer conversion for bitwise ops (no string coercion)
fn to_int_strict(v: &Value) -> Option<i64> {
    match v {
        Value::Int(i) => Some(*i),
        Value::Flt(f) => flt_to_int_exact(*f),
        _ => None,
    }
}

fn to_str_coerce(v: &Value) -> Option<Vec<u8>> {
    match v {
        Value::Str(s) => Some((**s).clone()),
        Value::Int(i) => Some(i.to_string().into_bytes()),
        Value::Flt(f) => Some(lua_float_to_string(*f).into_bytes()),
        _ => None,
    }
}

fn arith_mm_name(op: BinOp, unary: bool) -> &'static str {
    if unary { return "__unm"; }
    match op {
        BinOp::Add => "__add", BinOp::Sub => "__sub", BinOp::Mul => "__mul", BinOp::Div => "__div",
        BinOp::Mod => "__mod", BinOp::Pow => "__pow", BinOp::IDiv => "__idiv",
        _ => "__add",
    }
}

pub fn int_floor_div(a: i64, b: i64) -> i64 {
    if b == -1 { return a.wrapping_neg(); }
    let q = a / b;
    if (a % b != 0) && ((a < 0) != (b < 0)) { q - 1 } else { q }
}

pub fn int_mod(a: i64, b: i64) -> i64 {
    if b == -1 { return 0; }
    let r = a % b;
    if r != 0 && (r ^ b) < 0 { r + b } else { r }
}

pub fn flt_mod(a: f64, b: f64) -> f64 {
    let mut m = a % b;
    if (m > 0.0 && b < 0.0) || (m < 0.0 && b > 0.0 && m != b) { m += b; }
    m
}

fn pow(a: f64, b: f64) -> f64 {
    if b == 2.0 { a * a } else { a.powf(b) }
}

pub fn shift_left(x: i64, n: i64) -> i64 {
    if n <= -64 || n >= 64 { 0 }
    else if n >= 0 { ((x as u64) << n) as i64 }
    else { ((x as u64) >> (-n)) as i64 }
}

fn int_lt_flt(i: i64, f: f64) -> bool {
    if f.is_nan() { return false; }
    if f >= 9223372036854775808.0 { return true; }
    if f <= -9223372036854775808.0 { return false; }
    // compare i < f  <=> i < ceil(f) when f not integral, i < f when integral
    let fl = f.floor();
    if fl == f { i < f as i64 } else { i <= fl as i64 }
}
fn int_le_flt(i: i64, f: f64) -> bool {
    if f.is_nan() { return false; }
    if f >= 9223372036854775808.0 { return true; }
    if f < -9223372036854775808.0 { return false; }
    i <= f.floor() as i64
}
fn flt_lt_int(f: f64, i: i64) -> bool {
    if f.is_nan() { return false; }
    if f >= 9223372036854775808.0 { return false; }
    if f < -9223372036854775808.0 { return true; }
    let cl = f.ceil();
    if cl == f { (f as i64) < i } else { (cl as i64) <= i }
}
fn flt_le_int(f: f64, i: i64) -> bool {
    if f.is_nan() { return false; }
    if f >= 9223372036854775808.0 { return false; }
    if f < -9223372036854775808.0 { return true; }
    f.ceil() as i64 <= i
}
