use std::rc::Rc;

fn native(name: &'static str, f: NativeFn) -> Value {
    Value::Func(Rc::new(Function::Native(NativeFunction { name, f })))
}

fn reg(t: &TableRef, name: &str, qname: &'static str, f: NativeFn) {
    t.borrow_mut().set_str(name, native(qname, f));
}

pub fn install(it: &mut Interp) {
    let g = it.globals.clone();
    g.borrow_mut().set_str("_G", Value::Table(g.clone()));
    g.borrow_mut().set_str("_VERSION", Value::str("Lua 5.4"));
    reg(&g, "assert", "assert", lua_assert);
    reg(&g, "error", "error", lua_error);
    reg(&g, "getmetatable", "getmetatable", lua_getmetatable);
