// argument helpers

fn arg(args: &[Value], i: usize) -> Option<&Value> { args.get(i) }

fn check_any(it: &Interp, args: &[Value], i: usize) -> LResult<Value> {
    match args.get(i) {
        Some(v) => Ok(v.clone()),
        None => Err(it.arg_error(i + 1, "value expected")),
    }
}

pub fn check_str(it: &Interp, args: &[Value], i: usize) -> LResult<Vec<u8>> {
    match args.get(i) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(Value::Int(n)) => Ok(n.to_string().into_bytes()),
        Some(Value::Flt(f)) => Ok(lua_float_to_string(*f).into_bytes()),
        other => Err(it.type_error(i + 1, "string", other)),
    }
}

fn opt_str(it: &Interp, args: &[Value], i: usize) -> LResult<Option<Vec<u8>>> {
    match args.get(i) {
        None | Some(Value::Nil) => Ok(None),
        _ => Ok(Some(check_str(it, args, i)?)),
    }
}

fn check_int(it: &Interp, args: &[Value], i: usize) -> LResult<i64> {
    match args.get(i) {
        Some(Value::Int(n)) => Ok(*n),
        Some(Value::Flt(f)) => match flt_to_int_exact(*f) {
            Some(n) => Ok(n),
            None => Err(it.arg_error(i + 1, "number has no integer representation")),
        },
        Some(Value::Str(s)) => match str_to_number(s) {
            Some(Number::Int(n)) => Ok(n),
            Some(Number::Flt(f)) => match flt_to_int_exact(f) {
                Some(n) => Ok(n),
                None => Err(it.arg_error(i + 1, "number has no integer representation")),
            },
            None => Err(it.type_error(i + 1, "number", args.get(i))),
        },
        other => Err(it.type_error(i + 1, "number", other)),
    }
}

fn opt_int(it: &Interp, args: &[Value], i: usize, def: i64) -> LResult<i64> {
    match args.get(i) {
        None | Some(Value::Nil) => Ok(def),
        _ => check_int(it, args, i),
    }
}

fn check_num(it: &Interp, args: &[Value], i: usize) -> LResult<f64> {
    match args.get(i) {
        Some(Value::Int(n)) => Ok(*n as f64),
        Some(Value::Flt(f)) => Ok(*f),
        Some(Value::Str(s)) => match str_to_number(s) {
            Some(Number::Int(n)) => Ok(n as f64),
            Some(Number::Flt(f)) => Ok(f),
            None => Err(it.type_error(i + 1, "number", args.get(i))),
        },
        other => Err(it.type_error(i + 1, "number", other)),
    }
}

fn check_number(it: &Interp, args: &[Value], i: usize) -> LResult<Num> {
    match args.get(i) {
        Some(Value::Int(n)) => Ok(Num::I(*n)),
        Some(Value::Flt(f)) => Ok(Num::F(*f)),
        Some(Value::Str(s)) => match str_to_number(s) {
            Some(Number::Int(n)) => Ok(Num::I(n)),
            Some(Number::Flt(f)) => Ok(Num::F(f)),
            None => Err(it.type_error(i + 1, "number", args.get(i))),
        },
        other => Err(it.type_error(i + 1, "number", other)),
    }
}

fn check_table(it: &Interp, args: &[Value], i: usize) -> LResult<TableRef> {
    match args.get(i) {
        Some(Value::Table(t)) => Ok(t.clone()),
        other => Err(it.type_error(i + 1, "table", other)),
    }
}

fn nil() -> Vec<Value> { vec![Value::Nil] }

// ----------------------------------------------------------------------
// base library

fn lua_assert(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    if v.truthy() { return Ok(args); }
    if args.len() >= 2 {
        let msg = args[1].clone();
        return Err(error_with_value(it, msg, 1));
    }
    Err(it.lib_error("assertion failed!"))
}

fn error_with_value(it: &Interp, v: Value, level: i64) -> LuaError {
    // like lua_error: strings at level>0 get position info
    match (&v, level) {
        (Value::Str(s), l) if l > 0 => {
            let pos = it.where_(l as usize);
            let mut m = pos.into_bytes();
            m.extend_from_slice(s);
            it.lib_error_nopos(Value::bytes(m))
        }
        _ => it.lib_error_nopos(v),
    }
}

fn lua_error(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = args.get(0).cloned().unwrap_or(Value::Nil);
    let level = opt_int(it, &args, 1, 1)?;
    Err(error_with_value(it, v, level))
}

fn lua_getmetatable(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    match it.get_metatable(&v) {
        Some(mt) => {
            let protected = mt.borrow().get_str("__metatable");
            if !protected.is_nil() { return Ok(vec![protected]); }
            Ok(vec![Value::Table(mt)])
        }
        None => Ok(nil()),
    }
}

fn lua_setmetatable(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let mt = match args.get(1) {
        Some(Value::Nil) => None,
        Some(Value::Table(m)) => Some(m.clone()),
        other => return Err(it.type_error(2, "nil or table", other)),
    };
    if let Some(old) = &t.borrow().meta {
        if !old.borrow().get_str("__metatable").is_nil() {
            return Err(it.lib_error("cannot change a protected metatable"));
        }
    }
    t.borrow_mut().meta = mt;
    Ok(vec![Value::Table(t)])
}

fn ipairs_iter(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let i = check_int(it, &args, 1)?.wrapping_add(1);
    let t = args.get(0).cloned().unwrap_or(Value::Nil);
    let v = it.index_with_info(t, Value::Int(i), "")?;
    if v.is_nil() { return Ok(nil()); }
    Ok(vec![Value::Int(i), v])
}

fn lua_ipairs(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    Ok(vec![native("ipairs_iter", ipairs_iter), v, Value::Int(0)])
}

fn lua_next(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let k = args.get(1).cloned().unwrap_or(Value::Nil);
    let r = t.borrow().next(&k);
    match r {
        Ok(Some((k, v))) => Ok(vec![k, v]),
        Ok(None) => Ok(nil()),
        Err(()) => Err(it.lib_error("invalid key to 'next'")),
    }
}

fn lua_pairs(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    let h = it.get_metamethod(&v, "__pairs");
    if !h.is_nil() {
        let mut r = it.call_value(h, vec![v], CallName::Unknown, None)?;
        r.resize(3, Value::Nil);
        return Ok(r);
    }
    Ok(vec![native("next", lua_next), v, Value::Nil])
}

fn lua_print(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut out = Vec::new();
    for (i, a) in args.iter().enumerate() {
        if i > 0 { out.push(b'\t'); }
        let s = it.tostring(a)?;
        out.extend(s);
    }
    out.push(b'\n');
    it.write_out(&out);
    Ok(vec![])
}

fn lua_rawequal(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let a = check_any(it, &args, 0)?;
    let b = check_any(it, &args, 1)?;
    Ok(vec![Value::Bool(a.raw_eq(&b))])
}

fn lua_rawget(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let k = check_any(it, &args, 1)?;
    Ok(vec![t.borrow().get(&k)])
}

fn lua_rawset(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let k = check_any(it, &args, 1)?;
    let v = check_any(it, &args, 2)?;
    if let Err(m) = t.borrow_mut().set(k, v) { return Err(it.lib_error(m)); }
    Ok(vec![Value::Table(t)])
}

fn lua_rawlen(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    match args.get(0) {
        Some(Value::Table(t)) => Ok(vec![Value::Int(t.borrow().len())]),
        Some(Value::Str(s)) => Ok(vec![Value::Int(s.len() as i64)]),
        _ => Err(it.arg_error(1, "table or string expected")),
    }
}

fn lua_select(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let n = args.len() as i64 - 1;
    if let Some(Value::Str(s)) = args.get(0) {
        if s.as_slice() == b"#" { return Ok(vec![Value::Int(n)]); }
    }
    let i = check_int(it, &args, 0)?;
    if i < 0 {
        let i = n + i;
        if i < 0 { return Err(it.arg_error(1, "index out of range")); }
        return Ok(args[(i + 1) as usize..].to_vec());
    } else if i == 0 {
        return Err(it.arg_error(1, "index out of range"));
    }
    if i > n { return Ok(vec![]); }
    Ok(args[i as usize..].to_vec())
}

fn lua_tonumber(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    if args.len() < 2 || args[1].is_nil() {
        match args.get(0) {
            Some(Value::Int(_)) | Some(Value::Flt(_)) => return Ok(vec![args[0].clone()]),
            Some(Value::Str(s)) => {
                return Ok(vec![match str_to_number(s) {
                    Some(Number::Int(i)) => Value::Int(i),
                    Some(Number::Flt(f)) => Value::Flt(f),
                    None => Value::Nil,
                }]);
            }
            Some(_) => return Ok(nil()),
            None => return Err(it.arg_error(1, "value expected")),
        }
    }
    let base = check_int(it, &args, 1)?;
    let s = match args.get(0) {
        Some(Value::Str(s)) => (**s).clone(),
        other => return Err(it.type_error(1, "string", other)),
    };
    if !(2..=36).contains(&base) { return Err(it.arg_error(2, "base out of range")); }
    let t = String::from_utf8_lossy(&s).trim().to_lowercase();
    let (neg, body) = match t.strip_prefix('-') { Some(b) => (true, b.to_string()), None => (false, t.strip_prefix('+').map(|s| s.to_string()).unwrap_or(t.clone())) };
    if body.is_empty() { return Ok(nil()); }
    let mut n: i64 = 0;
    for c in body.chars() {
        let d = match c.to_digit(36) { Some(d) if (d as i64) < base => d as i64, _ => return Ok(nil()) };
        n = n.wrapping_mul(base).wrapping_add(d);
    }
    Ok(vec![Value::Int(if neg { n.wrapping_neg() } else { n })])
}

fn lua_tostring(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    let s = it.tostring(&v)?;
    Ok(vec![Value::bytes(s)])
}

fn lua_type(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    Ok(vec![Value::str(v.type_name())])
}

fn lua_pcall(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let f = check_any(it, &args, 0)?;
    let rest = args[1..].to_vec();
    let depth = it.frames.len();
    match it.call_value(f, rest, CallName::Unknown, None) {
        Ok(mut r) => { r.insert(0, Value::Bool(true)); Ok(r) }
        Err(e) => {
            it.frames.truncate(depth);
            Ok(vec![Value::Bool(false), e.value])
        }
    }
}

fn lua_xpcall(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let f = check_any(it, &args, 0)?;
    let h = check_any(it, &args, 1)?;
    let rest = if args.len() > 2 { args[2..].to_vec() } else { vec![] };
    let depth = it.frames.len();
    match it.call_value(f, rest, CallName::Unknown, None) {
        Ok(mut r) => { r.insert(0, Value::Bool(true)); Ok(r) }
        Err(e) => {
            it.frames.truncate(depth);
            let mut r = it.call_value(h, vec![e.value], CallName::Unknown, None)?;
            r.insert(0, Value::Bool(false));
            Ok(r)
        }
    }
}

fn lua_collectgarbage(_it: &mut Interp, _args: Vec<Value>) -> LResult<Vec<Value>> {
    Ok(vec![Value::Int(0)])
}

fn lua_require(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let name = check_str(it, &args, 0)?;
    let n = String::from_utf8_lossy(&name).into_owned();
    // check already-loaded globals
    let v = it.globals.borrow().get_str(&n);
    if !v.is_nil() { return Ok(vec![v]); }
    Err(it.lib_error(&format!("module '{}' not found:\n\tno field package.preload['{}']\n\tno file './{}.lua'", n, n, n)))
}

fn lua_load(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let chunk = match args.get(0) {
        Some(Value::Str(s)) => (**s).clone(),
        other => return Err(it.type_error(1, "string", other)),
    };
    let name = match opt_str(it, &args, 1)? {
        Some(n) => String::from_utf8_lossy(&n).into_owned(),
        None => format!("[string \"{}\"]", String::from_utf8_lossy(&chunk).lines().next().unwrap_or("")),
    };
    match super::parser::parse(&chunk) {
        Ok(def) => Ok(vec![Value::Func(Rc::new(Function::Lua(LuaClosure { def, env: Scope::new(None, 0) })))]),
        Err(e) => Ok(vec![Value::Nil, Value::str(&e.format(&name))]),
    }
}

fn lua_unsupported(it: &mut Interp, _args: Vec<Value>) -> LResult<Vec<Value>> {
    Err(it.lib_error("not supported"))
}

// ----------------------------------------------------------------------
// string library

fn str_arith_stub(it: &mut Interp, _args: Vec<Value>) -> LResult<Vec<Value>> {
    // handled directly in Interp::arith; reaching here means a direct call
    Err(it.lib_error("attempt to perform arithmetic on a string value"))
}

fn posrelat_start(pos: i64, len: usize) -> usize {
    if pos > 0 { pos as usize }
    else if pos == 0 { 1 }
    else if pos < -(len as i64) { 1 }
    else { (len as i64 + pos + 1) as usize }
}

fn getendpos(pos: i64, len: usize) -> usize {
    if pos > len as i64 { len }
    else if pos >= 0 { pos as usize }
    else if pos < -(len as i64) { 0 }
    else { (len as i64 + pos + 1) as usize }
}

fn str_len(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    Ok(vec![Value::Int(s.len() as i64)])
}

fn str_sub(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let i = check_int(it, &args, 1)?;
    let j = opt_int(it, &args, 2, -1)?;
    let l = s.len();
    let start = posrelat_start(i, l);
    let end = getendpos(j, l);
    if start <= end { Ok(vec![Value::bytes(s[start - 1..end].to_vec())]) } else { Ok(vec![Value::str("")]) }
}

fn str_upper(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    Ok(vec![Value::bytes(s.to_ascii_uppercase())])
}

fn str_lower(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    Ok(vec![Value::bytes(s.to_ascii_lowercase())])
}

fn str_reverse(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut s = check_str(it, &args, 0)?;
    s.reverse();
    Ok(vec![Value::bytes(s)])
}

const MAXSIZE: usize = 0x7fff_ffff;

fn str_rep(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let n = check_int(it, &args, 1)?;
    let sep = opt_str(it, &args, 2)?.unwrap_or_default();
    if n <= 0 { return Ok(vec![Value::str("")]); }
    let total = (s.len() + sep.len()) as u128 * n as u128;
    if total > MAXSIZE as u128 { return Err(it.lib_error("resulting string too large")); }
    let mut out = Vec::with_capacity(total as usize);
    for i in 0..n {
        if i > 0 { out.extend_from_slice(&sep); }
        out.extend_from_slice(&s);
    }
    Ok(vec![Value::bytes(out)])
}

fn str_byte(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let i = opt_int(it, &args, 1, 1)?;
    let l = s.len();
    let pi = posrelat_start(i, l);
    let j = opt_int(it, &args, 2, pi as i64)?;
    let pe = getendpos(j, l);
    if pi > pe { return Ok(vec![]); }
    if pe - pi >= i32::MAX as usize { return Err(it.lib_error("string slice too long")); }
    Ok(s[pi - 1..pe].iter().map(|b| Value::Int(*b as i64)).collect())
}

fn str_char(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut out = Vec::new();
    for i in 0..args.len() {
        let c = check_int(it, &args, i)?;
        if !(0..=255).contains(&c) { return Err(it.arg_error(i + 1, "value out of range")); }
        out.push(c as u8);
    }
    Ok(vec![Value::bytes(out)])
}

fn push_captures(ms: &MatchState, s: usize, e: usize, whole: bool) -> LResult<Vec<Value>> {
    let n = if ms.level == 0 && whole { 1 } else { ms.level };
    let mut out = Vec::with_capacity(n);
    for i in 0..n {
        out.push(capture_value(ms, i, s, e).map_err(|m| LuaError::new_plain(Value::str(&m)))?);
    }
    Ok(out)
}

fn capture_value(ms: &MatchState, i: usize, s: usize, e: usize) -> Result<Value, String> {
    match ms.get_capture(i, s, e)? {
        Capture::Str(init, len) => Ok(Value::bytes(ms.src[init..init + len].to_vec())),
        Capture::Pos(p) => Ok(Value::Int(p as i64)),
    }
}

fn str_find_aux(it: &mut Interp, args: Vec<Value>, find: bool) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let p = check_str(it, &args, 1)?;
    let init = posrelat_start(opt_int(it, &args, 2, 1)?, s.len());
    if init > s.len() + 1 { return Ok(nil()); }
    let init = init - 1;
    if find && (args.get(3).map_or(false, |v| v.truthy()) || no_specials(&p)) {
        return Ok(match lmemfind(&s[init..], &p) {
            Some(off) => vec![Value::Int((init + off + 1) as i64), Value::Int((init + off + p.len()) as i64)],
            None => nil(),
        });
    }
    let anchor = p.first() == Some(&b'^');
    let pstart = if anchor { 1 } else { 0 };
    let mut ms = MatchState::new(&s, &p);
    let mut s1 = init;
    loop {
        ms.reprep();
        match ms.do_match(s1, pstart) {
            Err(m) => return Err(it.lib_error(&m)),
            Ok(Some(e)) => {
                if find {
                    let mut out = vec![Value::Int((s1 + 1) as i64), Value::Int(e as i64)];
                    out.extend(push_captures(&ms, s1, e, false).map_err(|e| lift_err(it, e))?);
                    return Ok(out);
                } else {
                    return push_captures(&ms, s1, e, true).map_err(|e| lift_err(it, e));
                }
            }
            Ok(None) => {}
        }
        s1 += 1;
        if anchor || s1 > s.len() { break; }
    }
    Ok(nil())
}

fn lift_err(it: &Interp, e: LuaError) -> LuaError {
    match e.value {
        Value::Str(s) if e.traceback.is_none() => it.lib_error(&String::from_utf8_lossy(&s)),
        _ => e,
    }
}

fn str_find(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { str_find_aux(it, args, true) }
fn str_match(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { str_find_aux(it, args, false) }

fn str_gmatch(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let p = check_str(it, &args, 1)?;
    let init = posrelat_start(opt_int(it, &args, 2, 1)?, s.len());
    let start = if init > s.len() + 1 { s.len() + 1 } else { init - 1 };
    // state table: {s, p, pos, lastmatch}
    let st = Rc::new(RefCell::new(Table::new()));
    st.borrow_mut().set_int(1, Value::bytes(s));
    st.borrow_mut().set_int(2, Value::bytes(p));
    st.borrow_mut().set_int(3, Value::Int(start as i64));
    st.borrow_mut().set_int(4, Value::Int(-1));
    Ok(vec![native("gmatch_aux", gmatch_aux), Value::Table(st), Value::Nil])
}

fn gmatch_aux(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let st = check_table(it, &args, 0)?;
    let (s, p, mut pos, last) = {
        let t = st.borrow();
        let s = match t.get_int(1) { Value::Str(s) => s, _ => return Ok(nil()) };
        let p = match t.get_int(2) { Value::Str(s) => s, _ => return Ok(nil()) };
        let pos = match t.get_int(3) { Value::Int(i) => i as usize, _ => 0 };
        let last = match t.get_int(4) { Value::Int(i) => i, _ => -1 };
        (s, p, pos, last)
    };
    let mut ms = MatchState::new(&s, &p);
    while pos <= s.len() {
        ms.reprep();
        match ms.do_match(pos, 0) {
            Err(m) => return Err(it.lib_error(&m)),
            Ok(Some(e)) if e as i64 != last => {
                st.borrow_mut().set_int(3, Value::Int(e as i64));
                st.borrow_mut().set_int(4, Value::Int(e as i64));
                return push_captures(&ms, pos, e, true).map_err(|e| lift_err(it, e));
            }
            _ => {}
        }
        pos += 1;
    }
    Ok(nil())
}

fn str_gsub(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let src = check_str(it, &args, 0)?;
    let p = check_str(it, &args, 1)?;
    let repl = args.get(2).cloned().unwrap_or(Value::Nil);
    match &repl {
        Value::Int(_) | Value::Flt(_) | Value::Str(_) | Value::Table(_) | Value::Func(_) => {}
        other => return Err(it.type_error(3, "string/function/table", Some(other))),
    }
    let max_n = opt_int(it, &args, 3, src.len() as i64 + 1)?;
    let anchor = p.first() == Some(&b'^');
    let pstart = if anchor { 1 } else { 0 };
    let mut ms = MatchState::new(&src, &p);
    let mut out: Vec<u8> = Vec::new();
    let mut s1 = 0usize;
    let mut n: i64 = 0;
    let repl_str = match &repl {
        Value::Int(_) | Value::Flt(_) | Value::Str(_) => Some(check_str(it, &args, 2)?),
        _ => None,
    };
    while n < max_n {
        ms.reprep();
        let r = ms.do_match(s1, pstart).map_err(|m| it.lib_error(&m))?;
        if let Some(e) = r {
            n += 1;
            // add_value
            let whole = Value::bytes(src[s1..e].to_vec());
            let replacement: Value = match &repl {
                Value::Str(_) | Value::Int(_) | Value::Flt(_) => {
                    let rs = repl_str.as_ref().unwrap();
                    let mut buf = Vec::new();
                    let mut i = 0;
                    while i < rs.len() {
                        let c = rs[i];
                        if c == b'%' {
                            i += 1;
                            if i >= rs.len() { return Err(it.lib_error("invalid use of '%' in replacement string")); }
                            let d = rs[i];
                            if d == b'%' { buf.push(b'%'); }
                            else if d.is_ascii_digit() {
                                if d == b'0' { buf.extend_from_slice(&src[s1..e]); }
                                else {
                                    let idx = (d - b'1') as usize;
                                    let cv = capture_value(&ms, idx, s1, e).map_err(|m| it.lib_error(&m))?;
                                    match cv {
                                        Value::Str(cs) => buf.extend_from_slice(&cs),
                                        Value::Int(n) => buf.extend_from_slice(n.to_string().as_bytes()),
                                        _ => {}
                                    }
                                }
                            } else {
                                return Err(it.lib_error("invalid use of '%' in replacement string"));
                            }
                            i += 1;
                        } else { buf.push(c); i += 1; }
                    }
                    Value::bytes(buf)
                }
                Value::Table(t) => {
                    let k = capture_value(&ms, 0, s1, e).map_err(|m| it.lib_error(&m))?;
                    let v = it.index_with_info(Value::Table(t.clone()), k, "")?;
                    v
                }
                Value::Func(_) => {
                    let caps = push_captures(&ms, s1, e, true).map_err(|e| lift_err(it, e))?;
                    let r = it.call_value(repl.clone(), caps, CallName::Unknown, None)?;
                    r.into_iter().next().unwrap_or(Value::Nil)
                }
                _ => unreachable!(),
            };
            match replacement {
                Value::Nil | Value::Bool(false) => out.extend_from_slice(&src[s1..e]),
                Value::Str(s) => out.extend_from_slice(&s),
                Value::Int(i) => out.extend_from_slice(i.to_string().as_bytes()),
                Value::Flt(f) => out.extend_from_slice(lua_float_to_string(f).as_bytes()),
                other => return Err(it.lib_error(&format!("invalid replacement value (a {})", other.type_name()))),
            }
            let _ = whole;
            if e > s1 { s1 = e; }
            else {
                if s1 < src.len() { out.push(src[s1]); }
                s1 += 1;
            }
        } else {
            if s1 < src.len() { out.push(src[s1]); }
            s1 += 1;
        }
        if s1 > src.len() || anchor { break; }
    }
    if s1 < src.len() { out.extend_from_slice(&src[s1..]); }
    Ok(vec![Value::bytes(out), Value::Int(n)])
}

fn str_format(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let fmt = check_str(it, &args, 0)?;
    let mut out: Vec<u8> = Vec::new();
    let mut argi = 1usize;
    let mut i = 0usize;
    while i < fmt.len() {
        let c = fmt[i];
        if c != b'%' { out.push(c); i += 1; continue; }
        i += 1;
        if i >= fmt.len() { return Err(it.lib_error("invalid conversion '%' to 'format'")); }
        if fmt[i] == b'%' { out.push(b'%'); i += 1; continue; }
        // parse spec
        let spec_start = i;
        let mut flags = Vec::new();
        while i < fmt.len() && b"-+ #0".contains(&fmt[i]) { flags.push(fmt[i]); i += 1; }
        let mut width: Option<usize> = None;
        let mut wd = 0;
        while i < fmt.len() && fmt[i].is_ascii_digit() { width = Some(width.unwrap_or(0) * 10 + (fmt[i] - b'0') as usize); i += 1; wd += 1; }
        let mut precision: Option<usize> = None;
        let mut pd = 0;
        if i < fmt.len() && fmt[i] == b'.' {
            i += 1;
            precision = Some(0);
            while i < fmt.len() && fmt[i].is_ascii_digit() { precision = Some(precision.unwrap() * 10 + (fmt[i] - b'0') as usize); i += 1; pd += 1; }
        }
        if i >= fmt.len() {
            let spec = String::from_utf8_lossy(&fmt[spec_start - 1..]).into_owned();
            return Err(it.lib_error(&format!("invalid conversion '{}' to 'format'", spec)));
        }
        let conv = fmt[i];
        i += 1;
        let spec = String::from_utf8_lossy(&fmt[spec_start - 1..i]).into_owned();
        if flags.len() > 5 || wd > 2 || pd > 2 {
            return Err(it.lib_error("invalid format string to 'format'"));
        }
        let left = flags.contains(&b'-');
        let zero = flags.contains(&b'0');
        let plus = flags.contains(&b'+');
        let space = flags.contains(&b' ');
        let alt = flags.contains(&b'#');
        let pad = |s: String, numeric: bool| -> String {
            let w = width.unwrap_or(0);
            if s.len() >= w { return s; }
            let fill = w - s.len();
            if left { format!("{}{}", s, " ".repeat(fill)) }
            else if zero && numeric {
                // insert zeros after sign / 0x prefix
                let (sign, rest) = if s.starts_with('-') || s.starts_with('+') || s.starts_with(' ') { (&s[..1], &s[1..]) } else { ("", &s[..]) };
                format!("{}{}{}", sign, "0".repeat(fill), rest)
            } else { format!("{}{}", " ".repeat(fill), s) }
        };
        match conv {
            b'c' => {
                let n = check_int(it, &args, argi)?; argi += 1;
                let s = pad(String::from_utf8_lossy(&[n as u8]).into_owned(), false);
                out.extend_from_slice(s.as_bytes());
            }
            b'd' | b'i' => {
                let n = check_int(it, &args, argi)?; argi += 1;
                let mut digits = n.unsigned_abs().to_string();
                if let Some(p) = precision { while digits.len() < p { digits.insert(0, '0'); } if p == 0 && n == 0 { digits.clear(); } }
                let sign = if n < 0 { "-" } else if plus { "+" } else if space { " " } else { "" };
                let s = pad(format!("{}{}", sign, digits), precision.is_none());
                out.extend_from_slice(s.as_bytes());
            }
            b'u' => {
                let n = check_int(it, &args, argi)?; argi += 1;
                let s = pad((n as u64).to_string(), precision.is_none());
                out.extend_from_slice(s.as_bytes());
            }
            b'o' | b'x' | b'X' => {
                let n = check_int(it, &args, argi)?; argi += 1;
                let mut digits = match conv { b'o' => format!("{:o}", n as u64), b'x' => format!("{:x}", n as u64), _ => format!("{:X}", n as u64) };
                if let Some(p) = precision { while digits.len() < p { digits.insert(0, '0'); } }
                if alt && n != 0 { digits = match conv { b'o' => format!("0{}", digits), b'x' => format!("0x{}", digits), _ => format!("0X{}", digits) }; }
                let s = pad(digits, precision.is_none());
                out.extend_from_slice(s.as_bytes());
            }
            b'a' | b'A' | b'e' | b'E' | b'f' | b'F' | b'g' | b'G' => {
                let v = check_num(it, &args, argi)?; argi += 1;
                let upper = conv.is_ascii_uppercase();
                let mut body = match conv.to_ascii_lowercase() {
                    b'a' => fmt_a(v.abs(), precision, upper),
                    b'e' => fmt_e(v.abs(), precision.unwrap_or(6), upper),
                    b'f' => fmt_f(v.abs(), precision.unwrap_or(6), upper),
                    _ => fmt_g(v.abs(), precision.unwrap_or(6), upper, alt),
                };
                if alt && conv.to_ascii_lowercase() == b'f' && precision == Some(0) { body.push('.'); }
                let neg = v.is_sign_negative() && !(v.is_nan() && false);
                let sign = if neg { "-" } else if plus { "+" } else if space { " " } else { "" };
                let s = pad(format!("{}{}", sign, body), v.is_finite());
                out.extend_from_slice(s.as_bytes());
            }
            b'p' => {
                let v = check_any(it, &args, argi)?; argi += 1;
                let s = match &v {
                    Value::Table(t) => format!("{:p}", Rc::as_ptr(t)),
                    Value::Func(f) => format!("{:p}", Rc::as_ptr(f)),
                    Value::Str(s) => format!("{:p}", Rc::as_ptr(s)),
                    _ => "(null)".to_string(),
                };
                out.extend_from_slice(pad(s, false).as_bytes());
            }
            b'q' => {
                if spec != "%q" { return Err(it.lib_error("specifier '%q' cannot have modifiers")); }
                let v = check_any(it, &args, argi)?; argi += 1;
                match &v {
                    Value::Str(s) => {
                        out.push(b'"');
                        let bytes = s.as_slice();
                        for (k, &b) in bytes.iter().enumerate() {
                            match b {
                                b'"' => out.extend_from_slice(b"\\\""),
                                b'\\' => out.extend_from_slice(b"\\\\"),
                                b'\n' => out.extend_from_slice(b"\\\n"),
                                b'\r' => out.extend_from_slice(b"\\r"),
                                0 => {
                                    if bytes.get(k + 1).map_or(false, |n| n.is_ascii_digit()) { out.extend_from_slice(b"\\000"); } else { out.extend_from_slice(b"\\0"); }
                                }
                                c if c.is_ascii_control() => {
                                    if bytes.get(k + 1).map_or(false, |n| n.is_ascii_digit()) { out.extend_from_slice(format!("\\{:03}", c).as_bytes()); } else { out.extend_from_slice(format!("\\{}", c).as_bytes()); }
                                }
                                c => out.push(c),
                            }
                        }
                        out.push(b'"');
                    }
                    Value::Int(n) => {
                        if *n == i64::MIN { out.extend_from_slice(b"0x8000000000000000"); } else { out.extend_from_slice(n.to_string().as_bytes()); }
                    }
                    Value::Flt(f) => {
                        let s = if *f == f64::INFINITY { "1e9999".to_string() } else if *f == f64::NEG_INFINITY { "-1e9999".to_string() } else if f.is_nan() { "(0/0)".to_string() } else if *f == f.floor() && f.abs() < 1e15 { format!("{}", fmt_a(*f, None, false)) } else { fmt_a(*f, None, false) };
                        // integral floats: Lua uses "%a" too (LUAI_NUMFFORMAT hex); keep hex form
                        out.extend_from_slice(s.as_bytes());
                    }
                    Value::Nil | Value::Bool(_) => out.extend_from_slice(&tostring_basic(&v)),
                    _ => return Err(it.arg_error(argi, "value has no literal form")),
                }
            }
            b's' => {
                let v = check_any(it, &args, argi)?; argi += 1;
                let s = it.tostring(&v)?;
                let mut st = String::from_utf8_lossy(&s).into_owned();
                if let Some(p) = precision { st = st.chars().take(p).collect(); }
                if precision.is_none() && s.len() >= 100 { out.extend_from_slice(&s); }
                else { out.extend_from_slice(pad(st, false).as_bytes()); }
            }
            _ => {
                return Err(it.lib_error(&format!("invalid conversion '{}' to 'format'", spec)));
            }
        }
    }
    Ok(vec![Value::bytes(out)])
}

