// table library

fn tab_concat(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let sep = opt_str(it, &args, 1)?.unwrap_or_default();
    let i = opt_int(it, &args, 2, 1)?;
    let last = match args.get(3) { None | Some(Value::Nil) => t.borrow().len(), _ => check_int(it, &args, 3)? };
    let mut out = Vec::new();
    let mut k = i;
    while k <= last {
        let v = t.borrow().get_int(k);
        match v {
            Value::Str(s) => out.extend_from_slice(&s),
            Value::Int(n) => out.extend_from_slice(n.to_string().as_bytes()),
            Value::Flt(f) => out.extend_from_slice(lua_float_to_string(f).as_bytes()),
            other => return Err(it.lib_error(&format!("invalid value (at index {}) in table for 'concat'", k)).with_msg_fix(other.type_name(), k)),
        }
        if k < last { out.extend_from_slice(&sep); }
        if k == i64::MAX { break; }
        k += 1;
    }
    Ok(vec![Value::bytes(out)])
}

trait MsgFix { fn with_msg_fix(self, tname: &str, k: i64) -> Self; }
impl MsgFix for LuaError {
    fn with_msg_fix(mut self, tname: &str, k: i64) -> Self {
        if let Value::Str(s) = &self.value {
            let st = String::from_utf8_lossy(s).into_owned();
            let fixed = st.replace(&format!("invalid value (at index {}) in table for 'concat'", k), &format!("invalid value (a {}) at index {} in table for 'concat'", tname, k));
            self.value = Value::str(&fixed);
        }
        self
    }
}

fn tab_insert(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let e = t.borrow().len() + 1;
    match args.len() {
        2 => { t.borrow_mut().set_int(e, args[1].clone()); }
        3 => {
            let pos = check_int(it, &args, 1)?;
            if (pos as u64).wrapping_sub(1) >= e as u64 {
                return Err(it.arg_error(2, "position out of bounds"));
            }
            let mut tb = t.borrow_mut();
            let mut i = e;
            while i > pos {
                let v = tb.get_int(i - 1);
                tb.set_int(i, v);
                i -= 1;
            }
            tb.set_int(pos, args[2].clone());
        }
        _ => return Err(it.lib_error("wrong number of arguments to 'insert'")),
    }
    Ok(vec![])
}

fn tab_remove(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let size = t.borrow().len();
    let pos = opt_int(it, &args, 1, size)?;
    if args.len() > 1 && size + 1 != pos && (pos as u64).wrapping_sub(1) >= (size as u64).wrapping_add(1) {
        return Err(it.arg_error(2, "position out of bounds"));
    }
    let mut tb = t.borrow_mut();
    let v = tb.get_int(pos);
    let mut p = pos;
    while p < size {
        let nv = tb.get_int(p + 1);
        tb.set_int(p, nv);
        p += 1;
    }
    if p <= size || args.len() <= 1 { tb.set_int(p, Value::Nil); }
    Ok(vec![v])
}

fn tab_unpack(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let i = opt_int(it, &args, 1, 1)?;
    let e = match args.get(2) { None | Some(Value::Nil) => t.borrow().len(), _ => check_int(it, &args, 2)? };
    if i > e { return Ok(vec![]); }
    let n = (e as i128 - i as i128) as u128 + 1;
    if n >= 1_000_000 { return Err(it.lib_error("too many results to unpack")); }
    let tb = t.borrow();
    Ok((i..=e).map(|k| tb.get_int(k)).collect())
}

fn tab_pack(_it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = Rc::new(RefCell::new(Table::new()));
    let n = args.len() as i64;
    for (i, v) in args.into_iter().enumerate() { t.borrow_mut().set_int(i as i64 + 1, v); }
    t.borrow_mut().set_str("n", Value::Int(n));
    Ok(vec![Value::Table(t)])
}

fn tab_sort(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(it, &args, 0)?;
    let cmp = args.get(1).cloned().unwrap_or(Value::Nil);
    if !cmp.is_nil() && !matches!(cmp, Value::Func(_)) {
        return Err(it.type_error(2, "function", Some(&cmp)));
    }
    let n = t.borrow().len();
    let mut items: Vec<Value> = (1..=n).map(|k| t.borrow().get_int(k)).collect();
    // simple insertion/merge sort with fallible comparator
    let mut err: Option<LuaError> = None;
    let mut less = |it: &mut Interp, a: &Value, b: &Value| -> bool {
        if err.is_some() { return false; }
        let r = if cmp.is_nil() { it.less_than(a, b) } else {
            it.call_value(cmp.clone(), vec![a.clone(), b.clone()], CallName::Unknown, None).map(|r| r.get(0).map_or(false, |v| v.truthy()))
        };
        match r { Ok(b) => b, Err(e) => { err = Some(e); false } }
    };
    // merge sort
    fn msort(it: &mut Interp, v: &mut Vec<Value>, less: &mut dyn FnMut(&mut Interp, &Value, &Value) -> bool) {
        if v.len() <= 1 { return; }
        let mid = v.len() / 2;
        let mut right = v.split_off(mid);
        msort(it, v, less);
        msort(it, &mut right, less);
        let left = std::mem::take(v);
        let mut out = Vec::with_capacity(left.len() + right.len());
        let (mut i, mut j) = (0, 0);
        while i < left.len() && j < right.len() {
            if less(it, &right[j], &left[i]) { out.push(right[j].clone()); j += 1; } else { out.push(left[i].clone()); i += 1; }
        }
        out.extend_from_slice(&left[i..]);
        out.extend_from_slice(&right[j..]);
        *v = out;
    }
    msort(it, &mut items, &mut less);
    if let Some(e) = err { return Err(e); }
    for (k, v) in items.into_iter().enumerate() { t.borrow_mut().set_int(k as i64 + 1, v); }
    Ok(vec![])
}

// ----------------------------------------------------------------------
// math

fn math_abs(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    Ok(vec![match check_number(it, &args, 0)? { Num::I(i) => Value::Int(i.wrapping_abs()), Num::F(f) => Value::Flt(f.abs()) }])
}

fn push_numint(f: f64) -> Value {
    match flt_to_int_exact(f) { Some(i) => Value::Int(i), None => Value::Flt(f) }
}

fn math_ceil(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    Ok(vec![match check_number(it, &args, 0)? { Num::I(i) => Value::Int(i), Num::F(f) => push_numint(f.ceil()) }])
}

fn math_floor(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    Ok(vec![match check_number(it, &args, 0)? { Num::I(i) => Value::Int(i), Num::F(f) => push_numint(f.floor()) }])
}

fn math_max(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut best = check_number(it, &args, 0)?;
    let mut bv = num_val(best);
    for i in 1..args.len() {
        let v = check_number(it, &args, i)?;
        let vv = num_val(v);
        if it.less_than(&bv, &vv)? { best = v; bv = vv; }
    }
    let _ = best;
    Ok(vec![bv])
}

fn math_min(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let best = check_number(it, &args, 0)?;
    let mut bv = num_val(best);
    for i in 1..args.len() {
        let v = check_number(it, &args, i)?;
        let vv = num_val(v);
        if it.less_than(&vv, &bv)? { bv = vv; }
    }
    Ok(vec![bv])
}

fn num_val(n: Num) -> Value { match n { Num::I(i) => Value::Int(i), Num::F(f) => Value::Flt(f) } }

fn math_sqrt(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.sqrt())]) }
fn math_exp(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.exp())]) }
fn math_sin(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.sin())]) }
fn math_cos(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.cos())]) }
fn math_tan(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.tan())]) }
fn math_asin(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.asin())]) }
fn math_acos(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> { Ok(vec![Value::Flt(check_num(it, &args, 0)?.acos())]) }
fn math_atan(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let y = check_num(it, &args, 0)?;
    let x = match args.get(1) { None | Some(Value::Nil) => 1.0, _ => check_num(it, &args, 1)? };
    Ok(vec![Value::Flt(y.atan2(x))])
}

fn math_log(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let x = check_num(it, &args, 0)?;
    let r = match args.get(1) {
        None | Some(Value::Nil) => x.ln(),
        _ => {
            let b = check_num(it, &args, 1)?;
            if b == 2.0 { x.log2() } else if b == 10.0 { x.log10() } else { x.ln() / b.ln() }
        }
    };
    Ok(vec![Value::Flt(r)])
}

fn math_tointeger(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    Ok(vec![match &v {
        Value::Int(i) => Value::Int(*i),
        Value::Flt(f) => flt_to_int_exact(*f).map(Value::Int).unwrap_or(Value::Nil),
        Value::Str(s) => match str_to_number(s) {
            Some(Number::Int(i)) => Value::Int(i),
            Some(Number::Flt(f)) => flt_to_int_exact(f).map(Value::Int).unwrap_or(Value::Nil),
            None => Value::Nil,
        },
        _ => Value::Nil,
    }])
}

fn math_type(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let v = check_any(it, &args, 0)?;
    Ok(vec![match v { Value::Int(_) => Value::str("integer"), Value::Flt(_) => Value::str("float"), _ => Value::Nil }])
}

fn math_fmod(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let a = check_number(it, &args, 0)?;
    let b = check_number(it, &args, 1)?;
    match (a, b) {
        (Num::I(x), Num::I(y)) => {
            if y == 0 { return Err(it.arg_error(2, "zero")); }
            if y == -1 { return Ok(vec![Value::Int(0)]); }
            Ok(vec![Value::Int(x % y)])
        }
        _ => Ok(vec![Value::Flt(a.f() % b.f())]),
    }
}

fn math_modf(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let x = check_num(it, &args, 0)?;
    let ip = if x.is_infinite() { x } else { x.trunc() };
    let fp = if x.is_infinite() { 0.0 } else { x - ip };
    Ok(vec![push_numint_float(ip), Value::Flt(fp)])
}

fn push_numint_float(f: f64) -> Value {
    // math.modf returns a float unless it fits an integer ("pushnumint" in lmathlib uses lua_Number->integer when fits)
    match flt_to_int_exact(f) { Some(i) => Value::Flt(i as f64), None => Value::Flt(f) }
}

thread_local! { static RNG: std::cell::Cell<u64> = std::cell::Cell::new(0x9E3779B97F4A7C15); }

fn next_rand() -> u64 {
    RNG.with(|r| {
        let mut x = r.get();
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        r.set(x);
        x
    })
}

fn math_random(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let rv = next_rand();
    match args.len() {
        0 => Ok(vec![Value::Flt((rv >> 11) as f64 / (1u64 << 53) as f64)]),
        _ => {
            let (low, up) = if args.len() == 1 { (1, check_int(it, &args, 0)?) } else { (check_int(it, &args, 0)?, check_int(it, &args, 1)?) };
            if low > up { return Err(it.arg_error(args.len(), "interval is empty")); }
            let range = (up as i128 - low as i128) as u128 + 1;
            Ok(vec![Value::Int((low as i128 + (rv as u128 % range) as i128) as i64)])
        }
    }
}

fn math_randomseed(_it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let seed = match args.get(0) { Some(Value::Int(i)) => *i as u64, Some(Value::Flt(f)) => f.to_bits(), _ => 42 };
    RNG.with(|r| r.set(seed | 1));
    Ok(vec![])
}

fn math_ult(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let a = check_int(it, &args, 0)?;
    let b = check_int(it, &args, 1)?;
    Ok(vec![Value::Bool((a as u64) < (b as u64))])
}

// ----------------------------------------------------------------------
// os / io / utf8

fn os_time(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    match args.get(0) {
        None | Some(Value::Nil) => {
            let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
            Ok(vec![Value::Int(now)])
        }
        Some(Value::Table(t)) => {
            let get = |k: &str, d: Option<i64>| -> LResult<i64> {
                match t.borrow().get_str(k) {
                    Value::Int(i) => Ok(i),
                    Value::Flt(f) => flt_to_int_exact(f).ok_or_else(|| it.lib_error(&format!("field '{}' is not an integer", k))),
                    Value::Str(s) => match str_to_number(&s) { Some(Number::Int(i)) => Ok(i), _ => Err(it.lib_error(&format!("field '{}' is not an integer", k))) },
                    Value::Nil => d.ok_or_else(|| it.lib_error(&format!("field '{}' missing in date table", k))),
                    _ => Err(it.lib_error(&format!("field '{}' is not an integer", k))),
                }
            };
            let year = get("year", None)?;
            let month = get("month", None)?;
            let day = get("day", None)?;
            let hour = get("hour", Some(12))?;
            let min = get("min", Some(0))?;
            let sec = get("sec", Some(0))?;
            use chrono::TimeZone;
            let base = chrono::Local.with_ymd_and_hms(year as i32, 1, 1, 0, 0, 0).single();
            match base {
                Some(b) => {
                    let dt = b + chrono::Months::new((month - 1).max(0) as u32) + chrono::Duration::days(day - 1) + chrono::Duration::hours(hour) + chrono::Duration::minutes(min) + chrono::Duration::seconds(sec);
                    Ok(vec![Value::Int(dt.timestamp())])
                }
                None => Err(it.lib_error("time result cannot be represented in this installation")),
            }
        }
        other => Err(it.type_error(1, "table", other)),
    }
}

fn os_clock(_it: &mut Interp, _args: Vec<Value>) -> LResult<Vec<Value>> {
    thread_local! { static START: std::time::Instant = std::time::Instant::now(); }
    let e = START.with(|s| s.elapsed().as_secs_f64());
    Ok(vec![Value::Flt(e)])
}

fn os_difftime(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let a = check_int(it, &args, 0)?;
    let b = opt_int(it, &args, 1, 0)?;
    Ok(vec![Value::Flt((a - b) as f64)])
}

fn os_getenv(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let n = check_str(it, &args, 0)?;
    match std::env::var(String::from_utf8_lossy(&n).as_ref()) {
        Ok(v) => Ok(vec![Value::str(&v)]),
        Err(_) => Ok(nil()),
    }
}

fn os_date(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    use chrono::{Datelike, Timelike};
    let fmt = opt_str(it, &args, 0)?.unwrap_or_else(|| b"%c".to_vec());
    let t = match args.get(1) { None | Some(Value::Nil) => std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0), _ => check_int(it, &args, 1)? };
    let mut f = fmt.as_slice();
    let utc = f.first() == Some(&b'!');
    if utc { f = &f[1..]; }
    let dt_utc = chrono::DateTime::from_timestamp(t, 0).ok_or_else(|| it.lib_error("date result cannot be represented in this installation"))?;
    let (y, mo, d, h, mi, s, wd, yd, is_utc): (i32, u32, u32, u32, u32, u32, u32, u32, bool) = if utc {
        (dt_utc.year(), dt_utc.month(), dt_utc.day(), dt_utc.hour(), dt_utc.minute(), dt_utc.second(), dt_utc.weekday().num_days_from_sunday(), dt_utc.ordinal(), true)
    } else {
        let l = dt_utc.with_timezone(&chrono::Local);
        (l.year(), l.month(), l.day(), l.hour(), l.minute(), l.second(), l.weekday().num_days_from_sunday(), l.ordinal(), false)
    };
    if f.starts_with(b"*t") {
        let tb = Rc::new(RefCell::new(Table::new()));
        tb.borrow_mut().set_str("year", Value::Int(y as i64));
        tb.borrow_mut().set_str("month", Value::Int(mo as i64));
        tb.borrow_mut().set_str("day", Value::Int(d as i64));
        tb.borrow_mut().set_str("hour", Value::Int(h as i64));
        tb.borrow_mut().set_str("min", Value::Int(mi as i64));
        tb.borrow_mut().set_str("sec", Value::Int(s as i64));
        tb.borrow_mut().set_str("wday", Value::Int(wd as i64 + 1));
        tb.borrow_mut().set_str("yday", Value::Int(yd as i64));
        tb.borrow_mut().set_str("isdst", Value::Bool(false));
        return Ok(vec![Value::Table(tb)]);
    }
    let _ = is_utc;
    let dt = if utc { dt_utc.format(&String::from_utf8_lossy(f)).to_string() } else { dt_utc.with_timezone(&chrono::Local).format(&String::from_utf8_lossy(f)).to_string() };
    Ok(vec![Value::str(&dt)])
}

fn io_write(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut out = Vec::new();
    for i in 0..args.len() {
        match &args[i] {
            Value::Str(s) => out.extend_from_slice(s),
            Value::Int(n) => out.extend_from_slice(n.to_string().as_bytes()),
            Value::Flt(f) => out.extend_from_slice(fmt_g(*f, 14, false, false).as_bytes()),
            other => return Err(it.type_error(i + 1, "string", Some(other))),
        }
    }
    it.write_out(&out);
    Ok(vec![])
}

fn utf8_char(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let mut out = Vec::new();
    for i in 0..args.len() {
        let c = check_int(it, &args, i)?;
        if !(0..=0x7FFF_FFFF).contains(&c) { return Err(it.arg_error(i + 1, "value out of range")); }
        super::lexer::utf8_encode(c as u32, &mut out);
    }
    Ok(vec![Value::bytes(out)])
}

fn utf8_len(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let i = posrelat_start(opt_int(it, &args, 1, 1)?, s.len());
    let mut p = i - 1;
    let mut n = 0i64;
    while p < s.len() {
        match utf8_decode(&s[p..]) {
            Some((_, len)) => { p += len; n += 1; }
            None => return Ok(vec![Value::Nil, Value::Int(p as i64 + 1)]),
        }
    }
    Ok(vec![Value::Int(n)])
}

fn utf8_codepoint(it: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_str(it, &args, 0)?;
    let i = posrelat_start(opt_int(it, &args, 1, 1)?, s.len());
    let j = getendpos(opt_int(it, &args, 2, i as i64)?, s.len());
    let mut out = Vec::new();
    let mut p = i - 1;
    while p < j {
        match utf8_decode(&s[p..]) {
            Some((c, len)) => { out.push(Value::Int(c as i64)); p += len; }
            None => return Err(it.lib_error("invalid UTF-8 code")),
        }
    }
    Ok(out)
}

fn utf8_decode(s: &[u8]) -> Option<(u32, usize)> {
    let c = *s.first()?;
    if c < 0x80 { return Some((c as u32, 1)); }
    let (len, init) = if c >= 0xF0 { (4, (c & 0x07) as u32) } else if c >= 0xE0 { (3, (c & 0x0F) as u32) } else if c >= 0xC0 { (2, (c & 0x1F) as u32) } else { return None; };
    if s.len() < len { return None; }
    let mut v = init;
    for k in 1..len {
        if s[k] & 0xC0 != 0x80 { return None; }
        v = (v << 6) | (s[k] & 0x3F) as u32;
    }
    Some((v, len))
}

impl Interp {
    pub fn write_out(&mut self, bytes: &[u8]) {
        use std::io::Write;
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(bytes);
        let _ = lock.flush();
    }
}
