use crate::lua::interp::{Interp, LuaError};
use crate::lua::parser;
use crate::lua::value::Value as LValue;
use serde_json::{Map, Value};

const INIT_CHUNK: &str = "src/filter.rs:20";
const IMPLICIT_CHUNK: &str = "src/filter.rs:23";
const EXPLICIT_CHUNK: &str = "src/filter.rs:25";

pub struct Filter {
    pub expression: String,
    pub implicit_return: bool,
    pub print_lua: bool,
}

/// Sanitize a JSON key into a Lua identifier-like name.
pub fn sanitize_key(key: &str) -> String {
    key.chars().map(|c| if c.is_ascii_alphabetic() || c == '_' { c } else { '_' }).collect()
}

fn lua_string_literal(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\'' => out.push_str("\\'"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn lua_scalar(v: &Value) -> Option<String> {
    match v {
        Value::Bool(b) => Some(b.to_string()),
        Value::Number(n) => Some(n.to_string()),
        Value::String(s) => Some(lua_string_literal(s)),
        _ => None,
    }
}

fn lua_value(v: &Value) -> String {
    match v {
        Value::Null => "\"unsupported\"".to_string(),
        Value::Bool(_) | Value::Number(_) | Value::String(_) => lua_scalar(v).unwrap(),
        Value::Object(map) => {
            let fields: Vec<String> = map.iter().map(|(k, v)| format!("{} = {}", sanitize_key(k), lua_value(v))).collect();
            format!("{{{}}}", fields.join(","))
        }
        Value::Array(items) => {
            let elems: Vec<String> = items.iter().map(|e| lua_scalar(e).unwrap_or_else(|| "\"unsupported\"".to_string())).collect();
            format!("{{{}}}", elems.join(","))
        }
    }
}

pub fn build_init(log: &Map<String, Value>) -> String {
    log.iter().map(|(k, v)| format!("{} = {}", sanitize_key(k), lua_value(v))).collect::<Vec<_>>().join("\n")
}

fn format_syntax(e: parser::SyntaxError, chunk: &str) -> String {
    let msg = e.format(chunk);
    let incomplete = msg.ends_with("<eof>");
    format!("SyntaxError {{ message: {:?}, incomplete_input: {} }}", msg, incomplete)
}

fn format_runtime(it: &mut Interp, e: LuaError) -> String {
    let base = match &e.value {
        LValue::Str(s) => String::from_utf8_lossy(s).into_owned(),
        other => match it.tostring(other) {
            Ok(b) => String::from_utf8_lossy(&b).into_owned(),
            Err(_) => String::from_utf8_lossy(&crate::lua::interp::tostring_basic(other)).into_owned(),
        },
    };
    let full = match e.traceback {
        Some(tb) => format!("{}\n{}", base, tb),
        None => base,
    };
    format!("RuntimeError({:?})", full)
}

impl Filter {
    /// Returns Ok(true) when the entry should be shown.
    pub fn apply(&self, log: &Map<String, Value>) -> Result<bool, String> {
        let init = build_init(log);
        if self.print_lua {
            println!("{}", init);
        }
        let mut it = Interp::new(INIT_CHUNK);
        let init_def = parser::parse(init.as_bytes()).map_err(|e| format_syntax(e, INIT_CHUNK))?;
        if let Err(e) = it.run_main(init_def) {
            return Err(format_runtime(&mut it, e));
        }
        let chunk = if self.implicit_return { IMPLICIT_CHUNK } else { EXPLICIT_CHUNK };
        it.set_chunk_name(chunk);
        let code = if self.implicit_return { format!("return {};", self.expression) } else { self.expression.clone() };
        // mlua's eval(): first try as an expression, then as a chunk
        let def = match parser::parse(format!("return {}", code).as_bytes()) {
            Ok(d) => d,
            Err(_) => parser::parse(code.as_bytes()).map_err(|e| format_syntax(e, chunk))?,
        };
        match it.run_main(def) {
            Ok(vals) => Ok(vals.first().map_or(false, |v| v.truthy())),
            Err(e) => Err(format_runtime(&mut it, e)),
        }
    }
}
