use serde_json::Value;
use std::collections::BTreeMap;
use yansi::Paint;

// ----------------------------------------------------------------------
// AST

#[derive(Debug, Clone)]
pub enum Seg {
    Up,            // ../
    This,          // this, ., ./
    Key(String),   // identifier or [literal]
    Root,          // @root
    Local(String), // @index, @key, ...
}

#[derive(Debug, Clone)]
pub struct Path {
    pub segs: Vec<Seg>,
    pub raw: String,
}

#[derive(Debug, Clone)]
pub enum Param {
    Path(Path),
    Literal(Value),
    Sub(Box<HelperExpr>),
}

#[derive(Debug, Clone)]
pub struct HelperExpr {
    pub name: Path,
    pub params: Vec<Param>,
    pub hash: Vec<(String, Param)>,
}

#[derive(Debug, Clone)]
pub struct Pos {
    pub line: usize,
    pub col: usize,
}

#[derive(Debug, Clone)]
pub enum Element {
    Text(String),
    Expr { expr: HelperExpr, pos: Pos },
    Block {
        expr: HelperExpr,
        block_params: Vec<String>,
        body: Vec<Element>,
        inverse: Option<Vec<Element>>,
        pos: Pos,
    },
}

pub struct Template {
    pub name: String,
    pub elements: Vec<Element>,
}

// ----------------------------------------------------------------------
// Template errors (compile time)

#[derive(Debug)]
pub enum TemplateErrorReason {
    InvalidSyntax(String),
    MismatchingClosedHelper(String, String),
    InvalidParam(String),
}

pub struct TemplateError {
    pub reason: TemplateErrorReason,
    pub template_name: Option<String>,
    pub line_no: Option<usize>,
    pub column_no: Option<usize>,
    pub segment: Option<String>,
}

impl std::fmt::Debug for TemplateError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "TemplateError {{ reason: {:?}, template_name: {:?}, line_no: {:?}, column_no: {:?}, segment: {:?} }}",
            self.reason, self.template_name, self.line_no, self.column_no, self.segment)
    }
}

fn make_segment(src: &str, line_no: usize, column_no: usize) -> String {
    // line_no is 1-based; show up to two previous lines, then the error line and a marker
    let lines: Vec<&str> = src.split('\n').collect();
    let idx = line_no - 1;
    let start = idx.saturating_sub(2);
    let mut out = String::new();
    for i in start..=idx.min(lines.len().saturating_sub(1)) {
        out.push_str(&format!("{:>4} | {}\n", i, lines[i]));
    }
    let line_len = lines.get(idx).map_or(0, |l| l.chars().count());
    let mut marker = String::from("     |");
    for i in 0..line_len {
        if i == column_no { marker.push('^'); } else { marker.push('-'); }
    }
    out.push_str(&marker);
    out.push('\n');
    out
}

// ----------------------------------------------------------------------
// Parser

struct Parser<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
    name: String,
}

#[derive(Debug)]
enum Tag {
    Expr { expr: HelperExpr, raw: bool, strip_l: bool, strip_r: bool },
    Open { expr: HelperExpr, block_params: Vec<String>, strip_l: bool, strip_r: bool },
    Close { name: String, strip_l: bool, strip_r: bool },
    Else { chain: Option<HelperExpr>, strip_l: bool, strip_r: bool },
    Comment { strip_l: bool, strip_r: bool },
}

enum Token {
    Text(String),
    Tag(Tag, usize /* start offset */),
}

impl<'a> Parser<'a> {
    fn line_col(&self, offset: usize) -> (usize, usize) {
        let before = &self.src[..offset.min(self.src.len())];
        let line = before.matches('\n').count() + 1;
        let col = before.rsplit('\n').next().map_or(0, |l| l.chars().count()) + 1;
        (line, col)
    }

    fn error(&self, offset: usize, reason: TemplateErrorReason) -> TemplateError {
        let (line, col) = self.line_col(offset);
        TemplateError {
            reason,
            template_name: Some(self.name.clone()),
            line_no: Some(line),
            column_no: Some(col),
            segment: Some(make_segment(self.src, line, col)),
        }
    }

    fn syntax(&self, offset: usize, msg: &str) -> TemplateError {
        self.error(offset, TemplateErrorReason::InvalidSyntax(msg.to_string()))
    }

    fn peek(&self) -> Option<u8> { self.bytes.get(self.pos).copied() }

    fn starts_with(&self, s: &str) -> bool { self.bytes[self.pos..].starts_with(s.as_bytes()) }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_ascii_whitespace() { self.pos += 1; } else { break; }
        }
    }

    fn tokenize(&mut self) -> Result<Vec<Token>, TemplateError> {
        let mut tokens = Vec::new();
        let mut text = String::new();
        while self.pos < self.bytes.len() {
            if self.starts_with("\\{{") {
                // escaped mustache
                text.push_str("{{");
                self.pos += 3;
                continue;
            }
            if self.starts_with("{{") {
                if !text.is_empty() { tokens.push(Token::Text(std::mem::take(&mut text))); }
                let start = self.pos;
                let tag = self.parse_tag()?;
                tokens.push(Token::Tag(tag, start));
                continue;
            }
            let c = self.src[self.pos..].chars().next().unwrap();
            text.push(c);
            self.pos += c.len_utf8();
        }
        if !text.is_empty() { tokens.push(Token::Text(text)); }
        Ok(tokens)
    }

    const EXPR_EXPECT: &'static str = "expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline";

    fn parse_tag(&mut self) -> Result<Tag, TemplateError> {
        // at "{{"
        self.pos += 2;
        let mut raw = false;
        if self.peek() == Some(b'{') { raw = true; self.pos += 1; }
        let mut strip_l = false;
        if self.peek() == Some(b'~') { strip_l = true; self.pos += 1; }
        // comment
        if self.peek() == Some(b'!') {
            self.pos += 1;
            if self.starts_with("--") {
                match self.src[self.pos..].find("--") .and_then(|_| {
                    let rest = &self.src[self.pos + 2..];
                    rest.find("--}}").map(|i| self.pos + 2 + i)
                }) {
                    Some(end) => {
                        self.pos = end + 2;
                        let strip_r = if self.peek() == Some(b'~') { self.pos += 1; true } else { false };
                        if !self.starts_with("}}") { return Err(self.syntax(self.pos, "expected hbs_comment")); }
                        self.pos += 2;
                        return Ok(Tag::Comment { strip_l, strip_r });
                    }
                    None => return Err(self.syntax(self.src.len(), "expected hbs_comment")),
                }
            }
            match self.src[self.pos..].find("}}") {
                Some(i) => {
                    let inner = &self.src[self.pos..self.pos + i];
                    let strip_r = inner.ends_with('~');
                    self.pos += i + 2;
                    return Ok(Tag::Comment { strip_l, strip_r });
                }
                None => return Err(self.syntax(self.src.len(), "expected hbs_comment_compact")),
            }
        }
        let kind = match self.peek() {
            Some(b'#') => { self.pos += 1; 1 }
            Some(b'/') => { self.pos += 1; 2 }
            Some(b'^') => { self.pos += 1; 3 }
            Some(b'&') => { self.pos += 1; raw = true; 0 }
            Some(b'>') => { self.pos += 1; return Err(self.syntax(self.pos, "expected partial_expression")); }
            _ => 0,
        };
        self.skip_ws();
        if kind == 3 {
            // {{^}} else, or invalid
            if self.peek() == Some(b'~') { self.pos += 1; }
            if self.starts_with("}}") {
                self.pos += 2;
                return Ok(Tag::Else { chain: None, strip_l, strip_r: false });
            }
            return Err(self.syntax(self.pos, "expected keywords"));
        }
        if kind == 2 {
            // close tag
            let name_start = self.pos;
            let name = self.parse_ident_raw();
            if name.is_empty() { return Err(self.syntax(name_start, Self::EXPR_EXPECT)); }
            self.skip_ws();
            let strip_r = if self.peek() == Some(b'~') { self.pos += 1; true } else { false };
            if !self.starts_with("}}") { return Err(self.syntax(self.pos, "expected trailing_tilde_to_omit_whitespace")); }
            self.pos += 2;
            return Ok(Tag::Close { name, strip_l, strip_r });
        }
        // else tag?
        if kind == 0 && self.starts_with("else") {
            let after = self.bytes.get(self.pos + 4).copied();
            if after.map_or(true, |c| c.is_ascii_whitespace() || c == b'}' || c == b'~') {
                self.pos += 4;
                self.skip_ws();
                let chain = if self.starts_with("if") && self.bytes.get(self.pos + 2).map_or(false, |c| c.is_ascii_whitespace()) {
                    Some(self.parse_helper_expr(false)?.0)
                } else { None };
                self.skip_ws();
                let strip_r = if self.peek() == Some(b'~') { self.pos += 1; true } else { false };
                if !self.starts_with("}}") { return Err(self.syntax(self.pos, "expected trailing_tilde_to_omit_whitespace")); }
                self.pos += 2;
                return Ok(Tag::Else { chain, strip_l, strip_r });
            }
        }
        if kind == 0 && self.peek() == Some(b'}') {
            return Err(self.syntax(self.pos, Self::EXPR_EXPECT));
        }
        let (expr, block_params) = self.parse_helper_expr(kind == 1)?;
        self.skip_ws();
        let strip_r = if self.peek() == Some(b'~') { self.pos += 1; true } else { false };
        if raw && kind == 0 {
            if self.starts_with("}}}") { self.pos += 3; }
            else if self.starts_with("}}") { self.pos += 2; }
            else { return Err(self.syntax(self.pos, "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace")); }
        } else {
            if !self.starts_with("}}") {
                let msg = if kind == 1 { "expected identifier, helper_parameter, block_param, or trailing_tilde_to_omit_whitespace" } else { "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace" };
                return Err(self.syntax(self.pos, msg));
            }
            self.pos += 2;
        }
        if kind == 1 {
            Ok(Tag::Open { expr, block_params, strip_l, strip_r })
        } else {
            Ok(Tag::Expr { expr, raw, strip_l, strip_r })
        }
    }

    fn is_id_char(c: u8) -> bool {
        !(c.is_ascii_whitespace() || b"!\"#%&'()*+,./;<=>@[\\]^`{|}~".contains(&c))
    }

    fn parse_ident_raw(&mut self) -> String {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if Self::is_id_char(c) { self.pos += 1; } else { break; }
        }
        self.src[start..self.pos].to_string()
    }

    /// parse "name params... hash..." returning the expression and block params
    fn parse_helper_expr(&mut self, allow_block_params: bool) -> Result<(HelperExpr, Vec<String>), TemplateError> {
        self.skip_ws();
        let name_start = self.pos;
        let name = match self.parse_param()? {
            Some(Param::Path(p)) => p,
            Some(Param::Sub(s)) => {
                // subexpression as the expression itself, e.g. {{(foo)}}
                let _ = s;
                return Err(self.syntax(name_start, Self::EXPR_EXPECT));
            }
            _ => return Err(self.syntax(name_start, Self::EXPR_EXPECT)),
        };
        let mut params = Vec::new();
        let mut hash = Vec::new();
        let mut block_params = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => return Err(self.syntax(self.pos, "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace")),
                Some(b'}') | Some(b'~') => break,
                Some(b')') => break,
                _ => {}
            }
            // block params: as |a b|
            if allow_block_params && self.starts_with("as") && self.bytes.get(self.pos + 2).map_or(false, |c| c.is_ascii_whitespace()) {
                let save = self.pos;
                self.pos += 2;
                self.skip_ws();
                if self.peek() == Some(b'|') {
                    self.pos += 1;
                    loop {
                        self.skip_ws();
                        if self.peek() == Some(b'|') { self.pos += 1; break; }
                        let id = self.parse_ident_raw();
                        if id.is_empty() { return Err(self.syntax(self.pos, "expected block_param")); }
                        block_params.push(id);
                    }
                    continue;
                }
                self.pos = save;
            }
            // hash param?
            let save = self.pos;
            let id = self.parse_ident_raw();
            if !id.is_empty() && self.peek() == Some(b'=') {
                self.pos += 1;
                match self.parse_param()? {
                    Some(p) => hash.push((id, p)),
                    None => return Err(self.syntax(self.pos, "expected helper_parameter")),
                }
                continue;
            }
            self.pos = save;
            match self.parse_param()? {
                Some(p) => params.push(p),
                None => return Err(self.syntax(self.pos, "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace")),
            }
        }
        Ok((HelperExpr { name, params, hash }, block_params))
    }

    fn parse_param(&mut self) -> Result<Option<Param>, TemplateError> {
        self.skip_ws();
        let c = match self.peek() { Some(c) => c, None => return Ok(None) };
        match c {
            b'(' => {
                let start = self.pos;
                self.pos += 1;
                let (expr, _) = self.parse_helper_expr(false)?;
                self.skip_ws();
                if self.peek() != Some(b')') { return Err(self.syntax(self.pos, "expected helper_parameter")); }
                self.pos += 1;
                let _ = start;
                Ok(Some(Param::Sub(Box::new(expr))))
            }
            b'"' | b'\'' => {
                self.pos += 1;
                let mut s = String::new();
                loop {
                    match self.peek() {
                        None => return Err(self.syntax(self.pos, "expected string_literal")),
                        Some(b'\\') if self.bytes.get(self.pos + 1) == Some(&c) => { s.push(c as char); self.pos += 2; }
                        Some(ch) if ch == c => { self.pos += 1; break; }
                        Some(_) => {
                            let ch = self.src[self.pos..].chars().next().unwrap();
                            s.push(ch);
                            self.pos += ch.len_utf8();
                        }
                    }
                }
                Ok(Some(Param::Literal(Value::String(s))))
            }
            b'0'..=b'9' | b'-' => {
                let start = self.pos;
                if c == b'-' { self.pos += 1; }
                let mut seen_digit = false;
                while let Some(d) = self.peek() {
                    if d.is_ascii_digit() { self.pos += 1; seen_digit = true; }
                    else if d == b'.' && self.bytes.get(self.pos + 1).map_or(false, |x| x.is_ascii_digit()) { self.pos += 1; }
                    else { break; }
                }
                if !seen_digit {
                    // treat as path (e.g. "-foo")
                    self.pos = start;
                    return self.parse_path_param();
                }
                let text = &self.src[start..self.pos];
                // leading zero check like handlebars (InvalidParam)
                let digits = text.trim_start_matches('-');
                if digits.len() > 1 && digits.starts_with('0') && !digits.starts_with("0.") {
                    return Err(TemplateError { reason: TemplateErrorReason::InvalidParam(text.to_string()), template_name: None, line_no: None, column_no: None, segment: None });
                }
                let v: Value = if text.contains('.') {
                    serde_json::from_str(text).unwrap_or(Value::Null)
                } else {
                    match text.parse::<i64>() { Ok(i) => Value::from(i), Err(_) => Value::Null }
                };
                Ok(Some(Param::Literal(v)))
            }
            _ => self.parse_path_param(),
        }
    }

    fn parse_path_param(&mut self) -> Result<Option<Param>, TemplateError> {
        let start = self.pos;
        let mut segs = Vec::new();
        loop {
            // one segment
            if self.starts_with("../") {
                segs.push(Seg::Up);
                self.pos += 3;
            } else if self.starts_with("./") {
                segs.push(Seg::This);
                self.pos += 2;
            } else if self.peek() == Some(b'[') {
                match self.src[self.pos..].find(']') {
                    Some(i) => {
                        let lit = &self.src[self.pos + 1..self.pos + i];
                        segs.push(Seg::Key(lit.to_string()));
                        self.pos += i + 1;
                    }
                    None => return Err(self.syntax(self.pos, "expected path_id")),
                }
            } else if self.peek() == Some(b'@') {
                self.pos += 1;
                let id = self.parse_ident_raw();
                if id == "root" { segs.push(Seg::Root); } else { segs.push(Seg::Local(id)); }
            } else {
                let id = self.parse_ident_raw();
                if id.is_empty() {
                    if self.peek() == Some(b'.') && segs.is_empty() {
                        return Err(self.syntax(self.pos, Self::EXPR_EXPECT));
                    }
                    if segs.is_empty() { return Ok(None); }
                    return Err(self.syntax(self.pos, "expected path_id"));
                }
                if id == "this" { segs.push(Seg::This); } else { segs.push(Seg::Key(id)); }
            }
            // separator
            match self.peek() {
                Some(b'.') => {
                    self.pos += 1;
                    if self.starts_with("./") {
                        // "../" handled above; a single '.' followed by '/'? treat as this
                    }
                    if !self.peek().map_or(false, |c| Self::is_id_char(c) || c == b'[' || c == b'@' || c == b'.') {
                        return Err(self.syntax(self.pos, "expected path_id"));
                    }
                }
                Some(b'/') => { self.pos += 1; }
                _ => break,
            }
        }
        let raw = self.src[start..self.pos].to_string();
        match raw.as_str() {
            "true" => return Ok(Some(Param::Literal(Value::Bool(true)))),
            "false" => return Ok(Some(Param::Literal(Value::Bool(false)))),
            "null" | "undefined" => return Ok(Some(Param::Literal(Value::Null))),
            _ => {}
        }
        Ok(Some(Param::Path(Path { segs, raw })))
    }
}

const BLOCK_EXPECT: &str = "expected escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact";

pub fn compile(src: &str, name: &str) -> Result<Template, TemplateError> {
    let mut p = Parser { src, bytes: src.as_bytes(), pos: 0, name: name.to_string() };
    let mut tokens = p.tokenize()?;
    apply_whitespace(&mut tokens, src);
    let mut idx = 0;
    let elements = build_elements(&p, &mut tokens, &mut idx, None)?;
    Ok(Template { name: name.to_string(), elements })
}

/// whitespace control (~) and standalone-line stripping
fn apply_whitespace(tokens: &mut Vec<Token>, src: &str) {
    let n = tokens.len();
    // standalone detection first
    for i in 0..n {
        let (is_block_tag, strip_l, strip_r) = match &tokens[i] {
            Token::Tag(Tag::Open { strip_l, strip_r, .. }, _) => (true, *strip_l, *strip_r),
            Token::Tag(Tag::Close { strip_l, strip_r, .. }, _) => (true, *strip_l, *strip_r),
            Token::Tag(Tag::Else { strip_l, strip_r, .. }, _) => (true, *strip_l, *strip_r),
            Token::Tag(Tag::Comment { strip_l, strip_r }, _) => (true, *strip_l, *strip_r),
            _ => (false, false, false),
        };
        let _ = (strip_l, strip_r, src);
        if !is_block_tag { continue; }
        // previous text must be empty-or-whitespace back to a newline (or start)
        let prev_ok = if i == 0 { true } else {
            match &tokens[i - 1] {
                Token::Text(t) => {
                    let tail = t.rsplit('\n').next().unwrap();
                    let only_ws = tail.chars().all(|c| c == ' ' || c == '\t');
                    only_ws && (t.contains('\n') || i == 1)
                }
                _ => false,
            }
        };
        let next_ok = if i + 1 >= n { true } else {
            match &tokens[i + 1] {
                Token::Text(t) => {
                    let head = t.split('\n').next().unwrap();
                    let only_ws = head.chars().all(|c| c == ' ' || c == '\t' || c == '\r');
                    only_ws && (t.contains('\n') || i + 2 == n)
                }
                _ => false,
            }
        };
        if prev_ok && next_ok {
            if i > 0 {
                if let Token::Text(t) = &mut tokens[i - 1] {
                    let cut = t.rfind('\n').map(|p| p + 1).unwrap_or(0);
                    t.truncate(cut);
                }
            }
            if i + 1 < n {
                if let Token::Text(t) = &mut tokens[i + 1] {
                    let cut = t.find('\n').map(|p| p + 1).unwrap_or(t.len());
                    *t = t[cut..].to_string();
                }
            }
        }
    }
    // tilde stripping
    for i in 0..n {
        let (strip_l, strip_r) = match &tokens[i] {
            Token::Tag(Tag::Expr { strip_l, strip_r, .. }, _) => (*strip_l, *strip_r),
            Token::Tag(Tag::Open { strip_l, strip_r, .. }, _) => (*strip_l, *strip_r),
            Token::Tag(Tag::Close { strip_l, strip_r, .. }, _) => (*strip_l, *strip_r),
            Token::Tag(Tag::Else { strip_l, strip_r, .. }, _) => (*strip_l, *strip_r),
            Token::Tag(Tag::Comment { strip_l, strip_r }, _) => (*strip_l, *strip_r),
            _ => (false, false),
        };
        if strip_l && i > 0 {
            if let Token::Text(t) = &mut tokens[i - 1] {
                let trimmed = t.trim_end().len();
                t.truncate(trimmed);
            }
        }
        if strip_r && i + 1 < n {
            if let Token::Text(t) = &mut tokens[i + 1] {
                *t = t.trim_start().to_string();
            }
        }
    }
}

fn build_elements(p: &Parser, tokens: &mut Vec<Token>, idx: &mut usize, open: Option<(&str, usize)>) -> Result<Vec<Element>, TemplateError> {
    let mut out = Vec::new();
    while *idx < tokens.len() {
        let tok = std::mem::replace(&mut tokens[*idx], Token::Text(String::new()));
        *idx += 1;
        match tok {
            Token::Text(t) => { if !t.is_empty() { out.push(Element::Text(t)); } }
            Token::Tag(Tag::Comment { .. }, _) => {}
            Token::Tag(Tag::Expr { expr, .. }, off) => {
                let (line, col) = p.line_col(off);
                out.push(Element::Expr { expr, pos: Pos { line, col } });
            }
            Token::Tag(Tag::Open { expr, block_params, .. }, off) => {
                let name = expr.name.raw.clone();
                let (line, col) = p.line_col(off);
                let body = build_elements(p, tokens, idx, Some((&name, off)))?;
                // after body, idx points past either an Else or Close tag; we stored the else info in a side channel
                let mut inverse = None;
                // check what terminated the body
                let term = std::mem::replace(&mut tokens[*idx - 1], Token::Text(String::new()));
                match term {
                    Token::Tag(Tag::Close { .. }, _) => {}
                    Token::Tag(Tag::Else { chain, .. }, else_off) => {
                        // parse inverse until close
                        let mut chain_expr = chain;
                        let mut chain_off = else_off;
                        let mut inv = Vec::new();
                        loop {
                            let part = build_elements(p, tokens, idx, Some((&name, off)))?;
                            let term2 = std::mem::replace(&mut tokens[*idx - 1], Token::Text(String::new()));
                            match (chain_expr.take(), term2) {
                                (None, Token::Tag(Tag::Close { .. }, _)) => { inv = part; break; }
                                (None, Token::Tag(Tag::Else { .. }, eoff)) => {
                                    return Err(p.syntax(eoff + 2, "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace"));
                                }
                                (Some(ce), Token::Tag(Tag::Close { .. }, _)) => {
                                    let (l2, c2) = p.line_col(chain_off);
                                    inv = vec![Element::Block { expr: ce, block_params: vec![], body: part, inverse: None, pos: Pos { line: l2, col: c2 } }];
                                    break;
                                }
                                (Some(ce), Token::Tag(Tag::Else { chain: c3, .. }, eoff)) => {
                                    // nested chain: wrap recursively
                                    let (l2, c2) = p.line_col(chain_off);
                                    let mut nested_inverse = Vec::new();
                                    // build subsequent parts
                                    let mut rest_chain = c3;
                                    let mut rest_off = eoff;
                                    let mut chain_items: Vec<(HelperExpr, Vec<Element>, Pos)> = vec![(ce, part, Pos { line: l2, col: c2 })];
                                    loop {
                                        let part2 = build_elements(p, tokens, idx, Some((&name, off)))?;
                                        let term3 = std::mem::replace(&mut tokens[*idx - 1], Token::Text(String::new()));
                                        match (rest_chain.take(), term3) {
                                            (None, Token::Tag(Tag::Close { .. }, _)) => { nested_inverse = part2; break; }
                                            (None, Token::Tag(Tag::Else { .. }, eoff2)) => {
                                                return Err(p.syntax(eoff2 + 2, "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace"));
                                            }
                                            (Some(ce2), Token::Tag(Tag::Close { .. }, _)) => {
                                                let (l3, c3b) = p.line_col(rest_off);
                                                chain_items.push((ce2, part2, Pos { line: l3, col: c3b }));
                                                break;
                                            }
                                            (Some(ce2), Token::Tag(Tag::Else { chain: c4, .. }, eoff2)) => {
                                                let (l3, c3b) = p.line_col(rest_off);
                                                chain_items.push((ce2, part2, Pos { line: l3, col: c3b }));
                                                rest_chain = c4;
                                                rest_off = eoff2;
                                            }
                                            _ => unreachable!(),
                                        }
                                    }
                                    // fold chain items from the end
                                    let mut acc: Option<Vec<Element>> = if nested_inverse.is_empty() { None } else { Some(nested_inverse) };
                                    for (e, b, ps) in chain_items.into_iter().rev() {
                                        acc = Some(vec![Element::Block { expr: e, block_params: vec![], body: b, inverse: acc, pos: ps }]);
                                    }
                                    inv = acc.unwrap_or_default();
                                    break;
                                }
                                _ => unreachable!(),
                            }
                        }
                        let _ = chain_off;
                        chain_off = 0;
                        let _ = chain_off;
                        inverse = Some(inv);
                    }
                    _ => unreachable!(),
                }
                out.push(Element::Block { expr, block_params, body, inverse, pos: Pos { line, col } });
            }
            Token::Tag(Tag::Close { name, .. }, off) => {
                match open {
                    Some((oname, _)) => {
                        if oname != name {
                            return Err(p.error(off, TemplateErrorReason::MismatchingClosedHelper(oname.to_string(), name)));
                        }
                        // put the token back so caller can see the terminator
                        tokens[*idx - 1] = Token::Tag(Tag::Close { name, strip_l: false, strip_r: false }, off);
                        return Ok(out);
                    }
                    None => return Err(p.syntax(off + 2, Parser::EXPR_EXPECT)),
                }
            }
            Token::Tag(Tag::Else { chain, .. }, off) => {
                match open {
                    Some(_) => {
                        tokens[*idx - 1] = Token::Tag(Tag::Else { chain, strip_l: false, strip_r: false }, off);
                        return Ok(out);
                    }
                    None => return Err(p.syntax(off + 2, "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace")),
                }
            }
        }
    }
    if open.is_some() {
        return Err(p.syntax(p.src.len(), BLOCK_EXPECT));
    }
    Ok(out)
}

// ----------------------------------------------------------------------
// Rendering

pub struct RenderError {
    pub desc: String,
    pub pos: Pos,
    pub template: String,
}

impl std::fmt::Display for RenderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Error rendering \"{}\" line {}, col {}: {}", self.template, self.pos.line, self.pos.col, self.desc)
    }
}

struct BlockCtx {
    /// context value for this block level (None for blocks like #if that don't change context)
    ctx: Option<Value>,
    locals: BTreeMap<String, Value>,
    block_params: BTreeMap<String, Value>,
}

struct Renderer<'a> {
    root: &'a Value,
    blocks: Vec<BlockCtx>,
    template_name: &'a str,
}

type HResult = Result<Value, String>;

fn is_truthy(v: &Value, include_zero: bool) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => {
            if include_zero { true } else { n.as_f64().map_or(false, |f| f != 0.0) }
        }
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

pub fn render_json(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => String::new(),
        Value::Array(a) => {
            let mut buf = String::from("[");
            for (i, item) in a.iter().enumerate() {
                if i > 0 { buf.push_str(", "); }
                buf.push_str(&render_json(item));
            }
            buf.push(']');
            buf
        }
        Value::Object(_) => "[object]".to_string(),
    }
}

fn compare_json(x: &Value, y: &Value) -> Option<std::cmp::Ordering> {
    fn cmp_num_str(a: &serde_json::Number, b: &str) -> Option<std::cmp::Ordering> {
        let a = a.as_f64()?;
        let b: f64 = b.parse().ok()?;
        a.partial_cmp(&b)
    }
    match (x, y) {
        (Value::Number(a), Value::Number(b)) => a.as_f64()?.partial_cmp(&b.as_f64()?),
        (Value::Number(a), Value::String(b)) => cmp_num_str(a, b),
        (Value::String(a), Value::Number(b)) => cmp_num_str(b, a).map(|o| o.reverse()),
        (Value::String(a), Value::String(b)) => a.partial_cmp(b),
        (Value::Bool(a), Value::Bool(b)) => a.partial_cmp(b),
        (Value::Null, Value::Null) => Some(std::cmp::Ordering::Equal),
        _ => None,
    }
}

const FBLOG_HELPERS: &[&str] = &["bold", "red", "green", "yellow", "blue", "cyan", "purple", "color_rgb", "uppercase", "fixed_size", "min_size", "level_style"];
const BUILTIN_HELPERS: &[&str] = &["eq", "ne", "gt", "gte", "lt", "lte", "and", "or", "not", "len", "lookup", "log", "if", "unless", "each", "with", "raw"];

fn is_helper(name: &str) -> bool {
    FBLOG_HELPERS.contains(&name) || BUILTIN_HELPERS.contains(&name)
}

fn param_index_required(helper: &str, idx: usize) -> String {
    format!("Helper/Decorator {} param at index {} required but not found", helper, idx)
}
fn param_name_required(helper: &str, name: &str) -> String {
    format!("Helper/Decorator {} param with name {} required but not found", helper, name)
}
fn param_type_mismatch(helper: &str, name: &str, tpe: &str) -> String {
    format!("Helper/Decorator {} param with name {} type mismatch for {}", helper, name, tpe)
}

fn get_str<'v>(helper: &str, params: &'v [Value], idx: usize, name: &str) -> Result<&'v str, String> {
    let v = params.get(idx).ok_or_else(|| param_name_required(helper, name))?;
    v.as_str().ok_or_else(|| param_type_mismatch(helper, name, "str"))
}

fn get_u64(helper: &str, params: &[Value], idx: usize, name: &str) -> Result<u64, String> {
    let v = params.get(idx).ok_or_else(|| param_name_required(helper, name))?;
    v.as_u64().ok_or_else(|| param_type_mismatch(helper, name, "u64"))
}

fn style_wrap(code: &str, t: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", code, t)
}

pub fn level_style(level: &str) -> String {
    let style = match level.trim().to_lowercase().as_str() {
        "trace" => Paint::new(level).cyan().bold(),
        "debug" => Paint::new(level).blue().bold(),
        "info" => Paint::new(level).green().bold(),
        "warn" => Paint::new(level).yellow().bold(),
        "error" | "err" => Paint::new(level).red().bold(),
        _ => Paint::new(level).magenta().bold(),
    };
    style.to_string()
}

fn fixed_size(size: u64, t: &str) -> String {
    let mut s = t.to_string();
    if s.len() > size as usize {
        s.truncate(size as usize);
        s
    } else {
        min_size(size, &s)
    }
}

fn min_size(size: u64, t: &str) -> String {
    let n = size as usize;
    if t.len() >= n { return t.to_string(); }
    format!("{}{}", " ".repeat(n - t.len()), t)
}

fn color_rgb(r: u64, g: u64, b: u64, t: &str) -> String {
    let r: u8 = r.try_into().unwrap(); let g: u8 = g.try_into().unwrap(); let b: u8 = b.try_into().unwrap();
    Paint::new(t).rgb(r, g, b).to_string()
}

impl<'a> Renderer<'a> {
    fn current_ctx(&self) -> &Value {
        for b in self.blocks.iter().rev() {
            if let Some(c) = &b.ctx { return c; }
        }
        self.root
    }

    /// context `levels` up (number of "../")
    fn ctx_at_level(&self, levels: usize) -> Option<&Value> {
        // collect contexts: root + those of blocks that set a context
        let mut stack: Vec<&Value> = vec![self.root];
        for b in &self.blocks {
            if let Some(c) = &b.ctx { stack.push(c); }
        }
        let depth = stack.len() - 1;
        if depth == 0 { return Some(self.root); }
        if levels > depth { return None; }
        Some(stack[depth - levels])
    }

    fn lookup_local(&self, name: &str, up: usize) -> Value {
        // find the block level that owns locals, going up `up` context-changing blocks
        let mut skip = up;
        for b in self.blocks.iter().rev() {
            if b.ctx.is_some() {
                if skip == 0 {
                    return b.locals.get(name).cloned().unwrap_or(Value::Null);
                }
                skip -= 1;
            } else if skip == 0 && !b.locals.is_empty() {
                if let Some(v) = b.locals.get(name) { return v.clone(); }
            }
        }
        Value::Null
    }

    fn resolve_path(&self, path: &Path) -> Value {
        let mut segs = path.segs.iter().peekable();
        let mut up = 0usize;
        while let Some(Seg::Up) = segs.peek() { segs.next(); up += 1; }
        // block params take precedence (only at level 0)
        if up == 0 {
            if let Some(Seg::Key(k)) = segs.peek() {
                for b in self.blocks.iter().rev() {
                    if let Some(v) = b.block_params.get(k.as_str()) {
                        let mut cur = v.clone();
                        segs.next();
                        for s in segs { cur = step(&cur, s); }
                        return cur;
                    }
                }
            }
        }
        let mut cur: Value = match segs.peek() {
            Some(Seg::Root) => { segs.next(); self.root.clone() }
            Some(Seg::Local(name)) => {
                let name = name.clone();
                segs.next();
                self.lookup_local(&name, up)
            }
            _ => match self.ctx_at_level(up) { Some(v) => v.clone(), None => return Value::Null },
        };
        for s in segs {
            cur = step(&cur, s);
        }
        cur
    }

    fn eval_param(&mut self, p: &Param, pos: &Pos) -> Result<Value, RenderError> {
        match p {
            Param::Literal(v) => Ok(v.clone()),
            Param::Path(path) => Ok(self.resolve_path(path)),
            Param::Sub(expr) => {
                let name = &expr.name.raw;
                if !is_helper(name) {
                    return Err(self.err(format!("Helper not found {}", name), pos));
                }
                let params = self.eval_params(&expr.params, pos)?;
                let hash = self.eval_hash(&expr.hash, pos)?;
                self.call_inline_helper(name, &params, &hash).map_err(|d| self.err(d, pos))
            }
        }
    }

    fn eval_params(&mut self, params: &[Param], pos: &Pos) -> Result<Vec<Value>, RenderError> {
        params.iter().map(|p| self.eval_param(p, pos)).collect()
    }

    fn eval_hash(&mut self, hash: &[(String, Param)], pos: &Pos) -> Result<BTreeMap<String, Value>, RenderError> {
        let mut m = BTreeMap::new();
        for (k, p) in hash { m.insert(k.clone(), self.eval_param(p, pos)?); }
        Ok(m)
    }

    fn err(&self, desc: String, pos: &Pos) -> RenderError {
        RenderError { desc, pos: pos.clone(), template: self.template_name.to_string() }
    }

    fn call_inline_helper(&mut self, name: &str, params: &[Value], _hash: &BTreeMap<String, Value>) -> HResult {
        let s = |x: String| Ok(Value::String(x));
        match name {
            "bold" => s(style_wrap("1", get_str(name, params, 0, "t")?)),
            "red" => s(style_wrap("31", get_str(name, params, 0, "t")?)),
            "green" => s(style_wrap("32", get_str(name, params, 0, "t")?)),
            "yellow" => s(style_wrap("33", get_str(name, params, 0, "t")?)),
            "blue" => s(style_wrap("34", get_str(name, params, 0, "t")?)),
            "purple" => s(style_wrap("35", get_str(name, params, 0, "t")?)),
            "cyan" => s(style_wrap("36", get_str(name, params, 0, "t")?)),
            "color_rgb" => {
                let r = get_u64(name, params, 0, "r")?;
                let g = get_u64(name, params, 1, "g")?;
                let b = get_u64(name, params, 2, "b")?;
                let t = get_str(name, params, 3, "t")?;
                s(color_rgb(r, g, b, t))
            }
            "uppercase" => s(get_str(name, params, 0, "t")?.to_uppercase()),
            "fixed_size" => {
                let n = get_u64(name, params, 0, "isize")?;
                let t = get_str(name, params, 1, "t")?;
                s(fixed_size(n, t))
            }
            "min_size" => {
                let n = get_u64(name, params, 0, "isize")?;
                let t = get_str(name, params, 1, "t")?;
                s(min_size(n, t))
            }
            "level_style" => s(level_style(get_str(name, params, 0, "level")?)),
            "len" => {
                let v = params.get(0).ok_or_else(|| param_name_required(name, "x"))?;
                let n = match v { Value::Array(a) => a.len(), Value::Object(o) => o.len(), Value::String(st) => st.len(), _ => 0 };
                Ok(Value::from(n as u64))
            }
            "eq" | "ne" | "gt" | "gte" | "lt" | "lte" => {
                let x = params.get(0).ok_or_else(|| param_index_required(name, 0))?;
                let y = params.get(1).ok_or_else(|| param_index_required(name, 1))?;
                use std::cmp::Ordering::*;
                let r = match name {
                    "eq" => x == y,
                    "ne" => x != y,
                    "gt" => compare_json(x, y) == Some(Greater),
                    "gte" => matches!(compare_json(x, y), Some(Greater) | Some(Equal)),
                    "lt" => compare_json(x, y) == Some(Less),
                    _ => matches!(compare_json(x, y), Some(Less) | Some(Equal)),
                };
                Ok(Value::Bool(r))
            }
            "and" => Ok(Value::Bool(params.iter().all(|p| is_truthy(p, false)))),
            "or" => Ok(Value::Bool(params.iter().any(|p| is_truthy(p, false)))),
            "not" => {
                let x = params.get(0).ok_or_else(|| param_index_required(name, 0))?;
                Ok(Value::Bool(!is_truthy(x, false)))
            }
            "lookup" => {
                let obj = params.get(0).ok_or_else(|| param_index_required(name, 0))?;
                let key = params.get(1).ok_or_else(|| param_index_required(name, 1))?;
                Ok(match (obj, key) {
                    (Value::Array(a), Value::Number(n)) => n.as_u64().and_then(|i| a.get(i as usize)).cloned().unwrap_or(Value::Null),
                    (Value::Object(o), Value::String(k)) => o.get(k).cloned().unwrap_or(Value::Null),
                    _ => Value::Null,
                })
            }
            "log" => Ok(Value::Null),
            "if" | "unless" | "each" | "with" | "raw" => Ok(Value::Null),
            _ => Err(format!("Helper not found {}", name)),
        }
    }

    fn render_elements(&mut self, elements: &[Element], out: &mut String) -> Result<(), RenderError> {
        for e in elements { self.render_element(e, out)?; }
        Ok(())
    }

    fn render_element(&mut self, e: &Element, out: &mut String) -> Result<(), RenderError> {
        match e {
            Element::Text(t) => { out.push_str(t); Ok(()) }
            Element::Expr { expr, pos } => {
                let name = &expr.name.raw;
                let simple = expr.name.segs.len() == 1 && matches!(expr.name.segs[0], Seg::Key(_));
                if simple && is_helper(name) {
                    let params = self.eval_params(&expr.params, pos)?;
                    let hash = self.eval_hash(&expr.hash, pos)?;
                    let v = self.call_inline_helper(name, &params, &hash).map_err(|d| self.err(d, pos))?;
                    out.push_str(&render_json(&v));
                    return Ok(());
                }
                if !expr.params.is_empty() || !expr.hash.is_empty() {
                    return Err(self.err(format!("Helper not found {}", name), pos));
                }
                let v = self.resolve_path(&expr.name);
                out.push_str(&render_json(&v));
                Ok(())
            }
            Element::Block { expr, block_params, body, inverse, pos } => {
                let name = expr.name.raw.clone();
                let params = self.eval_params(&expr.params, pos)?;
                let hash = self.eval_hash(&expr.hash, pos)?;
                match name.as_str() {
                    "if" | "unless" => {
                        let helper_name = "if";
                        let cond = params.get(0).ok_or_else(|| self.err(param_index_required(helper_name, 0), pos))?;
                        let include_zero = hash.get("includeZero").map_or(false, |v| v == &Value::Bool(true));
                        let mut t = is_truthy(cond, include_zero);
                        if name == "unless" { t = !t; }
                        self.blocks.push(BlockCtx { ctx: None, locals: BTreeMap::new(), block_params: BTreeMap::new() });
                        let r = if t { self.render_elements(body, out) } else if let Some(inv) = inverse { self.render_elements(inv, out) } else { Ok(()) };
                        self.blocks.pop();
                        r
                    }
                    "each" => {
                        let v = params.get(0).ok_or_else(|| self.err(param_index_required("each", 0), pos))?.clone();
                        match &v {
                            Value::Array(items) if !items.is_empty() => {
                                let n = items.len();
                                for (i, item) in items.iter().enumerate() {
                                    let mut locals = BTreeMap::new();
                                    locals.insert("index".to_string(), Value::from(i as u64));
                                    locals.insert("first".to_string(), Value::Bool(i == 0));
                                    locals.insert("last".to_string(), Value::Bool(i + 1 == n));
                                    let mut bp = BTreeMap::new();
                                    if let Some(p0) = block_params.get(0) { bp.insert(p0.clone(), item.clone()); }
                                    if let Some(p1) = block_params.get(1) { bp.insert(p1.clone(), Value::from(i as u64)); }
                                    self.blocks.push(BlockCtx { ctx: Some(item.clone()), locals, block_params: bp });
                                    let r = self.render_elements(body, out);
                                    self.blocks.pop();
                                    r?;
                                }
                                Ok(())
                            }
                            Value::Object(map) if !map.is_empty() => {
                                let n = map.len();
                                for (i, (k, item)) in map.iter().enumerate() {
                                    let mut locals = BTreeMap::new();
                                    locals.insert("index".to_string(), Value::from(i as u64));
                                    locals.insert("key".to_string(), Value::String(k.clone()));
                                    locals.insert("first".to_string(), Value::Bool(i == 0));
                                    locals.insert("last".to_string(), Value::Bool(i + 1 == n));
                                    let mut bp = BTreeMap::new();
                                    if let Some(p0) = block_params.get(0) { bp.insert(p0.clone(), item.clone()); }
                                    if let Some(p1) = block_params.get(1) { bp.insert(p1.clone(), Value::String(k.clone())); }
                                    self.blocks.push(BlockCtx { ctx: Some(item.clone()), locals, block_params: bp });
                                    let r = self.render_elements(body, out);
                                    self.blocks.pop();
                                    r?;
                                }
                                Ok(())
                            }
                            _ => {
                                if let Some(inv) = inverse { self.render_elements(inv, out) } else { Ok(()) }
                            }
                        }
                    }
                    "with" => {
                        let v = params.get(0).ok_or_else(|| self.err(param_index_required("with", 0), pos))?.clone();
                        if is_truthy(&v, false) {
                            let mut bp = BTreeMap::new();
                            if let Some(p0) = block_params.get(0) { bp.insert(p0.clone(), v.clone()); }
                            self.blocks.push(BlockCtx { ctx: Some(v), locals: BTreeMap::new(), block_params: bp });
                            let r = self.render_elements(body, out);
                            self.blocks.pop();
                            r
                        } else if let Some(inv) = inverse {
                            self.render_elements(inv, out)
                        } else { Ok(()) }
                    }
                    "raw" => self.render_elements(body, out),
                    _ => Err(self.err(format!("Helper not found {}", name), pos)),
                }
            }
        }
    }
}

fn step(cur: &Value, s: &Seg) -> Value {
    match s {
        Seg::This => cur.clone(),
        Seg::Up => Value::Null,
        Seg::Root => Value::Null,
        Seg::Local(_) => Value::Null,
        Seg::Key(k) => match cur {
            Value::Object(o) => o.get(k).cloned().unwrap_or(Value::Null),
            Value::Array(a) => k.parse::<usize>().ok().and_then(|i| a.get(i)).cloned().unwrap_or(Value::Null),
            _ => Value::Null,
        },
    }
}

impl Template {
    pub fn render(&self, ctx: &Value) -> Result<String, RenderError> {
        let mut r = Renderer { root: ctx, blocks: Vec::new(), template_name: &self.name };
        let mut out = String::new();
        r.render_elements(&self.elements, &mut out)?;
        Ok(out)
    }
}
