        _ => unreachable!(),
    }
}

fn parse_body(p: &Parser, tokens: &mut Vec<Token>, idx: &mut usize, open: Option<(&str, usize)>) -> Result<(Vec<Element>, Term), TemplateError> {
    let mut out = Vec::new();
    while *idx < tokens.len() {
        let tok = std::mem::replace(&mut tokens[*idx], Token::Text(String::new()));
        *idx += 1;
        match tok {
            Token::Text(t) => { if !t.is_empty() { out.push(Element::Text(t)); } }
            Token::Tag(Tag::Comment { .. }, _) => {}
            Token::Tag(Tag::Expr { expr, .. }, off) => {
                let (line, col) = p.line_col(off);
                out.push(Element::Expr { expr, pos: Pos { line, col } });
            }
            Token::Tag(Tag::Open { expr, block_params, .. }, off) => {
                let name = expr.name.raw.clone();
                let (line, col) = p.line_col(off);
                let (body, term) = parse_body(p, tokens, idx, Some((&name, off)))?;
                let inverse = match term {
                    Term::Close { .. } => None,
                    Term::Else { chain, off: eoff } => Some(parse_inverse(p, tokens, idx, &name, off, chain, eoff)?),
                    Term::Eof => return Err(p.syntax(p.src.len(), BLOCK_EXPECT)),
                };
                out.push(Element::Block { expr, block_params, body, inverse, pos: Pos { line, col } });
            }
            Token::Tag(Tag::Close { name, .. }, off) => {
                match open {
                    Some((oname, _)) => {
                        if oname != name {
                            return Err(p.error(off, TemplateErrorReason::MismatchingClosedHelper(oname.to_string(), name)));
                        }
                        return Ok((out, Term::Close { off, name }));
                    }
                    None => return Err(p.syntax(off + 2, Parser::EXPR_EXPECT)),
                }
            }
            Token::Tag(Tag::Else { chain, .. }, off) => {
                match open {
                    Some(_) => return Ok((out, Term::Else { chain, off })),
                    None => return Err(p.syntax(off + 2, "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace")),
                }
            }
        }
    }
    if open.is_some() {
        return Err(p.syntax(p.src.len(), BLOCK_EXPECT));
    }
    Ok((out, Term::Eof))
}

fn parse_inverse(p: &Parser, tokens: &mut Vec<Token>, idx: &mut usize, name: &str, open_off: usize, chain: Option<HelperExpr>, else_off: usize) -> Result<Vec<Element>, TemplateError> {
    let (part, term) = parse_body(p, tokens, idx, Some((name, open_off)))?;
    match chain {
        None => match term {
            Term::Close { .. } => Ok(part),
            Term::Else { off, .. } => Err(p.syntax(off + 2, "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace")),
            Term::Eof => Err(p.syntax(p.src.len(), BLOCK_EXPECT)),
        },
        Some(ce) => {
            let inner = match term {
                Term::Close { .. } => None,
                Term::Else { chain: c2, off: o2 } => Some(parse_inverse(p, tokens, idx, name, open_off, c2, o2)?),
                Term::Eof => return Err(p.syntax(p.src.len(), BLOCK_EXPECT)),
            };
            let (line, col) = p.line_col(else_off);
            Ok(vec![Element::Block { expr: ce, block_params: vec![], body: part, inverse: inner, pos: Pos { line, col } }])
        }
    }
}

