//! Placeholder substitution in log messages.

use regex::Regex;
use serde_json::{Map, Value};

pub struct Substitution {
    pub context_key: String,
    regex: Regex,
    prefix: String,
    suffix: String,
}

const KEY_PATTERN: &str = "([a-zA-Z0-9_|-]+)";

fn dim(s: &str) -> String { format!("\x1b[2m{}\x1b[0m", s) }
fn bold(s: &str) -> String { format!("\x1b[1m{}\x1b[0m", s) }
fn bold_color(code: &str, s: &str) -> String { format!("\x1b[1;{}m{}\x1b[0m", code, s) }
fn magenta(s: &str) -> String { format!("\x1b[35m{}\x1b[0m", s) }

impl Substitution {
    pub fn new(context_key: &str, placeholder_format: &str) -> Result<Substitution, String> {
        let idx = match placeholder_format.find("key") {
            Some(i) => i,
            None => return Err("The identifier `key` is missing".to_string()),
        };
        let prefix = placeholder_format[..idx].to_string();
        let suffix = placeholder_format[idx + 3..].to_string();
        let pattern = format!("{}{}{}", regex::escape(&prefix), KEY_PATTERN, regex::escape(&suffix));
        let regex = Regex::new(&pattern).map_err(|e| e.to_string())?;
        Ok(Substitution { context_key: context_key.to_string(), regex, prefix, suffix })
    }

    pub fn apply(&self, message: &str, log: &Map<String, Value>) -> String {
        let context = match log.get(&self.context_key) {
            Some(c) => c,
            None => return message.to_string(),
        };
        let mut out = String::new();
        let mut last = 0;
        for cap in self.regex.captures_iter(message) {
            let whole = cap.get(0).unwrap();
            let key = cap.get(1).unwrap().as_str();
            out.push_str(&message[last..whole.start()]);
            let value = match context {
                Value::Object(map) => map.get(key),
                Value::Array(items) => key.parse::<usize>().ok().and_then(|i| items.get(i)),
                _ => None,
            };
            match value {
                Some(v) => out.push_str(&render_value(v)),
                None => {
                    out.push_str(&dim(&self.prefix));
                    out.push_str(&bold_color("31", key));
                    out.push_str(&dim(&self.suffix));
                }
            }
            last = whole.end();
        }
        out.push_str(&message[last..]);
        out
    }
}

fn render_value(v: &Value) -> String {
    match v {
        Value::Null => bold("null"),
        Value::Bool(true) => bold_color("32", "true"),
        Value::Bool(false) => bold_color("31", "false"),
        Value::Number(n) => bold_color("36", &n.to_string()),
        Value::String(s) => bold_color("33", s),
        Value::Array(items) => {
            let mut out = dim("[");
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push_str(&dim(", ")); }
                out.push_str(&render_value(item));
            }
            out.push_str(&dim("]"));
            out
        }
        Value::Object(map) => {
            let mut out = dim("{");
            for (i, (k, item)) in map.iter().enumerate() {
                if i > 0 { out.push_str(&dim(", ")); }
                out.push_str(&magenta(k));
                out.push_str(&dim(": "));
                out.push_str(&render_value(item));
            }
            out.push_str(&dim("}"));
            out
        }
    }
}
