//! Log entry processing: value extraction, flattening and printing.

use crate::filter::Filter;
use crate::substitution::Substitution;
use crate::template::Template;
use serde_json::{Map, Value};
use std::collections::HashMap;

pub struct Options {
    pub message_keys: Vec<String>,
    pub time_keys: Vec<String>,
    pub level_keys: Vec<String>,
    pub level_map: HashMap<String, String>,
    pub dump_all: bool,
    pub dump_all_exclude: Vec<String>,
    pub always_print_fields: Vec<String>,
    pub with_prefix: bool,
    pub filter: Option<Filter>,
    pub substitution: Option<Substitution>,
    pub main_line: Template,
    pub additional_value: Template,
}

fn bold_red(s: &str) -> String { format!("\x1b[1;31m{}\x1b[0m", s) }
fn red(s: &str) -> String { format!("\x1b[31m{}\x1b[0m", s) }
fn bold_orange(s: &str) -> String { format!("\x1b[1;38;2;255;135;22m{}\x1b[0m", s) }

/// Extract the first key whose value is a string, number or bool.
fn get_string_value(log: &Map<String, Value>, keys: &[String]) -> Option<String> {
    for k in keys {
        match log.get(k) {
            Some(Value::String(s)) => return Some(s.clone()),
            Some(Value::Number(n)) => return Some(n.to_string()),
            Some(Value::Bool(b)) => return Some(b.to_string()),
            _ => {}
        }
    }
    None
}

pub fn format_timestamp(raw: &str) -> String {
    let ts: i64 = match raw.parse() {
        Ok(v) => v,
        Err(_) => return raw.to_string(),
    };
    let secs = chrono::DateTime::from_timestamp(ts, 0);
    let millis = chrono::DateTime::from_timestamp_millis(ts);
    let now = chrono::Utc::now();
    let chosen = match (secs, millis) {
        (Some(s), Some(m)) => {
            let ds = (s - now).num_milliseconds().unsigned_abs();
            let dm = (m - now).num_milliseconds().unsigned_abs();
            if ds <= dm { Some(s) } else { Some(m) }
        }
        (Some(s), None) => Some(s),
        (None, Some(m)) => Some(m),
        (None, None) => None,
    };
    match chosen {
        Some(dt) => dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
        None => raw.to_string(),
    }
}

pub fn flatten(prefix: &str, value: &Map<String, Value>, out: &mut Vec<(String, String)>) {
    for (k, v) in value {
        let key = if prefix.is_empty() { k.clone() } else { format!("{} > {}", prefix, k) };
        match v {
            Value::Object(m) => flatten(&key, m, out),
            Value::Array(items) => flatten_array(&key, items, true, out),
            Value::Null => {}
            Value::String(s) => out.push((key, s.clone())),
            other => out.push((key, other.to_string())),
        }
    }
}

fn flatten_array(key: &str, items: &[Value], zero_based: bool, out: &mut Vec<(String, String)>) {
    for (i, e) in items.iter().enumerate() {
        let idx = if zero_based { i } else { i + 1 };
        let ekey = format!("{}[{}]", key, idx);
        match e {
            Value::Object(m) => flatten(&ekey, m, out),
            Value::Array(inner) => flatten_array(&ekey, inner, false, out),
            other => out.push((ekey, other.to_string())),
        }
    }
}

fn key_matches(field: &str, key: &str) -> bool {
    key == field || key.starts_with(&format!("{} > ", field)) || key.starts_with(&format!("{}[", field))
}

impl Options {
    pub fn process_line(&self, raw_line: &str) {
        let line = raw_line.trim_end_matches(['\n', '\r']);
        let (prefix, json_str) = if self.with_prefix {
            match line.find('{') {
                Some(i) => (Some(line[..i].trim().to_string()), &line[i..]),
                None => (None, line),
            }
        } else {
            (None, line)
        };
        match serde_json::from_str::<Map<String, Value>>(json_str) {
            Ok(log) => {
                if let Some(filter) = &self.filter {
                    match filter.apply(&log) {
                        Ok(true) => {}
                        Ok(false) => return,
                        Err(e) => {
                            eprintln!("{}: '{}'", red("Failed to apply filter expression"), e);
                            return;
                        }
                    }
                }
                self.print_log_line(&log, prefix);
            }
            Err(_) => {
                println!("{} {}", bold_orange("??? >"), line);
            }
        }
    }

    fn print_log_line(&self, log: &Map<String, Value>, prefix: Option<String>) {
        let timestamp = get_string_value(log, &self.time_keys).map(|t| format_timestamp(&t));
        let level = get_string_value(log, &self.level_keys)
            .map(|l| self.level_map.get(&l).cloned().unwrap_or(l))
            .unwrap_or_else(|| "unknown".to_string());
        let message = get_string_value(log, &self.message_keys).map(|m| match &self.substitution {
            Some(s) => s.apply(&m, log),
            None => m,
        });

        let mut context = log.clone();
        context.insert("fblog_timestamp".into(), timestamp.map(Value::String).unwrap_or(Value::Null));
        context.insert("fblog_level".into(), Value::String(level));
        context.insert("fblog_message".into(), message.map(Value::String).unwrap_or(Value::Null));
        context.insert("fblog_prefix".into(), prefix.filter(|p| !p.is_empty()).map(Value::String).unwrap_or(Value::Null));

        match self.main_line.render(&Value::Object(context)) {
            Ok(s) => println!("{}", s),
            Err(e) => eprintln!("{} Failed to process line: {}", bold_red("??? >"), e),
        }

        let mut flattened = Vec::new();
        flatten("", log, &mut flattened);
        if self.dump_all {
            for (k, v) in &flattened {
                if self.dump_all_exclude.iter().any(|x| x == k) { continue; }
                self.print_additional(k, v);
            }
        } else {
            for field in &self.always_print_fields {
                for (k, v) in &flattened {
                    if key_matches(field, k) { self.print_additional(k, v); }
                }
            }
        }
    }

    fn print_additional(&self, key: &str, value: &str) {
        let mut ctx = Map::new();
        ctx.insert("key".into(), Value::String(key.to_string()));
        ctx.insert("value".into(), Value::String(value.to_string()));
        match self.additional_value.render(&Value::Object(ctx)) {
            Ok(s) => println!("{}", s),
            Err(e) => eprintln!("{} Failed to process additional value: {}", bold_red("   ??? >"), e),
        }
    }
}
