{"command":"cd /workspace; cat > src/main.rs <<'EOF'
//! fblog - a small tool to view json log files.
//!
//! This is an original re-implementation written from observed behaviour.

mod cli;
mod config;
mod filter;
mod lua;
mod process;
mod substitution;
mod template;

use std::io::{BufRead, BufReader};

fn collect_values(matches: &clap::ArgMatches, name: &str) -> Vec<String> {
    matches
        .get_many::<String>(name)
        .map(|v| v.cloned().collect())
        .unwrap_or_default()
}

fn stdin_reader() -> Box<dyn BufRead> {
    Box::new(BufReader::new(std::io::stdin()))
}

fn file_reader(path: &str) -> Box<dyn BufRead> {
    let file = open_file(path);
    Box::new(BufReader::new(file))
}

fn main() {
    let matches = cli::app().get_matches();

    let mut config = match matches.get_one::<String>("config-file") {
        Some(path) => config::load_config_file(path).expect("Could not load config file."),
        None => config::load_default_config(),
    };

    let mut message_keys = collect_values(&matches, "message-key");
    message_keys.append(&mut config.message_keys);
    let mut time_keys = collect_values(&matches, "time-key");
    time_keys.append(&mut config.time_keys);
    let mut level_keys = collect_values(&matches, "level-key");
    level_keys.append(&mut config.level_keys);

    let mut always_print_fields = config.always_print_fields.clone();
    always_print_fields.extend(collect_values(&matches, "additional-value"));

    let excluded = collect_values(&matches, "excluded-value");
    let dump_all = matches.get_flag("dump-all") || !excluded.is_empty();
    let mut dump_all_exclude = config.dump_all_exclude.clone();
    dump_all_exclude.extend(excluded);

    let mut level_map = config.level_map.clone();
    if let Some(levels) = matches.get_many::<(String, String)>("map-level") {
        for (from, to) in levels {
            level_map.insert(from.clone(), to.clone());
        }
    }

    let substitution = if matches.get_flag("substitute")
        || matches.contains_id("context-key")
        || matches.contains_id("placeholder-format")
    {
        let context_key = matches.get_one::<String>("context-key").map(|s| s.as_str());
        let placeholder = matches.get_one::<String>("placeholder-format").map(|s| s.as_str());
        match substitution::Substitution::new(context_key.unwrap_or("context"), placeholder.unwrap_or("{key}")) {
            Err(e) => panic!("Invalid placeholder format: {}", e),
            Ok(s) => Some(s),
        }
    } else {
        None
    };

    let filter = matches.get_one::<String>("filter").map(|expr| filter::Filter {
        expression: expr.clone(),
        implicit_return: !matches.get_flag("no-implicit-filter-return-statement"),
        print_lua: matches.get_flag("print-lua"),
    });

    let main_line_format = matches
        .get_one::<String>("main-line-format")
        .cloned()
        .unwrap_or(config.main_line_format.clone());
    let additional_value_format = matches
        .get_one::<String>("additional-value-format")
        .cloned()
        .unwrap_or(config.additional_value_format.clone());
    let (main_line, additional_value) = template::compile_templates(&main_line_format, &additional_value_format);

    let options = process::Options {
        message_keys,
        time_keys,
        level_keys,
        level_map,
        dump_all,
        dump_all_exclude,
        always_print_fields,
        with_prefix: matches.get_flag("with-prefix"),
        filter,
        substitution,
        main_line,
        additional_value,
    };

    let input = matches.get_one::<String>("INPUT").map(|s| s.as_str()).unwrap_or("-");
    let reader = if input == "-" { stdin_reader() } else { file_reader(input) };
    run(reader, &options);
}

fn open_file(path: &str) -> std::fs::File {
    std::fs::File::open(path).unwrap_or_else(|_| panic!("Can't open file: {}", path))
}

fn run(mut reader: Box<dyn BufRead>, options: &process::Options) {
    let mut buffer = String::new();
    loop {
        buffer.clear();
        match reader.read_line(&mut buffer) {
            Ok(0) => break,
            Ok(_) => options.process_line(&buffer),
            Err(e) => {
                println!("{} Could not read line: {}", "\x1b[1;31m??? >\x1b[0m", e);
            }
        }
    }
}
