        message_keys,
        time_keys,
        level_keys,
        level_map,
        dump_all,
        dump_all_exclude,
        always_print_fields,
        with_prefix: matches.get_flag("with-prefix"),
        filter,
        substitution,
        main_line,
        additional_value,
    };

    let input = matches.get_one::<String>("INPUT").map(|s| s.as_str()).unwrap_or("-");
    let reader = if input == "-" { stdin_reader() } else { file_reader(input) };
    run(reader, &options);
}

fn open_file(path: &str) -> std::fs::File {
    std::fs::File::open(path).unwrap_or_else(|_| panic!("Can't open file: {}", path))
}

fn run(mut reader: Box<dyn BufRead>, options: &process::Options) {
    let mut buffer = String::new();
    loop {
        buffer.clear();
        match reader.read_line(&mut buffer) {
            Ok(0) => break,
            Ok(_) => options.process_line(&buffer),
            Err(e) => {
                println!("{} Could not read line: {}", "\x1b[1;31m??? >\x1b[0m", e);
            }
        }
    }
}
