/// Truncation happens on byte boundaries; like the original implementation this
/// aborts when the cut would fall inside a multi-byte character.
fn fixed_size(size: u64, t: &str) -> String {
    let n = size as usize;
    let mut s = t.to_string();
    match s.len().cmp(&n) {
        std::cmp::Ordering::Less => {
            // pad on the left
            s = min_size(size, &s);
        }
        std::cmp::Ordering::Equal => {}
        std::cmp::Ordering::Greater => {
            // cut off the end of the string
            s.truncate(n);
        }
    }
    s
}

// ----------------------------------------------------------------------
// Template compilation

/// Compile both templates, aborting (like the original) on invalid templates.
///
/// The main line template is rendered once per log entry with the parsed JSON
/// object plus the `fblog_*` variables as context. The additional value
/// template is rendered for every printed key/value pair with `key` and
/// `value` as context.
///
/// A template that does not parse is a configuration error. The message
/// contains the position of the problem inside the template so that it can
/// be fixed easily. There is no way to recover from it, hence the panic.
///
/// The templates are named `main_line` and `additional_value`; these names
/// show up in rendering error messages.
///
/// Errors while rendering (e.g. an unknown helper or a type mismatch of a
/// helper parameter) are not fatal and are reported per line instead.
pub fn compile_templates(main_line_format: &str, additional_value_format: &str) -> (Template, Template) {
    let main_template = compile(&main_line_format, "main_line").expect("Template invalid");
    let additional_template = compile(
        &additional_value_format, "additional_value")
        .expect("Template invalid");
    (main_template, additional_template)
}

