const C_STDIO_BUFSIZ: usize = 4096;

/// Buffered write emulating C stdio's fully buffered stdout.
pub fn lua_stdout_write(bytes: &[u8]) {
    LUA_STDOUT.with(|b| {
        let mut b = b.borrow_mut();
        b.extend_from_slice(bytes);
    });
    let len = LUA_STDOUT.with(|b| b.borrow().len());
    if len >= C_STDIO_BUFSIZ { lua_stdout_flush(); }
}

pub fn lua_stdout_flush() {
    use std::io::Write;
    let data = LUA_STDOUT.with(|b| std::mem::take(&mut *b.borrow_mut()));
    if data.is_empty() { return; }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(&data);
    let _ = lock.flush();
}'''
