    fn call_lua_function(&mut self, mut func: FuncRef, mut args: Vec<Value>, mut name: CallName, mut is_tail: bool) -> LResult<Vec<Value>> {
        // stack accounting: the callee's base is after the caller's active registers
        let advance = 1 + self.frames.last().map_or(0, |f| f.active_locals);
