                let v = check_num(it, &args, argi)?; argi += 1;
                let spec = check_format(it, &form, FMT_FLAGS_F, true)?;
                let upper = conv.is_ascii_uppercase();
                let alt = spec.flags.contains(&b'#');
                let mut body = match conv.to_ascii_lowercase() {
                    b'a' => fmt_a(v.abs(), spec.precision, upper),
                    b'e' => fmt_e(v.abs(), spec.precision.unwrap_or(6), upper),
                    b'f' => fmt_f(v.abs(), spec.precision.unwrap_or(6), upper),
                    _ => fmt_g(v.abs(), spec.precision.unwrap_or(6), upper, alt),
                };
                if alt && conv.to_ascii_lowercase() == b'f' && spec.precision == Some(0) { body.push('.'); }
                let neg = v.is_sign_negative();
                let sign = if neg { "-" } else if spec.flags.contains(&b'+') { "+" } else if spec.flags.contains(&b' ') { " " } else { "" };
