                let spec = check_format(it, &form, FMT_FLAGS_C, false)?;
                let s = match &v {
                    Value::Table(t) => format!("{:p}", Rc::as_ptr(t)),
                    Value::Func(f) => format!("{:p}", Rc::as_ptr(f)),
                    Value::Str(s) => format!("{:p}", Rc::as_ptr(s)),
                    _ => "(null)".to_string(),
                };
                out.extend_from_slice(pad_field(&spec, s, false).as_bytes());
            }
            b'q' => {
                if form.len() != 2 { return Err(it.lib_error("specifier '%q' cannot have modifiers")); }
                let v = check_any(it, &args, argi)?; argi += 1;
