                    } else {
                        let mut st = String::from_utf8_lossy(&s).into_owned();
                        if let Some(p) = spec.precision { if p < s.len() { st = String::from_utf8_lossy(&s[..p]).into_owned(); } }
                        out.extend_from_slice(pad_field(&spec, st, false).as_bytes());
                    }
                }
            }
            _ => {
                return Err(it.lib_error(&format!("invalid conversion '{}' to 'format'", form)));
            }
        }
    }
    Ok(vec![Value::bytes(out)])
}

